    "biography": "袁绍次子，袁谭之弟，袁尚之兄。为甄氏之夫。\n\n演：幽州刺史。护卫败给曹操的袁尚。在曹操供攻略幽州时，和袁尚一起逃亡投靠辽西的乌丸。在曹操进攻乌丸时，则转而投靠辽东的公孙康，却惨遭公孙康的暗算，同袁尚皆被斩首送给了曹操。\n\n史：乌丸的蹋顿特别为了援救袁熙，和曹操一战。\n\n",
