    "biography": "後改名为艳，为韩遂的女婿。\n\n演：没有记载。\n\n史：年少时就加入韩遂，和马腾一战中大勝了马超。２０９年，以韩遂的使者身份前访曹操，返回後说服韩遂归顺曹操却未被接受。２１１年，阻止韩遂跟马超联手出兵未果，在马超败逃後，和韩遂一起进入金城。韩遂为断绝他与曹操之间的关係，将自己的么女许配成婚。不料最後还是攻打韩遂，投向了曹操军。\n\n",
