    "biography": "袁绍的堂弟（一说为異母弟），为四世三公的名门。\n\n演：曾被何进所重用，何进被宦官暗杀後，联合袁绍一同屠杀宦官。在董卓势力抬头时逃往南阳，参加反董卓联盟。後移往淮南，拿著孙策让给的玉玺自称为皇帝。由於恶政而失去民心，靠著袁绍北上之际受到刘备攻击，吐血而亡。\n\n史：何进死後立即欲染指帝位，和企图拥立刘虞为帝的袁绍对立。虽然和公孙瓒、陶谦和孙坚等人联合，却在匡亭被袁绍派的曹操所败，逃亡扬州。\n\n",
