    "biography": "袁术的堂兄（一说为亲兄），为四世三公的名门，曹操之友。\n\n演：曾被何进重用，在何进被宦官暗杀後，开始屠杀宦官。当董卓掌握实权後逃往渤海，响应曹操的呼籲並成为反董卓联盟的盟主。在联盟解散後，从同联盟的韩馥手中夺取冀州，打倒公孙瓒後支配河北地方。虽一时获得了最大势力，却在官渡之战大败给曹操。企图復权而发动的仓亭之战却又败北，便在未决定後继者的情况下病死。\n\n史：企图和韩馥推举刘虞即位却被拒绝。並也拒绝了郭图拥护献帝的提案。\n\n",
