    "biography": "袁术的幕僚。\n\n演：在袁术意图自立为帝时，以「至於文王，三分天下有其二，犹以服事殷」的周文王的故事劝谏。然而袁术却相信「代汉者，当塗高也（字公路，和「途」的意思相应）」的民间说法，並未聽从劝谏。\n\n史：１９５年，献帝被李傕等人追赶，袁术企图谋篡皇位之际，於是提出周文王的故事劝谏。但於１９７年，袁术仍以瑞兆降临为由而自命为帝。\n\n",
