    "biography": "袁绍长子，袁熙、袁绍之兄。\n\n演：青州刺史。袁绍死後兄弟一同对抗曹操，却为了争夺继承者之位和袁尚对立。屈於劣势时曾向刘表请求援军遭拒，而向曹操投降。但却擅自夺取被曹操赶跑的袁尚领地，激怒了曹操驱使进攻南皮。再次提出投降却遭拒，在準备出击时为曹洪所讨。\n\n史：受到刘备的推薦下成为茂才。在投降曹操後，其女和曹操之子曹整成亲。在南皮之战中遭到曹纯讨伐。\n\n",
