    "biography": "张鲁的幕僚。\n\n演：向张鲁进言夺取蜀汉自立为王。在刘璋遭受刘备进攻之时，劝谏张鲁答应刘璋的援军要求。汉中受到曹操攻击时和庞德抗战，制止了受贿而欲屈於曹操军的杨松。但最後却未能阻止聽从杨松提案的张鲁而败北。遂同张鲁降於曹操。\n\n史：曹丕即位後爵位跟领地受增，但却在约十年後病死。\n\n",
