    "biography": "刘表的武将。\n\n演：在蔡瑁图谋暗杀刘备时，和文聘共担引赵雲離开刘备的任务。刘表死後，在刘琮打算投降曹操之时，献上在曹操入城时予以奇袭的策略，却不被接受。陪同刘琮前往青州赴任时，在途中被曹操所命的于禁所讨。\n\n史：曾向刘琮进言，趁曹操南下大意时杀了他，却没有被採用。没有同刘琮一起被杀害的记载。\n\n",
