    "biography": "赵昂之妻。原为益州刺史赵伟璋之妻。\n\n演：在马超杀死韦康夺取冀城之後，姜叙、杨阜、尹奉等人计劃讨伐马超。对於因担心马超阵营中的兒子赵月而迟迟无法下决心参加的丈夫，谏言为旧主韦康復仇的一事较重要。在姜叙等人举兵出征时，投下私产以慰劳士兵。在马超袭击历城之际，尹奉和赵昂一族皆被杀害，而从军的王異却逃过一劫。\n\n史：智谋过人，在赵昂所提出的策略中也都有参与。投资慰劳防禦马超攻击的冀城士兵。\n\n",
