    "biography": "东汉司徒。被誉为「一日千里，王佐之才也」的名士。\n\n演：在董卓掌握实权後不久，曾赠与七星宝刀给志願暗杀董卓的曹操。在董卓的恶政为人无所忍受时，策劃了利用貂蝉的美女连环计。挑拨董卓的心腹吕布，使其杀了董卓。之後，为了替董卓復仇的李傕等人举兵攻入时，拒绝了吕布的劝告留在长安，一族皆被杀光。\n\n史：参加镇压黄巾黨，虐杀宦官计劃。拉拢吕布却不使用美人计。甚至还处死感叹董卓死亡的蔡邕。展现種種无情的一面。\n\n",
