    "biography": "魏之武将。历任安平太守、荆州刺史等职。\n\n演：是聽到管辂的评價並使其占卜的人物之一。在司马师讨伐毌丘俭时以监军身份同行。提议制服毌丘俭之前应先压制南顿城，使战局导向有利。之後为镇南将军，也参与司马昭讨伐诸葛诞之行。击破朱異、唐咨攻进寿春城，镇压了叛乱。\n\n史：琅邪留学归回後，服侍王淩。劝谏曹叡建造宫殿。当曹芳即位，曹爽掌握实权时，著有「时要论」批判时代倾向。\n\n",
