    "biography": "魏国天水太守。\n\n演：曾参加邓艾讨伐蜀国之行。和牵弘设置伏兵大破诸葛瞻，攻陷绵竹。在邓艾压制成都之後，和牵弘同被封为益州各郡的太守。\n\n史：参加毌丘俭的东方远征，並历任东方诸郡的太守。此外，曾受和邻国纷争的倭国女王卑弥呼的邀请，促使两国和解。\n\n",
