    "biography": "东汉河内太守。\n\n演：响应曹操呼籲反董卓联合的诸侯之一。在军事会议上提议应该立谁为盟主，最後是袁绍担任。担任攻打虎牢关的先锋，但大将方悦却被吕布所杀，陷於窘困之际为桥瑁和袁遗所救。\n\n史：以乐善好施闻名，被何进招揽旗下。在败给董卓之後，回到泰山和张邈会合，最终被曹操所杀。\n\n",
