    "biography": "魏国雍州刺史。为平民出身的名士。\n\n演：２５５年，北伐姜维失败被包围在狄道城时，得到陈泰和邓艾的救援。劝阻曹髦提出的司马昭暗杀计劃，但曹髦並不聽劝。後因拒绝与王业、王沈一同投诚司马昭，而和母亲一同被捕。其母笑说终於死得其所後，二人便遭处刑並满门抄斩。\n\n史：曾受崔林提拔。母亲曾对他说出头太快並不吉利，但仍然继续升进。被处刑的只有王经，母亲平安无事。\n\n",
