    "biography": "建安七子之一。曾祖父、祖父皆为三公的名门之後。\n\n演：年纪轻轻才能就受到蔡邕评價。为了避开战乱前往荆州依靠刘表。在刘表死後刘琮继位时，和傅巽同主张向曹操投降。侍奉之後对曹操感到敬佩万分，在铜雀台落成时还咏唱了称赞曹操的诗。之後和杜袭、卫凯、和洽欲拥立曹操为魏王，却被荀攸阻止。\n\n史：相貌不出众，身體贫弱加上大而化之的个性，並不受刘表重用。在魏建国後成为侍中。记忆力过人，致力於朝廷的旧制度復兴以及奏议起草。\n\n",
