    "biography": "袁家之臣，後侍奉曹操。\n\n演：袁绍死後，因劝谏企图谋杀袁尚的袁谭而遭解职。当袁谭被曹操所杀後，打破禁令对袁谭表示哀悼。被曹操任命为司金中郎将。\n\n史：在侍奉北海太守孔融後，为袁绍、袁谭臣子。侍奉曹操後以魏郡太守立下功绩。魏建国後成为大司农郎中令，死於任职期间。\n\n",
