    "biography": "王浑（和玄冲不同人）之子。为竹林七贤的最年少者。\n\n演：晋国建威将军。参与２７９年的吴国讨伐战。进军武昌，和先进入石头城的王濬会合。\n\n史：年少时就发挥他不输给大人的聪明才智。因锺会的推薦受到司马懿重用。历任河东太守、荆州刺史等职。在晋惠帝时成为司徒。不过並不关心政务只执著於自己的利益。\n\n",
