    "biography": "王朗之子，魏国黄门侍郎。\n\n演：２３０年上奏劝退进攻蜀国因大雨而身陷苦战的曹真和司马懿。毌丘俭反叛时，提出善待反叛军的家族以降低士气的策略（吕蒙讨伐关羽时所用）给司马师。司马师死後，向曹髦进言封司马昭爵位。其女嫁给司马昭为妻，生下司马炎、司马攸。\n\n史：１８岁时从宋忠学习「太玄经」。历任广平太守、侍中、太常等。反郑玄学说为「尚书」「诗经」等加注解，並仿作「孔子家语」。\n\n",
