    "biography": "晋国益州刺史。\n\n演：陆抗死後，上奏讨伐吴国。２７９年，吴国讨伐战时受任龙骧将军，同唐彬从益州沿长江而下进攻。吴国的岑昏为了防止晋军的舰队，在水中设置了铁锥，却遭筏子作战所破壞。在石头城击败张象，降服了孙皓。之後和杜预、司马[0xFA][0x40]等人会合完全平定吴国，因此功绩而受封为辅国大将军。\n\n史：於吴国讨伐战中和王浑互争功绩。\n\n",
