    "biography": "魏国太尉。为二十四孝之一，留下了卧冰求鲤的故事。\n\n演：目送邓艾和锺会出发讨伐蜀国的其中一人。同时，从刘寔聽到邓艾和锺会可能无法活著回来的预言。在司马昭为了选择继承人而困惑之时，进言说不要破壞长幼有序的伦理，於是司马昭选择了司马炎。\n\n史：为了避开东汉末期的动乱，和母弟一起移往庐江隐居三十多年。在母亲死後，受到吕虔的邀请出仕。在曹髦掌权的时候就任光禄勋、司空。因为讨伐毌丘俭的功劳被认命为太常。在晋朝司马炎的时候被任命为太保。\n\n",
