    "biography": "魏国武将。身高九尺，操使60斤的大剃刀、内含铁芯的弓箭以及流星锤的猛将。和参加曹仁的进攻濡须而败给朱桓的王双是不同人。\n\n演：在诸葛亮的第二次北伐，曹真向曹叡的推薦而受到提拔。攻击包围陈仓的蜀军，击败谢雄、龚起，並使张嶷身负重伤。虽然蜀军从陈仓撤退後给予追击，却被魏延给砍死。\n\n史：在诸葛亮的第二次北伐中，率领骑兵攻击因为粮食耗尽而撤退的诸葛亮军，战死。\n\n",
