    "biography": "曹操的武将。\n\n演：同刘岱攻击佔领徐州的刘备。关羽被捕但刘备却被释放，受委託前去和曹操斡旋。返回许昌时虽险被盛怒的曹操处死，由於孔融的助言，只被剥夺爵位和俸禄而留下一命。\n\n史：攻击守护荆州的娄圭後，归顺曹操。年轻时曾经过著挨饿受苦的日子，这些事情被曹丕聽到，便成为日後被嘲笑的题材。\n\n",
