    "biography": "王浑之父，魏国征南大将军。\n\n演：２５２年，在司马昭趁孙权死去向吴国进攻时，担任攻击江陵方面。因友方的胡遵被丁奉打败而撤退。\n\n史：和王淩並称名士，视王淩为兄跟随在侧。为曹丕的太子文学，在曹丕即位後从事开拓荒地，升为兖州刺史。当曹叡下达推举人才的诏令时，被司马懿所推举。因为镇压毌丘俭的反叛而被封为骠骑将军，而後担任司空。提倡法律制度的宽容化，並且著作「治论」和「兵书」等书。\n\n",
