    "biography": "蜀国武将。原为魏国牙门将。\n\n演：在汉中攻防战中为徐晃的副先锋，却因与徐晃不和而向蜀军投降。之後，参加南蛮讨伐战及诸葛亮的北伐。在街亭之战受命为马谡的辅佐，未能劝阻独自行动的马谡。在诸葛亮的遗言中，列为忠义之士中之一人。\n\n史：原名何平。在街亭的撤退战防止了敌军的追击，是诸多降格的将领中唯一升级的人。在讨伐反叛的魏延後，历任汉中太守、前将军、镇北大将军，负责汉中方面的防守。\n\n",
