    "biography": "王肃之父，东汉会稽太守。\n\n演：同严白虎和孙策对战而败，之後改仕曹操。曹丕当权时任御史大夫，和华歆等人要胁献帝让位。因此份功绩成为司空，在曹叡掌权时当上司徒。诸葛亮北伐中夏侯楙败北时，推薦曹真並且自己也从军。在打头阵和诸葛亮展开论战时败北，气愤而死。\n\n史：通经书，曾被陶谦招揽成为会稽太守。被曹操招揽後，从曲阿往返长江和大海之间，花费数年时间才上京。並未记载随曹真从军与诸葛亮论战败北一事，而是终寿正寝。\n\n",
