    "biography": "东汉大将军·何进之孙，曹爽的心腹。\n\n演：曹叡死後曹芳掌权，就向曹爽进言夺取司马懿的政权。在曹爽政权下当上尚书，却被管辂看穿其死期将至。司马懿讨伐曹爽夺下政权後，被逮捕並以谋反罪处死。\n\n史：母亲尹氏为曹操的侧室，所以是在魏的宫廷中成长。可是不被曹丕和曹叡所喜而未受到重用。是个清谈家喜欢老莊思想，著有「老子道德论」等为玄学的代表者。「论语集解」也是何晏的著作。\n\n",
