    "biography": "蒯良之弟，刘表的幕僚。通晓观马相术。\n\n演：应袁绍的要求，同蔡瑁準备偷袭藏有玉玺的孙坚，却被孙坚给脱逃。在刘备让出的卢给刘表之际，曾进言这是不吉的象徵务请退还。之後，也参与蔡瑁的暗杀刘备计劃。刘表死後看出曹操南下的行动，於是对继承者刘琮进言投降。並对曹操说与其得到荆州，不如得到蒯越有利。\n\n史：曾为刘表所问何谓统治策略时回答说，平时要将仁爱道义放在第一，但在乱世谋策也是必要的。侍奉曹操後，成为光禄勋。\n\n",
