    "biography": "蒯越之兄，刘表的幕僚。通晓观马相术。\n\n演：在孙坚攻打荆州时，向刘表进言最好向袁绍请求援军。反对这个策略的蔡瑁出战失利後，强烈主张将其处刑。由天象看到将星陨落，就献计与吕公讨伐孙坚。当孙策提议拿人质的黄祖来交换孙坚的遗體时，进言即使对黄祖见死不救也要先攻下江东。可是，重用黄祖的刘表答应跟孙策交涉。\n\n史：刘表为了镇压宗贼的军队聚集兵力时，提倡只有信义仁爱才是统治之道。\n\n",
