    "biography": "吴国武将。\n\n演：赤壁之战结束後，立即同宋宪护卫出征合淝的孙权。刘备为了和孙权之妹成婚前往甘露寺时，奉孙权和吕範的命令派兵埋伏。準备如果吴国太不满意刘备的话，就砍下刘备的手，结果这件事被刘备察觉。反惹火了中意刘备的吴国太而差点被处刑，因刘备请命而逃过一劫。\n\n史：没有记载。\n\n",
