    "biography": "吴国之臣，韦昭的好友。\n\n演：蜀灭亡时，向孙休提议必须强化防禦的體制。当孙皓即位打算进攻晋时，主张与其出兵必须先以德治民。却惹火了孙皓被赶走，感叹「可惜啊，如此美的国土，不久也将成为别人的吧」。\n\n史：文章学识受到相当的评價，在孙皓当权时担任右国史，和韦昭、薛莹等人共编撰「吴书」。劝谏孙皓的状书达百次以上，在韦昭被处刑时也抗议到最後。推举了众多人才。\n\n",
