    "biography": "贾习之孙，贾充之父。魏国谏议大夫。\n\n演：曹操死後曾经建议曹彰，应该率领大军到京城取回兵权。之後成为豫州刺史负责戒备江东。在周鲂向曹休投降时，看穿以假投降引诱出曹休的计谋，但是曹休並未聽信。中计出征的曹休在石亭败北时，便假装伏兵埋伏，藉以阻止吴国的追击，救了曹休。\n\n史：从祖父身上学习兵法。在曹操讨伐马超的时候，被提拔为弘农太守。之後，成为豫州刺史整顿运河，並在征讨吴国时在洞浦击败吕範。\n\n",
