    "biography": "黄巾武将。\n\n演：和黄邵、何曼等人在汝南、潁川诸郡作乱。因为曹操军的进攻而逃走，被还是在野之士的许褚所捕，在许褚加入曹操军後被引渡，随後被斩首。\n\n史：和刘辟、黄邵、何曼等人各自拥有数万兵力，接近袁术以及孙坚。１９６年，被曹操所攻，刘辟和黄邵皆被斩首，但只有何仪连同军队一起投降，而没有被斩首的记载。\n\n",
