    "biography": "东汉豫章太守。之後服侍孙策、曹操。\n\n演：向进军江东的孙策投降。赤壁之战後，以孙权的使者派遣到曹操的手下，就这样被留下。之後，当伏完的曹操暗杀计劃曝光後，便奉曹操之命抓回伏皇后。在曹操死後，威胁献帝让位给曹丕。在曹叡时代成为太尉，褫夺有反叛嫌疑的司马懿的兵权。\n\n史：孙策死後，被曹操所招，魏建国後历任御史大夫、司徒。在演义中是为皇帝皇后所使声名狼藉的恶人，但是在正史中是个拥有清廉人格的人。\n\n",
