    "biography": "李傕、郭汜的参谋。之後服侍张绣、曹操。\n\n演：董卓死後，向李傕等人进言夺取长安拥立献帝。在夺回长安後为了献帝四处奔走，在献帝逃離长安之後成为张绣的部下。曾夜袭正对邹氏献殷勤的曹操等，多次让曹操军吃到苦头。在官渡之战前，说服张绣向曹操投降。在渭水之战中所策劃的離间计，成功地使马超和韩遂失和。在曹操苦恼於选择继承人之时，向曹操进言应该选择曹丕。在曹丕即位後成为太尉。\n\n史：被阎忠评论为足以和张良、陈平匹敌的策士。\n\n",
