    "biography": "魏国谋臣·郭嘉之子。\n\n演：郭嘉死後，被引领到曹操府中。\n\n史：在郭嘉病死之际便继承父亲之後。当上太子文学没多久後就死去。相识亲近的王昶评论其为「单纯，理解力强且博学。缺点是度量不够大，尊敬或轻蔑别人的状况非常極端。希望自己的兒子不要变得像这样」。不过裴松之却说王昶的批评太过偏颇，並说将友人的恶评流传後世是有反道义的行为。\n\n",
