    "biography": "董卓的武将，幼名阿多。\n\n演：在董卓入军洛阳时从军。董卓死後，同李傕攻陷长安，並拥献帝掌握政权。然而妒心强的妻子被杨彪所利用，使得和李傕之间反目成仇。虽然在张济的斡旋下和李傕重修旧好，但是献帝却逃出长安並受到曹操保护。和李傕同被曹操讨伐，成为山贼之後被部下伍习所杀。\n\n史：郭汜之妻见丈夫经常在李家过夜，害怕失去丈夫的宠爱，就计劃使两人反目成仇。並非杨彪所计谋。\n\n",
