    "biography": "袁术的武将。\n\n演：打著皇帝名号的袁术掀起吕布讨伐战时，担任督战官负责全七军的连络。但是因为陈珪亲子之计使得韩暹和杨奉反叛，进而使袁术军大败。之後马上受到曹操的攻击，虽然和梁纲、李豊、陈纪等人守卫寿春，四人却同被逮捕，並在市场中被斩首。\n\n史：在曹操亲自迎击入侵陈的袁术时，袁术弃军而逃。奉袁术命令和桥、李豊、梁纲等人一起留下，却被曹操击破被于禁斩首。\n\n",
