    "biography": "霍弋之父。原为刘表武将，後改仕刘备。\n\n演：受到孟达向正在进攻益州的刘备推举。和孟达两人守卫葭萌关，受到张鲁旗下的马超进攻时曾向刘备要求援军。即使正同曹操展开汉中攻防战时也依然死守葭萌关。在黄忠和严颜的救援之前，防止了张郃的攻击。\n\n史：刘表死後归顺刘备。虽然受到刘璋军的扶禁、向存等人包围葭萌关，仍孤军奋战守关一整年，甚至反将向存斩首。在刘备平定益州後任梓潼太守，却未能参加汉中攻防战便死去。\n\n",
