    "biography": "魏国武将。\n\n演：因司马懿的推举负责守卫陈仓。诸葛亮第二次北伐时对战，将诸葛亮开发的兵器烧光成功地守住城。王双及时来援，在蜀军一度撤退後染上了重病。聽到蜀军再次来袭火攻陈仓城後，遂导致病情恶化而死。\n\n史：在曹叡时代，镇压在西平反叛的麴英。从诸葛亮手中防卫了陈仓的功勋被列侯所赞誉，不久後病死。並未记载诸葛亮的再次袭击陈仓，以及郝昭因此而死的事。\n\n",
