    "biography": "曹操的武将，乐綝之父。\n\n演：在曹操举兵时从军，随後转战各地。在袁家讨伐战中射杀郭图，和李典等人攻陷高幹所防守的壶关。赤壁之战後，同李典成为张辽的副将共防合淝。在逍遥津一战故意败退引诱孙权军深入，致使张辽的奇袭成功。之後於濡须口和凌统交锋，受到凌统追击时被甘寧的箭射中而归阵。\n\n史：身材瘦小却骁勇果断。和张辽、于禁、张郃、徐晃並列齐名的名将。在官渡之战将淳于琼斩首。\n\n",
