    "biography": "魏国武将。乐进之子。\n\n演：为曹真的副先锋，同先锋的张虎共战诸葛亮的北伐军。祁山一战中未能破诸葛亮的阵势被俘，以赤裸裸一身並在脸上塗墨後才被释放。诸葛亮的北伐结束後，参加公孙渊的讨伐战。之後成为扬州刺史。接受贾充的密函企图除掉有反叛嫌疑的诸葛诞，不料被诸葛诞发现而被下手杀死。\n\n史：如同父亲的刚毅性格，容貌也很相似。死後追封为卫尉。\n\n",
