    "biography": "袁绍的参谋。袁绍死後服侍袁谭。\n\n演：官渡之战前，作为袁绍的臣子被问及是否和曹操开战时，主张开战。在刘备投靠袁绍时建议袁绍杀了刘备。乌巢的兵粮库受袭时，让张郃和高览进攻曹操本营失败，将自己的责任推给张郃两人，故使两人转投向曹操军。袁绍死後，和审配、逢纪对立，同辛评服侍袁谭。虽一时降於曹操攻讨袁尚，结果却被曹操包围在南皮城，被乐进射杀。\n\n史：献帝脱離长安之际，曾经进言拥护。\n\n",
