    "biography": "魏将·夏侯渊之子。夏侯霸之弟，夏侯惠、和之兄。\n\n演：夏侯渊的次子。在诸葛亮出兵五丈原时，被司马懿提拔，同其兄夏侯霸担任左右先锋。公孙渊掀起叛乱时，也随司马懿从军镇压。\n\n史：是个有男子气概的人物，历任荆州、兖州刺史。看面相的朱建平预言「虽在49岁时遭遇灾难，但只要撑过这关就会活到70岁，能成为辅佐皇帝之人」。在49岁时的12月患病，虽喜於除夕夜时康復，却在酒宴後病发随即猝死。\n\n",
