    "biography": "曹操的重臣。夏侯惇的堂弟。夏侯霸、威、惠、和之父。\n\n演：连同夏侯惇在曹操举兵时从军。铜雀台落成时展现曹操军第一弓术，在渭水一战中射杀成宜。在击退马超後，毛遂自薦同张既共守长安，並平定凉州。张鲁讨伐战中同张郃先锋，在压制汉中後守卫定军山。汉中受到刘备攻打时，虽受到曹操「我对妙才（夏侯渊的字）有所期待」警惕切莫过於急躁所写的一封信，却还是因对山被刘备军夺走而焦躁，在出阵时被黄忠所杀。\n\n史：官渡之战时负责确保兵粮。善於奇袭。\n\n",
