    "biography": "魏将·夏侯渊之子。夏侯霸、威之弟，夏侯和之兄。\n\n演：夏侯渊的三子。於诸葛亮出兵五丈原时，受司马懿提拔，同弟夏侯和担任行军司马。在上方谷时如诸葛亮所预测的连勝蜀军，为司马懿陷入陷阱的原因之一。同夏侯霸安抚因诸葛亮的木像而吓跑的司马懿。\n\n史：自幼才能和学问就为人所称赞。历任乐安太守等职。屡次和锺毓展开论战，大部分的时候都是夏侯惠的意见被採用。37岁死亡。\n\n",
