    "biography": "魏将·夏侯尚之子。曹爽的堂兄弟。清谈家。\n\n演：和李豐、张缉受曹芳命令诛杀司马师，不料密函被司马师发现。和李豐等人在市场被腰斩，三族皆被杀光。\n\n史：曹爽掌政时历任高官，傑出的功绩为後世的範本。２４４年，同曹爽进攻蜀国，败给了费禕。曹爽被司马懿所杀之後，也因与曹爽关係亲密而未遭到厚待。和李豐、张缉企图打倒司马氏的计劃洩露，招致被杀。和同样对司马氏掀起反叛的诸葛诞、毌丘俭等人也关係亲近。\n\n",
