    "biography": "魏将·夏侯惇（正史为夏侯渊）的姪子。夏侯德之弟。\n\n演：在对刘备军的汉中攻防战中，同韩浩、张郃共同防守的瓦口关被黄忠击破，防守天荡山的夏侯德也被击败。在定军山被黄忠所俘，在和陈式交换人质时中了黄忠一箭。之後，同徐晃共守襄阳，虽和曹真联手包围江陵，却还是败给陆逊。\n\n史：同和曹彰镇压在代郡的胡族反叛。曹丕的时代，因攻略上庸成为征南大将军。在江陵包围战击败诸葛瑾。因爱妾的死导致重病，最後懷恨而死。和曹丕有著超越身份的亲密关係。\n\n",
