    "biography": "曹操的重臣，西汉夏侯婴的後裔。\n\n演：在曹操举兵之後从军。在董卓讨伐战中救出败给徐荣的曹操，並刺死徐荣。在和吕布军交战中，左眼虽被曹性的箭射中，最後还是将曹性杀死。在刘备任用诸葛亮时进攻新野，但是遭到诸葛亮的火攻而大败。镇压在邺掀起反叛曹操的耿纪和韦晃。和刘备军的汉中攻防战中，向杨修询问曹操随口而出的「鸡肋」其意，並指挥军队撤退。曹操死後有如追随而去一般地病死。\n\n史：因失去左眼故称之为盲夏侯。在曹丕时代为大将军。\n\n",
