    "biography": "魏将·夏侯渊之子。夏侯威、夏侯惠和夏侯和之兄。\n\n演：夏侯渊的长子。在诸葛亮的第五次北伐时被司马懿提拔，同其弟夏侯威担任先锋。公孙渊反叛时亦随从司马懿，並砍杀卑衍。曹叡死後，和掌握实权的曹爽关係亲近，在曹爽被司马懿所杀後，便亡命到蜀国追随姜维。同时也传达锺会和邓艾是个强敌的消息。之後，在姜维北伐时从军。２６２年，中了邓艾和司马望的空城计，遭受石箭攻击而战死。\n\n史：夏侯渊的次子。其堂妹为张飞之妻，其女为刘禅之后，所以在蜀国也相当受到礼遇。被任命为车骑将军。\n\n",
