    "biography": "夏侯渊之子，夏侯惇的养子。其妻为曹操之女·清河公主。\n\n演：字子休。在诸葛亮第一次北伐时，自願亲自指挥迎击。虽被王朗指责毫无经验，仍无视於指责执意出征，在南安被王平逮捕。由於诸葛亮策略被释放後逃往天水，因为懷疑姜维而使其反叛。在天水被攻陷後，同马遵逃往羌胡城。\n\n史：虽是夏侯惇的次子，却继承夏侯渊的任职。曹丕时代以安西将军进驻在长安。於诸葛亮北伐前被召回中央，並未和诸葛亮交战。\n\n",
