    "biography": "夏侯文寧之女。曹爽的堂弟·曹文叔之妻。\n\n演：父亲为夏侯令。其名顾名思义即夏侯令之「女」。年轻丧夫，没有子女的缘故，虽受父亲鼓励再婚，却毅然割下一耳以表拒绝。在曹爽一族被灭之後，再次被劝说再婚时，这次则以切下鼻子拒绝。其贞节让司马懿感到佩服，於是允许其收养养子为继承人。\n\n史：曹文叔死後为恐被迫再婚而断发。之後切下耳鼻的发展和演义相同。\n\n",
