    "biography": "贾逵之子。晋惠帝之后·贾南风之父。司马昭的心腹。\n\n演：为了让司马昭掌握政权在暗中活跃，讨伐反抗的诸葛诞等人。发现魏帝·曹髦的暗杀司马昭计劃，就在成济杀死曹髦。当司马昭苦恼於选择继承人之际推举司马炎，司马昭死後促使成为晋王的司马炎决心夺取帝位。在羊祜和杜预上奏吴国讨伐作战时表示反对。在孙皓投降时责备他残忍的行为，但却反被指出暗杀曹髦一事，令其蒙羞。\n\n史：在晋国历任侍中、司空、尚书令等职，负责制定晋律。以晋建国的最大功臣而官升至太宰。\n\n",
