    "biography": "吴国司徒。孙和的侧室·何氏之弟，孙皓的叔父。\n\n演：２７９年，当晋国发起讨吴战时，被孙皓所召询问对策，却什麼也答不出来。\n\n史：孙皓即位後随心所欲操控政权，同其姐何氏等都被人民所怨恨。在晋国大军逼近时，曾被孙皓以书信询问对策。在吴国灭亡同时向晋国投降。\n\n",
