    "biography": "东汉大将军。为灵帝的皇后即生下刘辩（少帝）的何皇后的異母之兄。原本经营肉店，藉由宦官之助成为外戚。\n\n演：命令卢植、皇甫嵩、朱[0xFA][0x45]镇压黄巾之乱。曾经差点被宦官蹇硕所暗杀，之後和十常侍争夺政权。灵帝死後，拥刘辩即帝位，並暗杀刘协派的董太后。企图诛灭十常侍时被何太后阻止，接受袁绍献策，策劃集结董卓等诸侯的军事力量将宦官一扫而尽。不料在事前计劃洩漏，前去和何太后见面途中被十常侍暗杀。\n\n史：因宦官之助使外戚得权，可说是中国史上少见的情形。\n\n",
