    "biography": "吴国武将。贺达、贺景之父，贺邵的祖父。\n\n演：没有记载。\n\n史：年轻时曾讨伐联合山越为非作歹的斯从，因而被山越敬畏。在孙策成为会稽太守时进入麾下。致力於平定各地的叛乱，新设建平县、始新县、新都郡等地方单位。历任偏将军、奋武将军等，同陆逊平定鄱阳的反叛被任命为安东将军。喜好豪华的装扮，也给自己的部队装备上等且豪华的军装。曾有曹休军仅看到如此的威容就举兵撤退一说。後升为後将军及徐州牧。\n\n",
