    "biography": "董卓的武将，身高九尺。\n\n演：当以袁绍为盟主的反董卓联盟军攻向汜水关时，便以董卓军先锋同胡轸、李肃、赵岑等人出阵。序战中砍杀鲍信之弟·鲍忠，击破联合军的先锋·孙坚，並杀掉孙坚的替身祖茂。接著杀掉袁术的部下俞涉、韩馥的部下潘凤，让联合军大为震惊。但最後却被当时默默无名的关羽所杀。\n\n史：董卓的都尉。在阳人和孙坚军交战，被杀死。\n\n",
