    "biography": "关羽之子·关兴的庶子。蜀国汉寿亭侯。\n\n演：因为关兴的嫡子·关统没有子嗣的关係，在关统死後继承关羽的爵位。蜀国灭亡後，被捲入企图在益州独立的锺会叛乱之中，最後被魏国士兵所杀。\n\n史：蜀国灭亡後，被参与邓艾和锺会所发起之蜀国讨伐战的庞会（被关羽所杀的庞德之子）所杀，断绝关羽的血脉。\n\n",
