    "biography": "袁术的幕僚。\n\n演：以促使袁术之子及吕布之女婚事的使者前访吕布。与鼓吹和袁术同盟的陈宫意气相投，但被联手刘备及曹操的陈珪父子所碍，而遭吕布逮捕。当袁术再次派遣的使者被吕布斩首後，颈部就被铐上枷锁护送回许昌，被曹操处刑。\n\n史：因吕布答应袁术所提出的婚事，所以前去迎接吕布的女兒。但在陈珪劝说和曹操敌对的危险性後，就被吕布带回，被送到许昌後受到曹操处刑。\n\n",
