    "biography": "刘备的义弟，张飞的义兄。关平、关兴、关索之父。\n\n演：在桃园起誓和刘备、张飞结为兄弟。董卓讨伐战中因击败华雄而声名大噪。在刘备败给曹操时，为了保护刘备之妻而向曹操投降。斩杀袁绍军的颜良和文醜回报曹操的恩情之後，就突破五关六将回到刘备麾下。刘备入蜀後虽然统治了荆州，却与同盟的孙权关係恶化。在掛上五虎将军的称号进军中原後，被破弃同盟关係的孙权军夺去荆州，在麦城同关平等双双被砍杀。\n\n史：好读「春秋左氏传」，並熟谙其内容。\n\n",
