    "biography": "毌丘兴之子，毌丘甸之父，毌丘秀之兄。魏国幽州刺史。\n\n演：将辽东的公孙渊以燕王自称举兵的事情告知曹叡。在曹芳被司马师迫退位时，同文钦举兵企图打倒司马师，却被吴国孙峻和司马师的两军夹攻而败北。在逃走中被慎县的县令·宋白灌醉杀害。\n\n史：曾为曹叡的太子文学，受到亲密的对待。於镇压公孙渊的反叛和东方远征时相当活跃。以败给吴国的诸葛诞的後继者成为镇东将军，防止了诸葛恪的进攻。在败给司马师逃走时，被张属所射杀。\n\n",
