    "biography": "东汉长沙太守。\n\n演：魏国武将·韩浩之兄。赤壁之战後，受到关羽的攻击，派杨龄迎击却惨遭反击。接著虽派遣黄忠迎击，见其彼此为道义而无心相战的情形懷疑内神通外鬼。於是逮捕黄忠欲处以死刑之际，却被部下魏延阻止並遭砍杀。刘备军和曹操军的汉中攻防战中，其弟韩浩向黄忠挑起復仇战，却被砍杀。\n\n史：赤壁之战後，刘备进攻荆州南四郡时投降。对於和韩浩间的关係未有任何描述。\n\n",
