    "biography": "魏国武将。\n\n演：长沙太守·韩玄之弟。以夏侯惇的副将进攻刘备所在的新野，在博望坡败於诸葛亮的火计。汉中攻防战中同夏侯尚协助进攻葭萌关的张郃。天荡山一战为报兄仇向黄忠挑战，最後被杀。\n\n史：以王匡部下和董卓相战，被聽到名声的袁术所任用。受夏侯惇登庸，因向曹操进言屯田制而成为护军。参加张鲁讨伐战，指挥近卫部队。和韩玄的关係不明。\n\n",
