    "biography": "关羽的次子，关统之父，张苞的义弟。\n\n演：当关羽进攻曹操军的襄阳，大破于禁时，便向成都的刘备报告战果。当关羽败给孙权军战死时，加入刘备所组的復仇之军的行列，便和争抢先锋的张苞结为义兄弟。斩杀了吴国的李異、周平，並讨伐抓住关羽的潘璋夺回青龙偃月刀，但蜀军终是战败。之後参加诸葛亮的北伐。和西羌军之战中斩杀越吉等表现大为活跃，却在第五次北伐前病死。\n\n史：其才能曾受到诸葛亮评價。继承关羽之後，20岁时任侍中、中监军，却在数年後死去。\n\n",
