    "biography": "关羽的三子。\n\n演：关羽战死於荆州时负伤，在鲍家的莊园裡疗养。诸葛亮的南蛮讨伐战中率先归来，並为先锋。活跃於屡次逮捕孟获的作战中。\n\n史：没有记载。有不少像「花关索传」等，以关索为题材的民间故事存在，亦为京剧的题材。四川省现存的鲍三娘墓上，记录著关索和其妻鲍三娘共守葭萌关一事。\n\n",
