    "biography": "东汉并州刺史，凉州军阀首领之一。\n\n演：和西凉太守·马腾为义兄弟。同马腾对抗佔领长安的李傕军却败北。在马腾被曹操暗杀後，和马超共同举兵復仇。在攻陷长安，进军潼关时，却因贾诩的離间计和马超决裂。在决心向曹操投降时被马超趁虚而入，並且被砍断左手。马超败北逃走後，成为西凉侯。\n\n史：黄巾之乱後和边章共同举兵。虽受到张温、董卓等人的讨伐，却依然保持著势力。在渭水一战後也持续对抗曹操军，於西平金城被杀死。亦有病死一说。\n\n",
