    "biography": "刘表的幕僚，荆州的名士。\n\n演：官渡之战前，被刘表询问该在曹操和袁绍中选择支持谁，回答为曹操。奉命侦查许昌时，受到献帝告知如果接受了赐位就不再是刘表的家臣之後離走。被曹操任命为侍中、零陵太守，返回後，被刘表关入牢狱。在刘琮降於曹操，曹操进入荆州後被释放。\n\n史：刘表死後，同蒯越、傅巽等人劝告刘琮向曹操投降。\n\n",
