    "biography": "公孙瓒的幕僚。\n\n演：没有记载。\n\n史：深得公孙瓒的信赖和宠爱，只懂得巴结而未抱持长期性的展望。在易京受到袁绍包围时，阻止公孙瓒从背後偷袭袁绍。公孙瓒死後，说「聽闻君子使他人陷於危难之际，必当患难与共。我等岂可以独存？」，随即突击袁绍军而死。\n\n",
