    "biography": "黄巾武将，白波的头目。\n\n演：护卫献帝逃出长安，被任命为征东将军。虽曾和李乐共誇权势，但不久之後就叛離。在曹操欲来保护献帝时，同杨奉和曹操作战，败北後便投靠袁术。後来虽参加袁术的吕布讨伐战，却由於陈珪的计谋而倒戈投向吕布军。之後在徐州附近进行掠夺时，被关羽和张飞所讨。\n\n史：在杨奉被刘备俘虏之後陷於孤立。欲逃往并州，却被张宣所杀。\n\n",
