    "biography": "吴国幕僚。\n\n演：孙策死後，被孙权招至其麾下。在赤壁之战时，将黄盖的假投降书送给曹操，並用其善辩的口才瞒骗了曹操。返回後同甘寧谋骗曹操派来秘密侦查的蔡中和蔡和，使苦肉计成功。在孙权面临刘备的关羽復仇战，苦恼要选择谁当防卫指挥官时，只推举了陆逊一人。\n\n史：孙权即位後，担任尚书、中书令。後为太子太傅，负责教育孙和。著有吴国历法「乾象历注」一书，被虞翻称赞为「现代的董仲舒」。\n\n",
