    "biography": "服侍孙坚、孙策、孙权三代。擅使剃刀。\n\n演：追随孙坚参加董卓讨伐战。孙坚死後服侍孙策，在江东进军战时和严舆对战。孙权时代当曹操攻打江东时，主张正面抗战。在周瑜的指挥下，在赤壁、南郡和曹操军作战。当刘备和孙权的关係恶化时，随吕蒙进攻荆州击败关羽。之後，迎击为关羽復仇来战的刘备时，与指挥将领的陆逊反目，但知道为陆逊的计谋後便深感佩服。\n\n史：弓术、马术都十分優秀，並深得将兵们的心。韩当死後，其子韩综向魏国投降，被诸葛恪所杀。\n\n",
