    "biography": "魏臣，西凉大将。韩瑛、韩瑶、韩琼、韩琪之父。\n\n演：擅使大斧。在诸葛亮北伐时，同四个兒子率领西羌的军队加入迎击，並为夏侯楙的先锋。其子皆被赵雲所杀，为了復仇向赵雲挑战，却反而也被杀。\n\n史：没有记载。\n\n",
