    "biography": "吴国勇将。原是锦帆贼的头目，在腰间繫有铃铛。\n\n演：为黄祖的部下。和孙权军作战，虽打败凌操却未获得重用，受战友苏飞劝说向孙权投降。以孙权军将领追讨黄祖，黄祖被苏飞抓到後跪地求饶。之後，在赤壁、南郡、合淝等地皆以吴军的先锋奋战。在濡须口仅以百名之力夜袭成功，被赞为足以匹敌魏国张辽。为凌操之子·凌统前来报仇挑战，最後因凌统受乐进袭击时相救，而在战场上和解。之後在夷陵之战，中了沙摩柯的箭而战死。\n\n史：並没有在夷陵战死的记载。\n\n",
