    "biography": "魏国大臣，曹爽的心腹。被称为智囊的策士。\n\n演：曹芳时代曹爽掌握实权时，被任命为大司农。曾对出去打猎的曹爽警告注意司马懿的动向，但却未被聽进去。结果如桓範所料，司马懿佔领了洛阳。之後单身脱逃前去和曹爽会面，劝说在许昌展开抗战。但仍旧未被接纳，只能仰天长叹。不久之後曹爽一黨皆被逮捕，连三族被处死。\n\n史：同王象等共编「皇览」。虽受到曹爽以同乡的前辈的尊敬，但两人並不亲近。\n\n",
