    "biography": "东汉冀州刺史。\n\n演：是响应曹操打倒董卓口号的诸侯之一。汜水关一战中，部下的潘凤被董卓军的华雄所杀。在反董卓联盟军解散後，袁绍威胁韩馥说，公孙瓒对他虎视耽耽，使韩馥向袁绍请求协助。结果被进入冀州的袁绍夺走了领地。之後，投靠陈留的张邈。\n\n史：同袁绍计劃使刘虞即位皇帝。在公孙瓒的势力扩大後，将自己的地位让给袁绍，逃到张邈之下。见袁绍的使者跟张邈耳语，懷疑自己性命不保，於是自杀。\n\n",
