    "biography": "居住在河北国境的关定之次子，关羽之养子。\n\n演：在脱離曹操和刘备再会时的关羽相遇，经刘备穿针引线成为关羽的养子。新野一战中同刘封促使诸葛亮的火计成功。在刘备进攻益州时从军，庞统战死时向荆州要求援军，等诸葛亮等人前往益州後，转而留在荆州辅佐关羽。在关羽攻打襄阳时随军，表现十分活跃。但受孙权突袭，在麦城同关羽被捕皆被处死。\n\n史：记载为关羽之子，而非养子。\n\n",
