    "biography": "和文醜並称为袁绍军的双璧猛将。\n\n演：汜水关一战未能随行，和董卓军的华雄苦战的袁绍就感叹「如果有颜良、文醜在就不会输了」。在袁绍和公孙瓒在界桥开战时，以袁绍军的先锋和刘备军的公孙瓒对战。官渡之战的前哨战白马之战时，连讨曹操军的宋宪、魏续，並败退徐晃，让曹操军有所畏惧。可是在面临曹操麾下关羽的挑战时，却被一击而毙。\n\n史：另一说法是，和关羽对战当时，颜良误以关羽为袁绍阵营的刘备所託，是故未有抵抗而被砍杀。\n\n",
