    "biography": "原是刘表的武将。改仕韩玄後，加入刘备军。\n\n演：在刘备军进攻南荆州时，将韩玄杀死並交出长沙。虽被诸葛亮指出魏延有反骨之相应用立刻处斩，却被刘备允许加入军队。攻益州之战中与黄忠争功，在汉中攻防战时射中曹操，表现十分活跃。刘备成为汉中王时担任汉中太守。之後跟随诸葛亮征服南蛮、北伐等行动。虽然是蜀军主力，却在北伐的进攻路线上和诸葛亮起冲突。在诸葛亮死後，和杨仪对立並掀起反叛，为马岱所斩杀。\n\n史：无视於张飞，成为汉中太守，让周围的人大感震惊。\n\n",
