    "biography": "袁绍的武将。\n\n演：在界桥之战中，指挥防守公孙瓒的白马义从的前卫部队。虽斩杀严纲瓦解了公孙瓒军，却被公孙瓒部下的赵雲所杀。\n\n史：因为长期留在凉州，熟悉羌族的战法，麾下士兵也都骁勇善战。对抗公孙瓒的骑兵时，以盾牌护身，等接近後再用强力的弩攻击的战法获得勝利。在袁绍遭公孙瓒奇袭而陷入危機时，救援的表现也相当活跃。最後仗著功绩卓越擅自採取行动，被袁绍所杀。\n\n",
