    "biography": "吕布的武将。\n\n演：跟随从曹操手中夺走兖州的吕布和曹操军抗战。在吕布进入徐州後，和宋宪购买良马时被张飞袭击，愤怒的吕布就将刘备赶出徐州。之後，被曹操和刘备的联合军包围在下邳，当同僚的侯成被吕布处罚时，便同侯成、宋宪共捕吕布向曹操投降。不久之後以曹操部下参加官渡之战，却同宋宪被颜良所杀。\n\n史：和侯成、宋宪等人合力抓住陈宫。並没有抓住吕布。也没有成为曹操部下的记载。\n\n",
