    "biography": "董卓的女婿，东汉中郎将。\n\n演：在董卓奉何进之命上京时，留守陜西。在董卓被王允和吕布设计杀害後，为了復仇和李傕、郭汜、张济、樊稠等人进攻长安。可是却为吕布所败，而在携带著财宝和数名亲信逃亡的途中，被心腹胡赤兒给杀害。\n\n史：奉董卓的命令进驻陜西，命令李傕、郭汜、张济进攻陈留、潁川。董卓死後，在李傕等人归来之前，曾破吕布所派遣的李肃。而在半夜中误将骚动视为叛乱，慌乱逃跑中被胡赤兒等人所杀。\n\n",
