    "biography": "魏国天水太守·马遵的部下。後为蜀将。\n\n演：在第一次北伐时迎击蜀军，虽一度击败诸葛亮，却陷入诸葛亮的陷阱而向蜀军投降。之後就以蜀将参加诸葛亮的北伐，在诸葛亮临终之际还受传授兵法。诸葛亮死後，对出兵採消極态度的费禕战死，便成为大将军指挥北伐。在锺会和邓艾进攻蜀国时，虽在剑阁死守抵抗，最後因顾虑先投降的刘禅的性命而投降。虽立志再兴蜀国而同锺会举兵，却战败而死。\n\n史：诸葛亮赞赏姜维「身懷有马良以上的才能，为凉州最傑出的人才」。\n\n",
