    "biography": "许褚之子。魏国牙门将军。\n\n演：锺会和邓艾发起蜀国讨伐战时，担任锺会的先锋打开军道。在南郑交战时，因路况不佳使锺会的马匹动弹不得，而险遭蜀国卢逊所杀。於是九死一生後的锺会，以怠忽职守将其处死。\n\n史：奉锺会之命整备道路，然而桥面陷洞，使得马脚陷落因此被斩首。见锺会对即使是功臣许褚之子也毫不留情的处置，不禁令魏国将兵不寒而慄。\n\n",
