    "biography": "东汉吴郡太守。\n\n演：欲将孙策打倒曹操的计劃向曹操密告，不料被孙策发现而被杀。死後，许贡的食客设下復仇之计，使孙策负伤致死。\n\n史：上奏献帝「孙策同项羽为武艺高强的豪傑，将其置於地方必定引起灾难」。这份上奏文落入孙策手中，並受到孙策询问。虽然辩驳並无上奏一事，仍不被聽信而惨遭绞杀。\n\n",
