    "biography": "刘璋部下的蜀郡太守。後为蜀国司徒。\n\n演：在刘备劝降刘璋之际，早一步翻过城墙向刘备投降。刘备成为益州牧之後，许靖也成为太傅。东汉灭亡後，和诸葛亮、谯周等人计劃让刘备即位，蜀建国後成为司徒。\n\n史：许劭的堂兄。虽同为评论人物的名嘴，彼此却交恶。东汉时以尚书令的身份担任选拔官员，在董卓政权下提拔了韩馥、刘岱、张咨、孔[0xFA][0x40]、张邈等人。当韩馥等人举兵计劃攻打董卓时，便前去投靠孔[0xFA][0x40]、陈禕、许贡、王朗等人，後来受刘璋之邀入蜀。\n\n",
