    "biography": "曹操的武将。因其武艺以及胆识，另有「虎痴」的别称。\n\n演：讨伐黄巾黨的残黨时，其武勇受到曹操注目因此受邀加入曹操军。进攻新野的刘备时担任先锋，在赤壁之战时护卫战败的曹操撤退。而潼关之战中亦拼死保护受马超军追赶的曹操。因单挑马超且不分上下，被赞为「真不愧为虎痴」。之後在濡须、汉中等地，曹操和曹丕出阵时以护卫随军。\n\n史：为人谨慎且守法，外表憨厚寡言。明帝即位後死去。\n\n",
