    "biography": "袁绍的幕僚。和曹操十分亲近。\n\n演：服侍支配冀州的袁绍。官渡之战中得知曹操兵粮不足，催促袁绍採取速攻。但却遭政敌的审配中伤其一族不良，因此得罪了袁绍而转向曹操投降。而後让曹操军攻击袁绍军兵粮基地所在的乌巢，对曹操之勝颇有贡献。在曹操军入城袁家的根据地·邺时，说出「如果没有自己，曹操军根本无法入城」造成众将领的不悦，被许褚所杀。\n\n史：黄巾之乱後，同王芬等人计劃废灵帝拥立合淝侯。虽曾邀曹操参加被拒绝，最後计劃失败。\n\n",
