    "biography": "袁术的武将。操使重达五十斤的三尖刀。\n\n演：因荀彧的「驱虎吞狼之计」，成为迎击刘备军部队的大将，和关羽单挑不分上下。在刘备被吕布夺走下邳後，亦为袁术发起刘备讨伐战中的讨伐军大将，但在吕布的仲裁之下退兵。之後加入吕布讨伐战，却因杨奉和韩暹的背叛而失败。成为皇帝的袁术失势投靠袁绍时，受到刘备军的攻击，而被张飞所杀。\n\n史：仅有攻刘备，及受吕布仲裁的记载。\n\n",
