    "biography": "东汉大臣。武陵太守·金旋之子。\n\n演：曾和奉曹操之命指挥近卫队的王必相当亲近。同韦晃、耿纪、吉邈、吉穆等人杀王必夺献帝，加入和刘备合力讨伐曹操的计劃。在２１８年正月时决定谋反。虽使王必负伤但却让他脱逃，结果被接到王必通报前来的夏侯惇和曹休等人所讨伐而死。族人跟其他的参加者也全被杀尽。\n\n史：中兴西汉之臣·金日磾的子孙。为世代皆对汉朝忠诚笃实守节义的一族。\n\n",
