    "biography": "刘璋麾下的巴郡太守。後改仕刘备。\n\n演：反对刘璋招揽刘备防张鲁一事。受张飞攻击而闭城自守，因中计出城攻击之际被捕。对张飞怒言「蜀国中有被斩首之将，却无降伏之将」，最後被为自己无礼道歉的张飞说服方才投降。打开蜀道，並受到刘备款待。与曹操的汉中攻防战时，同黄忠共同出击。在天荡山之战中，斩杀了夏侯德。\n\n史：仅有被张飞所捕後到降伏为止的记载，对於张飞计略及与黄忠共同奋鬥並无记载。\n\n",
