    "biography": "吴国官僚。\n\n演：孙策死後，被继承的孙权所招揽。赤壁之战前，同张昭等人企图以辩论阻止欲使孙权军和刘备军同盟而访吴国的诸葛亮，却反而论输。\n\n史：年少致力研修学问，经通「诗经」「书经」「三礼」。受张昭推薦服侍孙权。不善於军事，所以坚决推辞鲁肃的後任。在孙权即位後，为派往蜀国的使者，获得诸葛亮很高的评價。78岁死去。著作有「孝经传」「潮水论」。\n\n",
