    "biography": "魏国雁门太守，牵弘之父。\n\n演：没有记载。\n\n史：服侍袁绍、袁尚当邺被曹操包围时，为了调配兵粮而派遣到上黨，返回之前由於袁尚败逃，便降於曹操。之後袁尚被公孙康所杀，虽身为曹操臣子亦前往袁家弔丧。曹丕即位後成为雁门太守，立下统治異族以及开通水路等等功绩。曹叡时代，在田予被轲比能包围时前往救援，戒备联合轲比能準备进攻的诸葛亮。统治边境的评價仅次於田予。\n\n",
