    "biography": "以「东吴德王」自称佔领吴国。\n\n演：遭受进军江东的孙策的攻击，命其弟严舆前往迎战败北，因此投靠会稽的王朗。之後，又败给进攻会稽的孙策军，在逃往余杭途中，被董袭杀死。\n\n史：山越出身。率领一万兵力对抗朝廷。在孙策进军江东时，同吴郡太守的许贡、广陵太守的陈登等人联合抗战。败北後靠许昭的部下逃走。並未记载王朗败北後持续抵抗，及遭杀害等事。\n\n",
