    "biography": "为自称「东吴德王」的严白虎之弟。\n\n演：在孙策进军江东时，担任严白虎的先锋在枫桥迎击，败给了程普、蒋钦、陈武。在严白虎看出没有勝算决定和解时，被派为使者前去和孙策会面。但提出同孙策统治江东的方案，引起孙策的不快而被砍杀。\n\n史：拥有武艺以及敏捷的身手广为人知。並没有谈和前抗战的记载。在谈和时被孙策所杀，聽到这个消息後，严白虎恐惧不已。\n\n",
