    "biography": "刘璋的武将。其妹为刘璋之兄·刘瑁之妻。吴班的族兄。\n\n演：在刘备入蜀时，同刘循、吴兰、雷铜前来援救在雒城的张任等人，却被赵雲逮捕而臣服。因其夫亡人的妹妹成为刘备的皇后，並生下刘永和刘理而备受礼遇。参加诸葛亮的北伐，在诸葛亮死後成为车骑将军守卫汉中。\n\n史：为避免和司马懿同名而记为吴壹。早年丧父，同父亲旧交的刘焉加入蜀国。街亭之战中诸葛亮虽以马谡为前锋，但其他的将领却推举吴懿和魏延。诸葛亮死後，同王平共卫汉中。\n\n",
