    "biography": "服侍孙坚、孙策、孙权三代。操使铁鞭。\n\n演：和程普、韩当早期就跟随孙坚，与刘表一战中抓住了黄祖。赤壁之战前，诸葛亮为了和孙权结盟访吴国时，制止企图以论战阻止诸葛亮的张昭等人。决定抗战之後，和周瑜提议「苦肉计」並自願遭受棒刑，使曹操对黄盖的假投降信以为真。赤壁之战开战时让假装投降的火船冲入，並烧光了曹操的船队。在追击曹操时，中了张辽的箭而被韩当所救。\n\n史：赤壁之战後，成为武陵太守，在任中死亡。\n\n",
