    "skills": [],
    "biography": "袁绍的姪子，高柔的堂兄。并州刺史。\n\n演：官渡之战後，为袁绍的援军在仓亭和曹操相战却败北。袁绍死後和袁谭、袁熙、袁尚等人於黎阳再度和曹操一战又败北後，返回并州。死守壶关抵禦李典、乐进、张燕的攻击，却被诈降的吕旷、吕翔所骗而逃亡。遭匈奴左贤王拒绝援助，转向荆州投靠刘表时，被王琰所杀。\n\n史：被袁绍任命为并州牧。在曹操佔领邺时投降，被任命为并州刺史。在曹操讨伐乌丸时再度举兵，死守在壶关。\n\n",
