    "biography": "黄承彦之女，诸葛亮之妻，诸葛瞻之母。\n\n演：相貌醜陋，却是个通天文地理兵法的才女。为南阳诸葛亮所求而成为其妻，在学问上对诸葛亮有诸多相助。在丈夫死去不久後，亦追随丈夫死去。\n\n史：聽到诸葛亮在寻找结婚对象的黄承彦便对诸葛亮说「我有个醜女兒，虽然红发黑皮肤，但才智与你不相上下」。当地的人都议论纷纷的说「勿学孔明选新娘」。也有传说指出，对外宣称相貌醜陋使男子敬而远之，但其实是个美若天仙的女子。\n\n",
