    "biography": "刘璋的幕僚。\n\n演：在刘璋欲招揽刘备抵禦张鲁时，曾企图阻止但未被接受。刘备準备入蜀之际，献出向张鲁要求援军以抵禦刘备等策略。在刘璋向刘备投降之後拒绝仕官，後来在刘备亲访下才出仕。在夷陵之战负责水军，当刘备战败被吴军包围时，因为向吴投降愧对自己的良心，转而向魏国投降。接到家人被刘备杀害的消息但並没有聽信，而刘备也没有对黄权问罪。\n\n史：投降魏国後，历任阵南将军、车骑将军。\n\n",
