    "skills": [],
    "biography": "蜀国宦官。受刘禅所宠爱。\n\n演：董允死後掌握政权。因阎宇谄媚把姜维降职，並妨碍姜维北伐行动。即使锺会和邓艾发起蜀国攻略战，黄皓依然让刘禅相信巫女的话拒绝援军。在刘禅聽到江油城被邓艾攻陷大感震惊时，却告知是误报。在刘禅投降後，虽以行贿逃过险被邓艾斩首一劫，但在同刘禅被送往洛阳之後，仍被司马昭下令处死。\n\n史：董允死後，和成为侍中的陈祗联合掌握政权。並未记载被司马昭处刑一事。\n\n",
