    "biography": "魏国官僚。高靖之子，高幹的堂弟。\n\n演：在曹方时代为司徒。２４９年，司马懿发起打倒曹爽的政变时，代替曹爽执行大将军一职，並佔领曹爽阵营。\n\n史：张邈曾预料招吕布至旗下，将会掀起反叛曹操一事。於是为高幹所招揽，举家前往河北赴任。曾一度降於曹操的高幹兴起反叛时，使高柔险被曹操所杀，但展示其精明的用法之道後得到曹操的信任。並且也被曹丕、曹叡所重用，担任掌管法律的廷尉２３年之久。曹芳时代担任司空和司徒，曹髦的时代则担任太尉。\n\n",
