    "biography": "吕布的武将。\n\n演：和曹操军争夺濮阳之战中表现活跃，在吕布定陶山败北後，便同陈宫保护吕布的家人逃往徐州。在吕布夺取由刘备所留守的下邳後进驻小沛。之後，和曹操联手的陈登运用谋略夺走小沛，在下邳受到曹操军包围。由於侯成等人的背叛，和吕布一同被捕。和求饶的吕布相反，高顺是一言不发凛然的接受斩首。\n\n史：所攻击的对手必定击破，被称为「陷阵营」。虽曾不断地向吕布提出忠告，却完全不被接受。\n\n",
