    "biography": "蜀国武将。\n\n演：参加诸葛亮的北伐。在街亭之战中驻紮列柳城，担任进军街亭的马谡的後方支援。在诸葛亮的第四次北伐中，使用木牛流马担任兵粮运输的工作。聽从诸葛亮的计策让魏军数次夺走木牛流马，中计的魏军就被伏兵所击败。\n\n史：在第四次北伐中，同魏延、吴班击破张郃军，夺取了三千首级，五千件黑金铠甲，三十万张弩，表现大为活跃。\n\n",
