    "biography": "蜀国武将。黄权之子。\n\n演：同和诸葛瞻共防绵竹关，受到邓艾攻击，诸葛瞻父子战死後，就跟同阵营的张遵、李球各自率领一个军队出击，最後三人都战死。\n\n史：当夷陵之战战败的黄权向魏国投降时留在蜀国。在邓艾进攻蜀国时，同诸葛瞻一起迎击。流泪斥责预见蜀国灭亡而消極的诸葛瞻。而後与邓艾交战，退回绵竹关。为了激励士兵而决死一战，最後战死。\n\n",
