    "biography": "吕布的武将。\n\n演：参加战鬥和曹操军争夺濮阳。虽然一进一退的持续进行攻防战，却在调配兵粮的时候在定陶山败给吕布，逃往徐州。之後，在下邳被曹操和刘备的联合军包围的时候，防止部下把军马送给刘备投降。在报告时顺便邀请吕布参加酒宴，却以违反禁酒令的理由处以棒刑。因为这件事情，就跟同事魏续和宋宪趁吕布不注意的时候，夺取吕布的坐骑赤兔马向曹操军投降。\n\n史：和魏续、宋宪一起被陈宫逮捕，向曹操军投降。\n\n",
