    "biography": "韩遂的武将。\n\n演：马腾被曹操杀害後，和挑起復仇战的马超、韩遂一起举兵。而渭水之战中，因贾诩的離间计导致马超和韩遂不和，於是在韩遂的营舍中商讨善後策略。商讨当中因为马超冲进来砍杀而逃亡。在马超战败逃亡後，同杨秋向曹操投降，防守渭口。\n\n史：在渭水之战败北後，同程银投靠汉中的张鲁。２１５年汉中被曹操平定後便出面投降，並受授同原来的官职。\n\n",
