    "skills": [],
    "biography": "刘表的武将，江夏太守。黄射之父。\n\n演：在和孙坚军作战时被黄盖逮捕，因孙坚战死的关係，就以其为人质交换遗體。当企图復仇的孙坚攻来时，命令甘寧迎击並一度成功地击退敌军。但却因为侮辱甘寧原为江贼而遭到反叛被杀。在这之前，还因对曹操派遣来的禰衡的毒舌感到愤怒，而杀了禰衡。\n\n史：对与黄射关係亲近的禰衡有不错的评價並经常让其同席，但後因怒於弥衡态度傲慢而将之杀害。被孙权挑起復仇战时弃城而逃，途中被冯则所杀。\n\n",
