    "biography": "公孙瓒之弟（正史中为堂弟）。\n\n演：在袁绍和公孙瓒共谋夺取冀州後，为了交涉领土的分配而拜访袁绍。可是袁绍却没有给予公孙瓒的意思，在返回的途中被伪装成董卓部下的袁绍士兵给射杀。\n\n史：奉公孙瓒的命令协助袁术。在袁术手下的孙坚和董卓军交战时，受到袁绍军的周昂攻击，被袁术以援军派遣前往。虽然同孙坚迎击周昂，却因为中了流箭而战死。\n\n",
