    "biography": "公孙康的次子，公孙恭的姪子。公孙晃之弟，公孙修之父。\n\n演：夺取继承父亲之後的公孙恭之位，被曹叡封为扬烈将军、辽东太守。受吴帝·孙权封为燕王，却杀害使者张弥和许宴，並将首级送去给曹叡。之後因不满被赐的大司马一职，结果以燕王自称。无视贾範和伦直的忠告举兵，结果大败给了司马懿。提出投降申请却被拒绝，和公孙修企图逃走之际，被抓到处死。\n\n史：自称为燕王後，击退毌丘俭所率领的最初的讨伐军。公孙渊灭亡後，倭国向魏国派遣使者。\n\n",
