    "biography": "公孙度之子，公孙恭之兄，公孙晃、公孙渊之父。\n\n演：公孙度死後继承辽东太守之位。２０７年，败给曹操的袁熙和袁尚前来寻求保护。但由於曹操未表示出进攻辽东之举，便聽从公孙恭之计讨伐袁氏兄弟，将首级送给曹操表示归顺之意。不久之後，被曹操任命为襄平侯、左将军。\n\n史：２０４年，继承死去的公孙度之位。此时，公孙度生前因不服而拒绝的永寧乡侯之位也由公孙恭继承。\n\n",
