    "biography": "同为卢植门下的刘备的师兄。率领著称为白马义从的精锐骑兵讨伐異族，被取了「白马将军」的别名。\n\n演：北平太守。响应曹操並随刘备参加反董卓联盟，在虎牢关一战败给吕布。联合解散後，为和袁绍争夺冀州而在界桥对峙。最初虽趋於劣势，因得到赵雲和刘备的协助挽回局面，在董卓的仲裁下谈和。和袁绍再次开战後被追讨，虽死守易京奋战，最後力竭自杀而死。\n\n史：並未加入董卓讨伐军。和袁术结盟对抗袁绍，杀死袁绍派的幽州牧·刘虞。\n\n",
