    "biography": "公孙瓒之子。\n\n演：没有记载。\n\n史：在公孙瓒被袁绍追赶到易京楼後，向张燕借援军，並受到从外围攻击的指令。不料密探却被袁绍所捕使得作战揭露。指令反遭利用，受引诱而出的公孙瓒吃了大败仗。之後发现自己难逃败北的命运，就同公孙瓒一起自杀。\n\n",
