    "biography": "乳名为公孙豹。武威将军，辽东太守。为公孙康、公孙恭之父，公孙渊的祖父。\n\n演：只有记载和公孙康、公孙恭之间的关係。\n\n史：被同郡出身的徐荣向董卓的推薦，成为辽东太守。赴任後因压制乌丸周边地区而使声名大噪。在董卓和诸侯间的相争导致中原荒废之际，抱持著称王的野心，後来便自称辽东侯、平州牧。被曹操任命为武威将军、永寧乡侯时，曾说「我是辽东之王。永寧乡侯算什麼」遂将印绶给收藏起来。\n\n",
