    "biography": "公孙瓒的堂弟。\n\n演：没有记载。\n\n史：在袁术军友军的公孙越（公孙瓒的堂弟）於阳城战败死於袁绍军周昂的手下时，受到为恐公孙瓒反击的袁绍授予渤海太守的印绶，以证明友好关係。但公孙範却不向袁绍让步，协助公孙瓒击破青州和徐州的黄巾黨，向界桥进军。公孙瓒在界桥一战败北後，两人共同从渤海撤到蓟驻紮。和定居在蓟的刘虞的关係变为险恶。\n\n",
