    "biography": "东汉豫州刺史。\n\n演：响应曹操讨伐董卓的诸侯之一。\n\n史：擅长评论人物和清谈高论，被比喻成为只要吹口气枯树也会开花。另一方面，被评为没有身为军队指挥官的才能，並不适合餐风露宿的劳动工作。在董卓政权下被提拔为豫州刺史，和袁绍等人参加董卓讨伐战而在潁川驻紮。但却把军队指挥权交给臧洪，同其他诸侯因畏惧董卓的兵力而举兵不动。\n\n",
