    "biography": "刘表的武将。刘表死後服侍长沙太守·韩玄。弓箭名手。在中国为老当益壮者的代名词。\n\n演：迎击入侵长沙的刘备军，和关羽单挑不相上下。韩玄死後，因为刘备直接来访而决定出仕。在刘备攻蜀时，和魏延以先锋活跃於战前。在曹操军的汉中攻防战中，和同样高龄的严颜联手在葭萌关击退张郃。在定军山时也和法正协力砍杀夏侯渊，也因此功绩成为五虎将军之一。在夷陵之战的前哨战中，冲进潘璋阵营不幸战死。\n\n史：在刘备成为汉中王後升为後将军，翌年去世。\n\n",
