    "biography": "蜀国越巂太守。\n\n演：２２５年，在孟获的号召下，和雍闓、朱褒等人反叛蜀国並进攻永昌郡。派遣部下鄂焕迎击对抗诸葛亮所率领的讨伐军。之後，由於中了诸葛亮的離间计，误以为雍闓、朱褒两人背叛，於是杀了雍闓和朱褒向蜀国投降，成为益州太守。\n\n史：越巂的異族之王。在包围新道县时，受李严所攻而逃亡。刘备死後的２２３年和雍闓、朱褒发起反叛，於２２５年被诸葛亮平定。雍闓是被高定的部下所杀。\n\n",
