    "biography": "魏国官僚。西汉儒者·高堂生的子孙。\n\n演：没有记载。\n\n史：为曹操所招揽下进入丞相府。曹丕时代负责守护平原王·曹叡，因长於天文学而被任命研究历法。在曹叡即位後历任陈留太守等职。在曹叡打算继续建造宫殿时，曾严厉地劝谏。後来晋升为侍中、太史令、光禄勋。\n\n",
