    "biography": "刘璋的武将。\n\n演：为防以讨伐张鲁之名而入蜀的刘备，同杨懷进入涪水关（白水关）。受到决定讨伐刘璋的刘备邀请参加宴会时，企图暗杀刘备而出席。却被庞统察觉，和杨懷一起被刘封和关平砍死。\n\n史：被庞统评为「刘璋手下的名将，其手下皆为精锐」。和杨懷皆为聽从庞统策略开始攻蜀的刘备所斩首。\n\n",
