    "biography": "东汉官僚。\n\n演：和卢植、朱[0xFA][0x45]受何进所命讨伐黄巾黨。加上曹操的指挥，以火攻击败张宝和张梁。在曲阳斩杀张梁等表现活跃，平乱後，成为车骑将军、冀州牧。虽使在战中因拒受宦官贿赂而被罢免的卢植復职，但自己却也因拒受贿赂而遭免职。之後在王允讨伐董卓时，同吕布进攻郿城。\n\n史：１８８年，和董卓、陶谦、孙坚等人被派遣镇压韩遂的反叛时，遭董卓憎恨，而在董卓掌权後被逮捕。董卓死後，成为太尉。\n\n",
