    "biography": "东汉官僚。孔子的第二十代子孙，建安七子之一。\n\n演：北海太守。响应曹操发起董卓讨伐战的诸侯之一。此後，曾被黄巾残黨的管亥等人包围在北海，因太史慈而逃过一劫。同时，接纳了受曹操攻击的陶谦的援助请求，遂同刘备前往。在曹操拥立献帝後回到京城。在曹操下令攻击新野的刘备时，因不慎脱口而出「以至不仁（曹操）伐至仁（刘备），安得不败乎！」 而被处刑。\n\n史：和平原的陶丘洪、陈留的边让並称为俊才。但疏於政治的实务，而无法保住北海。\n\n",
