    "skills": [],
    "biography": "袁绍的武将。\n\n演：官渡之战中，乌巢的兵粮基地受曹操军突袭时，奉郭图命令和张郃攻往曹操本营，却被夏侯惇给击退。由於郭图将自己的失责全部推到高览的身上，於是就同张郃向曹操投降。之後便以曹操军的身份和袁绍军战鬥。後来攻打割据汝南的刘备，虽然三刀砍倒刘辟，最後却被赵雲一击而死。\n\n史：曹操进攻淳于琼时，奉袁绍之命和张郃攻打曹洪，淳于琼败北时就向曹操投降。\n\n",
