    "biography": "吴国武将。\n\n演：车骑将军。在晋掀起讨吴战时，由於丞相·张悌献策，便以都督前往江陵赴任。迎击攻来的杜预，却因同僚陆景被张尚所杀造成组织崩壞，於是弃城而逃。途中被伏兵所捕，带到杜预面前被处死。\n\n史：只记载被杜预处死。\n\n",
