    "biography": "刘表的武将。苍梧太守，交州刺史。刘备的旧交。\n\n演：没有记载。\n\n史：是被曹操的南下逼到新野的刘备最先投靠的人物。曾被孙权手下的鲁肃评论为「吴巨没有斩开乱世的才能，不久之後将为其他势力所吸收」。２１１年，受孙权任命为交州刺史的步骘到达之後，表面上顺从孙权的支配来迎接。後来受步骘殷勤的召见到场时，当场立即被杀死。\n\n",
