    "biography": "魏国官僚，国泰之父。\n\n演：没有记载。\n\n史：热衷研究学问，喜好古学，曾被老师郑玄评论为「将成为国家级的人物」。一时曾为了避战乱而移到辽东，返回後为曹操效命。统括屯田政策，五年之间就回復亏损的国库。曹操讨伐马超和韩遂的反叛时受命留守，镇压在河间发起叛乱的田银和苏伯。因此功绩晋成为魏郡太守。後升为太僕，在任职中死去。即使身处大臣高位，依然是粗衣粗食，贯彻谦虚的态度。\n\n",
