    "biography": "孙坚之妻·吴氏之弟。孙策、孙权的叔父。丹阳太守。\n\n演：自幼与双亲死别，同姐姐移往钱塘。遭扬州刺史·刘繇攻打，为孙策所救。\n\n史：追随孙坚立下战功，被袁术任命为丹阳太守，之後到外地讨伐周昕。在刘繇扩大势力之後回到袁术麾下，同孙贲共战笮融、薛礼。之後虽被袁术任命为广陵太守，在袁术自称皇帝後，就回到孙策的手下担任丹阳太守。\n\n",
