    "biography": "吴国建平太守。\n\n演：在晋挑起吴国讨伐战後，诸多投降的吴国将领中战到最後，直到得知吴国灭亡才投降的将领。\n\n史：西陵的步阐倒向投向晋时，在陆抗的指挥下和左奕、蔡贡等人加入讨伐军。见到长江上所漂流的木屑，察知是晋为了讨伐吴国而开始造船。试向孙皓建议增加建平的兵员却遭拒绝。改仕於晋之後，历任金城太守、南中都督、交州刺史。\n\n",
