    "biography": "诸葛诞的武将。西汉长沙王第十六代子孙。\n\n演：在魏国的诸葛诞和吴国的孙綝结盟举兵讨伐司马昭时，跟身为人质的诸葛靓（诸葛诞之子）同行前往吴国。在被孙綝所接受後，回到寿春並告知诸葛诞。\n\n史：虽然比所发现的长沙王遗體的身高还矮，不过姿态却很相似。在向孙綝请求救援後，並没有回到寿春的记载。\n\n",
