    "biography": "孙坚的第二夫人，孙朗、孙仁（孙尚香）之母。姐姐吴氏是孙坚的第一夫人，生下孙权、孙翊。\n\n演：在孙权时代姐姐吴氏死去，之後就被称为吴国太。赤壁之战前，为了向曹操投降及抗战造成朝臣意见歧分两派，便让为此而烦恼的孙权想起孙策和姐姐的遗言，並劝其和周瑜商量。之後，对於周瑜打算藉由和孙尚香成婚将刘备诱出並暗杀一事，知道後大为震怒。亲自和刘备会面後，十分欣赏刘备的吴国太就让刘备迎娶孙尚香。\n\n史：没有记载。只记载孙朗是孙坚嫡子。孙仁是孙朗的别名。孙朗和孙氏（孙尚香）是否亲兄妹依然不明。\n\n",
