    "biography": "蜀国武将。\n\n演：参加诸葛亮的北伐。２５８年的姜维北伐中担任後卫守护汉寿城。当锺会的蜀国讨伐军攻破阳平关时，前往成都请求救援。\n\n史：侍奉诸葛亮，为人忠实並常予以助言因此受到赞赏。在诸葛亮北伐时从军，诸葛亮死後统括汉中诸军。蜀国另还有外一位胡济。受命担任镇西将军，参加２５６年的姜维北伐。虽然是姜维的援军却无法会合，惨败给邓艾。２５８年，奉姜维命令进入汉寿。演义中将这两个人当作是同一个人。\n\n",
