    "biography": "吴国幕僚。\n\n演：孙策死後，应孙权的招揽加入阵营。\n\n史：牧童出身。受孙和提拔並立下功绩，得到了和陆逊、卜静等人齐名的名声。孙权成为车骑将军後，被中央招揽。２２２年，同吕範、贺齐在洞口防止曹休的攻击。因此功绩成为会稽太守，和吕岱讨伐山越表现活跃。返回中央後成为太子太傅。当孙权废太子孙和欲立孙霸时，便同陆逊取得连络强力反对，並向孙权进言将孙霸和杨竺调往地方。後来受到了孙霸和杨竺的中伤，而遭处刑。\n\n",
