    "biography": "魏国武将。胡敏之子，胡威之父。\n\n演：东莞太守。当吴国的周鲂将曹休引诱到石亭时，在贾逵的指挥下同满宠出兵濡须。\n\n史：从年少时就和蒋济、朱绩在淮水一带相当为人所知。还曾为张辽所託，希望能让温恢迎为部下。从东莞太守变成荆州刺史，在樊城击退吴国的朱然。接著成为征东将军掌握青州和徐州的军事力量。致力於农业发展，由於不将自己的想法强强制在别人身上，在每个任地都获得仰慕。\n\n",
