    "biography": "魏国官僚，朝歌县长。和曹丕交情甚笃。\n\n演：受到和曹植争夺继承之位的曹丕的商谈，而躲在衣箱裡进出曹丕的宅邸。虽遭曹植派的杨修密告，便将计就计把放了绢布的衣箱送进曹丕的宅邸，让门卫检查。接到报告的曹操认为杨修想要陷害曹丕，便疏远杨修。\n\n史：在迎送曹操出征之际，和赠送美丽词句的曹植相比，吴质则是叫曹丕无言的留下眼泪，因而得到曹操欢心。曹丕即位後其态度转变为傲慢，因此死後曾一时被称为醜侯。是代表魏国的文人之一。\n\n",
