    "biography": "张绣的武将。\n\n演：是个身背五百斤重物一天可走七百里的豪傑。当张绣因为曹操和邹氏私通，感到極为愤怒而袭击曹操时，将曹操的护卫典韦的双铁戟夺走使他失去战力。\n\n史：以张绣军中第一的武艺誇耀。在张绣向曹操投降後，被曹操称赞其武艺，並得到黄金。知道这件事情的张绣，以为曹操在讨好自己的亲信预谋要杀害自己，於是就决定计劃背叛曹操。\n\n",
