    "biography": "魏国武将。胡烈之父，胡渊的祖父。\n\n演：司马懿讨伐公孙渊时担任先锋，後来成为征东将军。孙权死後，和王昶、毌丘俭在司马师的命令下讨伐吴国。但在攻打东兴城时受到丁奉的奇袭，被部下桓嘉等人给击败。之後在毌丘俭掀起反叛时，和王基、邓艾等人协力镇压。\n\n史：被张既起用。２２３年匈奴的胡薄居姿职叛乱时，奉司马懿之命前去镇压。曾历任征东大将军、卫将军、车骑将军。\n\n",
