    "biography": "董卓的武将。\n\n演：在以袁绍为盟主的反董卓联盟来袭时，为华雄的副将防守汜水关。和联合军的先锋·孙坚交战时，被程普所杀。\n\n史：陈郡太守。当孙坚进军阳人时，同吕布前往迎击。但却引起吕布与诸将领的反感，於是传达友方假情报，在未能一战时就败走。並没有因和孙坚军一战而死的描写。\n\n",
