    "biography": "吴国丞相·顾雍之子。「吴之四姓」的顾家之後。\n\n演：没有记载。\n\n史：和诸葛恪、张休、陈表同为皇太子·孙登的学友。其广博的见识无人能出其右。顾雍死後成为太常。对於冷落太子·孙和而宠爱鲁王·孙霸的孙权，进言应该要明辨嫡子和庶子之分。於是和孙霸的关係恶化。再加上蔑视孙霸派的全奇，因此被全琮父子陷害被流放到交州。由此怨愤而写了「新言」20卷。在遭到流放的两年後，以42岁之龄死去。\n\n",
