    "skills": [],
    "biography": "乌戈国王。身高一丈二尺。生吃活蛇及野兽，身上覆盖著鳞片且刀枪不入。率领著穿著浸过油且日曬过的藤蔓铠甲的藤甲兵。藤甲兵身著铠甲渡河，虽是刀枪不入，但火是唯一弱点。\n\n演：受诸葛亮六擒六放的孟获最後投靠的蛮族之王。骑著大象率领著藤甲兵压制住蜀军。追著战败而逃的魏延被引诱到盘蛇谷，受到由诸葛亮所策劃的火攻而全灭。由於之後，孟获才对诸葛亮感到心服口服。\n\n史：没有记载。\n\n",
