    "skills": [],
    "biography": "曾服侍桓帝的胡华之子。曹操的荥阳太守·王植的从事。\n\n演：降於曹操的关羽为了返回刘备阵营通过荥阳时，奉王植之命要烧死关羽。但由於关羽持有胡华的书信，加上自己也推崇关羽的人品因而放行。之後投靠关羽前往荆州。当刘备成为汉中王，关羽被任命为五虎将军时，以关羽代理人的身份被派遣到成都，受取爵位。\n\n史：没有记载。\n\n",
