    "biography": "蜀国武将。何进的武将吴匡之子，吴懿的族弟。\n\n演：张飞的副将。在张飞被范彊和张达所杀害後，便成为关羽和张飞復仇战的先锋，向吴国进军。依张南和冯习的指示在夷陵包围孙桓，因刘备败给陆逊而撤退。之後成为後将军参加诸葛亮的北伐。在第五次的北伐中，同吴懿奉命烧掉魏军的浮桥，不料被司马懿识破而被张虎和乐綝所杀。\n\n史：在蜀国时，经常得到仅次於吴懿的官位。刘禅时代成为骠骑将军。在北伐时大破张郃。並没有战死的记载。\n\n",
