    "biography": "刘备的武将。\n\n演：服侍刘璋。在刘备攻蜀时，同刘循、吴懿、雷铜前往救援受困於雒城的张任，结果因被抓而投降。後来成为刘备部下的将领。和曹操进行汉中攻防战时，在马超的指挥下防守下弁，被曹洪击败。之後，在汉水附近遭遇援助曹操而来的曹彰，大战数回合後被杀。\n\n史：並没有身为刘璋部下的记载。２１８年，奉刘备之命同雷铜进攻武都，败给曹洪、曹休、张既而全灭。被氐族的强端所斩杀。\n\n",
