    "biography": "魏国武将。胡遵之子，胡奋之弟，胡渊之父。\n\n演：参加锺会的蜀国讨伐战。在蜀国投降後，因为拒绝与锺会和姜维共同谋反而成为阶下囚。在前部下丘建牵引下前来的胡渊等人将锺会和姜维杀死，使得逃过一劫。\n\n史：参加诸葛诞的反叛镇压军，烧光吴国朱異所看守的兵粮。在蜀国讨伐战中和田续、庞会包围姜维，接收了姜维所送的投降信。镇压了锺会和姜维的谋反後，前去西陵援救受陆抗包围的罗宪，並击退陆抗。历任襄阳太守、荆州刺史。\n\n",
