    "skills": [],
    "biography": "魏国官僚。崔林的堂兄，郑玄的弟子。\n\n演：虽然曾经服侍袁绍，但在曹操压制邺城後就加入其阵营。此时，对得到户籍且对冀州的豐饶感到喜悦的曹操诉说人民的辛苦，並加以劝诫。曹操为丞相时进入丞相府，在曹操为魏公後担任尚书。但在曹操计劃自立为魏王时，独自一人反对並大声痛骂曹操奸贼，最後被杀。\n\n史：和司马朗甚亲，早先也就获得司马懿的评價。写给自己所推薦的杨训的书信中的一节，由於有批判时事的内容，因此惹恼曹操而自杀。\n\n",
