    "biography": "女流诗人。学者·蔡邕之女，原卫道玠之妻。\n\n演：被匈奴带走，以琴曲歌辞「胡笳十八拍」咏唱自己流離遭遇的悲伤。当和蔡邕有深交的曹操在河北的势力扩大，打算用千金买回时，便被畏惧曹操势力的左贤王给送回来。之後，在曹操的说媒下，成为董纪（正确应该是董祀）的妻子。在曹操即将出征和刘备的汉中功防战时，在莊园受到曹操的访问，两人合作解开蔡邕的遗书之谜。\n\n史：现存的遗作有「悲愤诗」。「胡笳十八拍」据说是别人对蔡邕的境遇感到悲伤而咏唱的。\n\n",
