    "biography": "刘表的重镇·蔡瑁的堂弟。和蔡中是兄弟。\n\n演：当蔡瑁想暗杀进驻新野的刘备时，曾加入和蔡瑁合作。当继承刘表的刘琮向曹操投降後，成为曹操的部下。在赤壁之战前蔡瑁被曹操处刑後，为了挽回名誉假装向孙权军投降。被周瑜识破为「埋伏之毒」而置於不顾。之後将黄盖遭到棒刑一事使其通知曹操，让曹操对黄盖的诈降信以为真。赤壁之战开始後，被带到周瑜面前处死。\n\n史：没有记载。\n\n",
