    "biography": "刘表的续絃，蔡瑁之姐。刘琦的义母，刘琮之母。\n\n演：对於投靠刘表而进入新野的刘备早先开始戒备，同蔡瑁策劃放逐或杀害刘备的计劃。刘表将死之际，策劃置刘琦一旁而立刘琮为继承者。刘表死後，伪造遗言将刘琮立为後继者。在刘琮向曹操投降後，和刘琮同行前往青州时，双双被于禁所杀。\n\n史：並非刘琮的亲生母亲。因为姪女成为刘琮之妻，所以才对刘琮特别偏爱。並没有同刘琮被于禁所杀的记载。\n\n",
