    "biography": "刘表的重镇·蔡瑁的堂弟。和蔡和是兄弟。\n\n演：在蔡瑁欲暗杀投靠刘表而进入新野的刘备时，曾协助蔡瑁。刘表死後，刘琮向曹操投降时，臣服於曹操。在赤壁之战前蔡瑁被曹操处刑後，同蔡和假装向孙权军投降。被周瑜识破为「埋伏之毒」而置於一旁不管。之後将黄盖遭周瑜处以棒刑一事使其通知曹操，让曹操对黄盖的诈降信以为真。赤壁之战开始後将甘寧引到曹操阵营，後被砍杀。\n\n史：没有记载。\n\n",
