    "biography": "刘表的武将。刘表的续絃·蔡氏之弟。\n\n演：当孙坚依照袁术的指示攻打刘表时，和孙坚一战後失败，但因刘表的亲戚缘故而免於一死。在刘备投靠刘表进入新野时，同蔡氏企图暗杀刘备。刘表死後，捏造遗言让外甥刘琮成为继承人。但是看出曹操南下的动静时，便指示刘琮投降，受曹操任命为水军都督。和孙权军一战之前整备水军，其气势让周瑜大感震惊，不过却因为周瑜的计谋而被懷疑为内奸，同张允一起被杀。\n\n史：刘琮为姪女之夫。並没有被曹操处死的描述。\n\n",
