    "biography": "魏国官僚。崔琰的堂弟。\n\n演：没有记载。\n\n史：在曹操平定冀州後被起用。魏建国时成为御史中丞，曹丕即位後被任命为尚书。後来虽然为幽州刺史，却因为不懂得谄媚上司而遭左迁，令人惋惜。曹叡即位後成为光禄勋、司隶校尉，最後升为司空。从平民中提拔後来成为名士的王经，而广受称赞。\n\n",
