    "biography": "扬州刺史·刘繇的武将。\n\n演：迎击进攻江东的孙策但被击败，同刘繇投靠刘表逃亡到豫章。\n\n史：投靠徐州牧·陶谦，负责监督物资的运送。将物资占为己有累积财力，建造佛教寺庙。曹操攻击陶谦时逃往广陵，杀害曾礼遇待之的太守赵昱並大肆掠夺。之後同薛礼以刘繇为盟主和孙策对战而败，逃往豫章。杀害薛礼及豫章太守的朱皓，被企图自立为王的刘繇所击败，逃跑中被当地人民所杀。\n\n",
