    "biography": "魏国武将。\n\n演：在邓艾的指挥下和姜维的北伐军战鬥。邓艾和锺会挑起蜀国讨伐战时，随邓艾越过阴平的捷径攻击绵竹关。虽曾一度和邓忠败给诸葛瞻，但再次出击时成功地攻下绵竹关。降伏了刘禅後，被任命为益州刺史。\n\n史：虽然曾是邓艾军的武将，在向蜀国投降後，和锺会、胡烈等人联手，上奏邓艾有企图谋反的举动。但却在邓艾父子被卫邓和田续杀死时一起被杀死。\n\n",
