    "biography": "司马懿之孙，司马昭的长子，司马攸之兄。晋武帝。\n\n演：司马昭死後继承晋王之位。之後随即派遣心腹贾充等人迫使魏帝·曹奂退位，然後登上帝位。当吴国陆抗遭到罢免，由羊祜上奏讨伐吴国时，被贾充、荀勗、冯紞等劝阻暂缓出兵。羊祜病死後，由王濬、杜预再度上奏後决定出兵。派遣杜预、司马[0xFA][0x40]、王浑、王戎、胡奋、王濬、唐彬、杨济等人出击灭了吴国。\n\n史：晋朝时是将兵权给予各个皇族並给予封地。当皇帝的势力衰弱时，各地的皇族纷纷独立而导致了「八王之乱」。\n\n",
