    "biography": "魏国重臣·司马懿的长子。司马昭之兄。晋景帝。\n\n演：跟随司马懿，在防禦诸葛亮的北伐军和讨伐公孙渊时十分活跃。２４９年的政变时打倒政敌曹爽掌握政权，在司马懿死後成为大将军。之後拥有比皇帝还要大的实权，虽然差点被曹芳诛杀，但是防範於未然。之後废曹芳立曹髦，将协助曹芳的夏侯玄、李豐、张缉处刑。亲自镇压反对废曹芳而发起叛乱的毌丘俭、文钦，不过不久後就死去。\n\n史：孙权死後下令讨伐吴国失败。自己负起了责任，並未处罚指挥官王昶、胡遵、毌丘俭等人。\n\n",
