    "biography": "司马懿的次子，司马师之弟，司马炎、攸之父。晋文帝。\n\n演：跟随司马懿，在防禦诸葛亮的北伐军和讨伐公孙渊时十分活跃。在其兄身为大将军的司马师死後继承政权。在反司马家的诸葛诞叛乱时，拥立魏帝·曹髦並加以镇压。虽然险被害怕自己威望的曹髦所杀，但是防範於未然。杀了曹髦拥立曹奂，並将协助曹髦的王经处刑。２６３年派遣锺会和邓艾灭蜀国。翌年成为晋王。\n\n史：从晋公升格为晋王时，对巴结自己的太尉王祥给予厚待。\n\n",
