    "biography": "司马懿的六男。司马师、司马昭之弟。\n\n演：晋国司马炎时代被封为镇东大将军、琅邪王。２７９年参加吴国讨伐战，率先与降伏孙皓的王濬军队会合，同庆讨伐成功。\n\n史：魏国兖州刺史。在魏帝·曹髦和王经等人共谋企图讨伐司马昭时，同贾充等人攻打曹髦。在平定吴国後升为大将军。\n\n",
