    "biography": "魏国官僚。司马懿的次弟，司马望之父。\n\n演：对曹操死後曹丕的即位很有贡献，历任尚书、尚书令。在司马懿夺取曹爽政权时协助司马懿。在司马师废掉曹芳後，看出郭太后的意图提议拥立曹髦。在曹髦被司马昭派的贾充所杀害之後，跪地抱著遗體痛哭，令司马昭允许可以君王之格下葬。司马炎即位时，受封为安平王却拒绝，贯彻身为魏臣的立场。\n\n史：在诸葛恪攻打合淝新城时，负责防卫的指挥。也以邓艾的後续部队与姜维的北伐军交战。\n\n",
