    "biography": "魏国武将。司马孚之子，司马朗的养嗣子。\n\n演：２５８年，姜维进攻长城时，率领王真、李鹏抗战而败，被邓艾所救。同年，姜维出兵祁山时，和邓艾一同迎击。看穿姜维所佈的「长蛇捲地之阵」，並和姜维在阵势上一较高下（和诸葛亮的好友崔州平、石广元交情甚笃缘故，因此知道姜维向诸葛亮所学的兵法）。２６３年，当邓艾和锺会进行蜀国讨伐战时，在邓艾的指令下牵制羌族。\n\n史：为叔父司马朗的後继。在魏国被封为司徒，在晋国时被封为义阳王，历任大尉、大司马。\n\n",
