    "biography": "司马昭的次子，司马炎之弟。因为伯父司马师没有子嗣，所以成为他的养嗣子。\n\n演：由於武艺優秀，性格温厚的缘故受到司马昭的宠爱。本来被成为晋王的司马昭指名为继承人，却遭到山涛、贾充、何曾、裴秀、王祥、荀顗等人的反对，由其兄司马炎成为继承人。\n\n史：司马炎即位後被调離中央封为齐王。指责司马炎对其弟的处置太过分的曹志遭到免职，司马攸本人最後也因忧鬱而死。\n\n",
