    "biography": "司马懿、司马孚之兄，司马遗之父。\n\n演：服侍曹操，为丞相主簿。\n\n史：在董卓迁都长安而荒废洛阳时，带领家人逃难。後来服侍曹操，历任堂阳太守、兖州刺史等地方官，由於广施德政而备受爱戴。２１７年，同夏侯惇、臧霸参加吴国讨伐战。在疫病蔓延时也亲自巡查给予医药，最後却染病而死。在曹叡时代，司马孚之子·司马望成为继承人。和崔琰相当亲近。\n\n",
