    "biography": "吴国武将。\n\n演：在刘备为了帮关羽报仇攻入宜都时，追随孙桓迎击。和张苞大战30余回合，最後仍不敌败北。翌日，为了保护孙桓挡在张苞面前，而一刀被杀死。\n\n史：陆逊击破关羽压制荆州後，同李異率三千兵力攻打蜀军。击破詹晏、邓辅、郭睦等人，並拿下陈凤。此外，在陆逊的指挥下击破文布、邓凯。並没有和进攻荆州的刘备交战的记载。\n\n",
