    "biography": "五溪的蛮族之王。使用铁蒺藜骨朵。\n\n演：在蜀帝·刘备为了帮关羽復仇而对吴国发起的夷陵之战时加入蜀军。不顾自己生病出阵，结果被吴国的甘寧射杀。另一个说法是，在吴国淳于丹发动夜袭的时候，曾经成为伏兵断了敌军的後路。可是由於陆逊的火计使蜀军节节败退，在沙摩柯单枪匹马逃走时遇到了周泰。大战20多回合後由於筋疲力竭被砍死。\n\n史：在夷陵之战中加入蜀国的異族首领。遭遇陆逊的火攻而被砍杀。並没有被甘寧杀掉的记载。\n\n",
