    "biography": "吴国武将。朱桓之子。「吴之四姓」的朱家之後。\n\n演：在魏国诸葛诞反叛的时候，在孙綝的命令下前往援救诸葛诞。可是却连续败给王基、锺会、司马昭，被極为愤怒的孙綝所杀。\n\n史：和孙权互相辩论战略，被赞为比传说中更大胆的人物。２５２年，在魏国的胡遵和诸葛诞进攻东兴时，率领水军迎击获得大勝。２５７年成为大都督，前往救援在寿春四处起义的诸葛诞，却因兵粮不足而撤退惹火了孙綝。在返回时不顾陆抗的制止和孙綝见面，当场被杀死。\n\n",
