    "biography": "会稽太守·王朗的武将。周昂之兄。\n\n演：与进军江东的孙策军的首战中曾和黄盖战鬥。之後，由於中了孙策的计谋同颜白虎出城之际，被埋伏的孙策给一击杀死。\n\n史：拜陈蕃为师研究学问，对於风水还有预知灾害相当拿手。为丹阳太守，当败给董卓军徐荣的曹操在扬州募兵时，曾同扬州刺史·陈温予以援助。之後，被袁术所派遣的吴景夺走丹阳，便投靠会稽太守·王朗。孙策进攻会稽郡时，迎击败北而遭杀害。\n\n",
