    "biography": "黄巾大将·张宝的武将，後改仕关羽。\n\n演：黄巾之乱後成为卧牛山的山贼时，遇见关羽便臣服於下。之後常与关羽共同行动，在关羽的指挥下防守荆州。在要求退还荆州的鲁肃和关羽会面时担任护卫，运用機智结束了这场会面。之後和于禁、庞德在襄阳一战时，被庞德打落水中而受俘。当关羽战死麦城时，也随之自杀身亡。\n\n史：没有记载。虽是捏造的人物却在多数的民间故事中有登场。在绘画中，常见於同关平被绘在关羽的左右。\n\n",
