    "biography": "吴国武将，扬子江的江贼。周平之兄。\n\n演：和同为江贼的蒋钦支持孙策，並被孙策所登庸。追随孙权防守宣城时被山贼袭击，虽全身受到枪伤依然将孙权救出。在之後的赤壁之战、合淝攻防战、夷陵之战中皆以主力将参战。特别是２１５年的合淝攻防战，救出受魏军包围的孙权和徐盛，並被孙权赐与青绢伞。\n\n史：成为濡须督时，麾下的朱然、徐盛等人有所微词，但在孙权指著周泰一个又一个的伤痕並叙述其功绩时，才使朱然等人心服口服。\n\n",
