    "biography": "魏国兖州刺史。和邓艾是同州出身的同辈。\n\n演：当诸葛诞在寿春起义时，加入司马昭所领的镇压军担任右翼。在吴国朱異以诸葛诞援军前来救援时，在钟会的计策下，被所释放的牛马冲撞的吴国士兵混乱之际，和石苞夹击击退。\n\n史：被荆州刺史的裴潜任用。数度被派遣为使者前访进驻在宛的司马懿，成为司马懿的知己。在司马懿讨伐孟达时担任先行部队。後来历任兖州、豫州刺史，成为征虏将军统括江南的军事。\n\n",
