    "biography": "吴国鄱阳太守。周处之父。\n\n演：２２８年，向魏国的曹休诈降，叙述灭吴的七项理由使其发起吴国讨伐军。进入皖城的曹休曾一度懷疑此为计谋，於是周鲂切断自己的发髻以得曹休的信任。之後进入石亭的曹休大败给了陆逊。\n\n史：将写满对吴国不满的七封书信送往魏国，被懷疑是内奸而断然剃发。聽到此事的曹休相信周鲂的投降。在石亭击破曹休後，成为裨将军。治理鄱阳１３年，留下了優秀的政绩。\n\n",
