    "biography": "孙策的义兄弟，其妻为小乔。扬州的名士。\n\n演：协助孙策的江东进军战。孙策临死时，留下了如有国家大事务必找周瑜商讨的遗言。孙策死後服侍孙权，並推举了鲁肃。曹操进攻江东时，主张和刘备军结盟抗战。任大都督率领孙权军，在赤壁之战大破曹操军。之後，进军曹操军所在的江陵时，苦战於曹任並且负伤。最後江陵被诸葛亮夺走，便在苦闷之中去世。\n\n史：与诸葛亮的谋略战和气量狭小是演义中的虚構情节。赤壁之战的勝利和委让荆州南部给刘备军，皆由周瑜所主导。\n\n",
