    "biography": "吴国武将，朱異之父。「吴之四姓」的朱家之後。\n\n演：孙策死後，受到孙权的招揽。夷陵之战後，曹丕进攻吴国时，在濡须迎击曹仁。以空城计引诱曹仁军，击破诸葛虔、王双，並且杀了常雕。在石亭之战童同全琮成为陆逊军的都督，大勝曹休军並杀死张普。\n\n史：在镇压山越叛乱时表现活跃，接受周泰之後成为濡须督。孙权即帝位後成为前将军、青州牧。自视甚高厌恶他人的指使。曾发生因作战方式和全琮对立，便任性返回建业一事。\n\n",
