    "biography": "吴国武将，朱桓的同族。「吴之四姓」的朱家之後。\n\n演：没有记载。\n\n史：被孙权期待为吕蒙、张温的继承人。在孙权即位後为左将军，並迎娶孙权之女·孙鲁育，後晋升为骠骑将军。但在太子·孙和与鲁王·孙霸争夺孙权後继之位时，因支持孙和而向孙权直言时招致孙权大怒。被左迁至新都郡丞，在孙权卧病在床时被孙弘所发出的假诏令命其自杀。\n\n",
