    "biography": "南蛮王·孟获之妻。带来洞主之姐。古代南方火神·祝融的末裔。使用飞刀的名手。\n\n演：诸葛亮南征时丈夫数次被捕，便愤而出阵。虽以单挑战勝並捕捉了蜀国张嶷和马忠，却败给魏延和赵雲而受俘。同其丈夫不願向诸葛亮投降，最後以张嶷、马忠为人质交换被释放。之後虽同丈夫数次被捕，但仍坚持不肯屈服。当孟获第七次被抓，终於对诸葛亮心服口服後，也跟丈夫一起投降。\n\n史：没有记载。\n\n",
