    "biography": "东汉官僚。\n\n演：张角掀起黄巾之乱时，奉何进的命令同卢植、皇甫嵩担任镇压。得曹操、刘备、孙坚等人所助击破张宝，对镇压叛乱有所贡献。因此成为车骑将军、河南尹，却因拒绝向宦官行贿而遭罢免。董卓死後，李傕和郭汜掌握政权时被招为太僕。後来为了劝解关係交恶的李傕和郭汜而被逮捕。在释放後病死。\n\n史：黄巾之乱中招孙坚加入指挥之下，因勇於奋战，在黄巾之乱平定後提升了孙坚。反对董卓迁都长安。\n\n",
