    "biography": "吴国武将。原名施然，为朱治的养子。\n\n演：在吕蒙进攻荆州的关羽时从军。为关羽復仇而进攻荆州的刘备来袭时，虽同孙桓迎击，却因蜀国吴班的计谋使副将崔禹被杀迫使暂且撤退。在重新指挥迎击的陆逊的命令下进行火攻，追击战败而逃的刘备。但却被赵雲所阻挡並一击刺死。\n\n史：夷陵之战後，击退魏国夏侯尚等人守住江陵。同孙权为共勉学问的夥伴，在陆逊死後成为吴国的重镇。官升左大司马、右军师。\n\n",
