    "biography": "吴国武将。将其姐之子·朱然收为养子。\n\n演：从孙坚时代就为吴国效命。孙坚死後，向袁术保护下的孙策劝说进军江东並且自立。在孙策压制住吴郡时就任吴郡太守。在赤壁之战中同吕範担任四方巡警使。\n\n史：２０２年，孙权时代为吴郡太守，平定山越和黄巾残黨的陈败和万秉等人。２２３年成为安国将军。在孙权成为吴王之後，朱治前来晋见孙权时，也受到孙权亲自迎接的礼遇。此外，喜怒形於色的个性常受到孙翊的劝告。\n\n",
