    "biography": "原为袁绍的武将，後改仕曹操。\n\n演：受曹操所命，同路昭加入为讨伐袁术而进入徐州的刘备军。袁术死後，将士兵交给企图自立的刘备而返。为此举曹操大怒，但在荀彧的说情下才逃过一死。渭水一战中同徐晃渡黄河为伏兵，取得夹击马超的攻势。\n\n史：在曹操进攻陶谦被袁绍以援军派遣前去时，见曹操是位名君，便就此改仕曹操。但却因为和曹操个性不和，曾被褫夺兵权成为于禁的部下。在曹丕时代升为後将军。\n\n",
