    "biography": "曹操的参谋。荀昆之子，荀攸的伯父。原是袁绍的部下。\n\n演：加入为平定兖州黄巾残黨而在招募人才的曹操阵营，被评为有如张良一般的人物。被吕布夺去兖州时，同程昱死守三县。曾向曹操进言保护脱離李傕的献帝，以及鼓励官渡之战後因居劣势而丧气的曹操等，以第一谋臣支持著曹操军。但却因反对曹操就任魏公而引起曹操不满，受曹操送来一食器，内空无一物（即已经没有用的意思），於是服毒自尽。\n\n史：出自三公名门之後。被评为辅佐王者之才。\n\n",
