    "biography": "东汉官吏，後改仕袁绍。\n\n演：在何进暗杀混乱当中，脱離而出的少帝和陈留王返回时，曾前往迎接。後来服侍袁绍並参加官渡之战。成为守护乌巢的兵粮基地的大将。但由於生性嗜酒，在烂醉如泥时遭曹操军奇袭成了俘虏。之後虽平安地回到袁绍身边，却被盛怒的袁绍给砍死。\n\n史：黄巾之乱後，同蹇硕、袁绍、曹操等人被任命为西园八校尉。在乌巢和曹操军奋战後被捕，因拒降为曹操所惋惜而处斩。\n\n",
