    "biography": "魏国尚书。荀彧的四子，陈泰之舅。\n\n演：司马昭杀了曹髦之後，前去召唤拒绝进宫的陈泰时，被陈泰感叹言道「义父大人难道成为比我还不如的人了吗」。後为司空，在成为晋王的司马昭苦恼选择继承者时，便以遵从长幼有序的伦理推举了司马炎。\n\n史：被司马懿评为「果然不愧为荀彧之子」。因讨伐毌丘俭有功成为司空。以晋的建国功臣晋升侍中、太尉，並受封为临淮公。博学多闻並熟知三礼经通朝廷礼仪。和何曾並称为至仁至孝之人。\n\n",
