    "biography": "魏国从事中郎。\n\n演：当蜀国姜维在沓中屯田时，反对主张暗杀姜维的贾充，而以蜀国宫廷腐败为由主张军事攻击。进言以邓艾为主将，锺会为副将发起蜀国讨伐军，被司马昭採用。之後改仕晋国，在羊祜上奏进行吴国讨伐战时，同贾充、冯紞共谏司马炎，使作战中止。\n\n史：在晋国历任侍中、尚书令，和贾充等人制定晋律。此外还跟张华整理古书，将其分为经、子、史、集四类。\n\n",
