    "biography": "冀州牧·韩馥的幕僚，荀彧之弟。後改仕袁绍。\n\n演：接到公孙瓒进攻冀州的报告的韩馥欲招揽袁绍之时，同辛评共策善後计劃。之後就顺势侍奉进入冀州的袁绍。在官渡之战前，当袁绍询问幕僚们是否与曹操开战时，建议交战，使袁绍决定和曹操一决勝负。\n\n史：一开始就是袁绍的幕僚。说服韩馥将冀州让给袁绍。在「魏书」中为荀彧之弟，在「荀氏家传」中却是荀彧之兄。\n\n",
