    "biography": "诸葛诞的武将。後改仕司马昭。\n\n演：和反叛司马招的诸葛诞共同死守寿春城。受司马昭军围城时，和同僚蒋班共主张早期决战。但却被诸葛诞拒绝，和蒋班双双逃城而出向司马昭投降。\n\n史：同蒋班主张在城外决战，但文钦却主张笼城战策，加上诸葛诞意图杀害蒋班，於是两人一同出城投降。\n\n",
