    "biography": "魏国重臣·锺繇之子，锺会之兄。\n\n演：八岁时，同锺会拜见曹丕时，与怡然自得的锺会相比之下，锺毓则是满头大汗显得相当惶恐。\n\n史：在诸葛亮进军祁山时，劝谏想亲自迎击的曹叡。之後在曹爽远征蜀国时，因炎夏暑热陷入苦战之际建议撤兵。之外也上奏希望能减轻农民的税赋以振兴农业，考虑人民的劳苦而不断献策。之後历任御史中丞、侍中、廷尉、尚书、青州刺史，後来统括徐州和荆州的军事。\n\n",
