    "biography": "魏国重臣·锺繇的么子，锺毓之弟。\n\n演：在司马师讨伐毌丘俭、司马昭讨伐诸葛诞时从军。适当时機时献上适当策略，被司马昭喻为张良。２６３年同邓艾共指挥蜀国讨伐战，攻下汉中並把姜维包围在剑阁。之後在邓艾攻陷成都灭掉蜀国後，被邓艾加上莫须有的反叛罪名而被逮捕。之後和企图復兴蜀国的姜维共计自立，被原为指挥下的胡渊、卫瓘所袭击，同姜维双双被斩杀。\n\n史：在蜀国禁止士兵掠夺，並敬重原蜀国之臣，以仿邓艾笔迹送出不敬的上奏文，而被懷疑为有谋反的意图。\n\n",
