    "biography": "魏国谋臣，周瑜的同窗。\n\n演：在赤壁之战为了劝降周瑜而来到孙权的阵营。将周瑜伪造的蔡瑁和张允背叛的书信交给了曹操，让曹操杀了蔡瑁和张允。为了挽回名誉再次造访周瑜时，却也如周瑜所算计的邀庞统前去曹操军，促使赤壁之战最大的败因，即连环计的成功。\n\n史：因大方的风格和善辩的口才，为淮水一代知名的秀才。未有和周瑜是同窗的记载。赤壁之战後，企图遊说孙权和周瑜反目但却失败。\n\n",
