    "biography": "乔氏，周瑜之妻。孙策之妻·大乔之妹。\n\n演：乔国老之女。以绝世美女的相貌广为人知，和嫁给孙策的大乔並称「二乔」。孙策临终之际，交代周瑜务必辅佐孙权的遗言。赤壁之战前，聽到诸葛亮说曹操希望二乔住在铜雀台的周瑜大为愤怒，因此促使决定和曹操决战。\n\n史：和周瑜相亲相爱的模样，以及鼓励在曹操大军前感到胆怯的周瑜等的故事，经常在绘画还有戏曲的题材中出现。\n\n",
