    "biography": "吴国武将。原为扬子江的江贼。\n\n演：孙策进军江东时，和同是江贼的周泰成为孙策的部下。在孙策死後服侍孙权。在周瑜的指挥下参加赤壁之战、南郡攻略战，在孙权进攻合淝的时候担任後卫部队。也参加由吕蒙发起的荆州攻略战，劝告被包围的关羽投降。\n\n史：在孙策还在袁术的保护下时，同周泰以亲信随侍。被孙权指出学问的重要性後，便同吕蒙奋发向学。在打倒关羽的回程途中病死。\n\n",
