    "skills": [],
    "biography": "魏国幕僚。\n\n演：在关羽北上包围曹仁时，同司马懿劝谏因害怕关羽气势而打算迁都的曹操。後来成为太尉，在司马懿讨伐曹爽一派而掀起政变时，协助司马懿取回兵权。\n\n史：赤壁之战後，成为辅佐扬州刺史·温恢的别驾，活跃在对吴国的战线中。在夺取曹爽兵权时，对於转告曹爽仅处以免职，不料却遭到满门抄斩一事而耿耿於懷，最後病死。著有「万機论」和「三州论」，不停的在文武两面献上優秀的计策。\n\n",
