    "biography": "蜀国官僚、学者，原为刘璋部下。通天文。\n\n演：在刘璋受刘备包围时，说服向刘备投降是为天意。後改仕刘备，同诸葛亮等人劝服刘备登上帝位。在诸葛亮出兵五丈原时表示反对，也在姜维想趁著魏国诸葛诞叛乱时派军北伐时，著「仇国论」一书劝谏姜维。在邓艾的军队逼近成都时劝告刘禅投降，隔年，随刘禅移住洛阳。\n\n史：著作有「法训」「五经论」「古史考」等。不让国家遭受毁灭一事得到司马昭的评價。\n\n",
