    "biography": "蜀国武将。\n\n演：追随姜维北伐得到信任，同传佥共防阳平关。在锺会的军队攻进阳平关时，因畏惧对方的气势，在传佥出阵之际投降将阳平关交给锺会。\n\n史：担任武兴督察时，由於毫无功绩而被调派为汉中太守的辅佐。据说因此懷恨在心而决定投降。锺会的军队来袭时，和主张採取笼城战的传佥分離，前往阴平向魏国的胡烈投降。\n\n",
