    "biography": "袁熙的武将。\n\n演：在曹操灭了袁谭之後，和同僚张南向曹操投降。在曹操攻击逃往袁熙阵营的袁尚时，和其他的降将共同追赶袁尚兄弟。之後参加曹操的南征。在长阪坡之战包围抱著刘禅逃跑的赵雲，但却被赵雲突破重围。在赤壁一战之初同张南挑战孙权军，被韩当用枪刺杀身亡。在演义中有幾处将此人物误记为乌丸触。\n\n史：在改仕曹操之前，曾经威胁诸郡太守和各县令长要支持曹操。\n\n",
