    "biography": "蜀国武将，向朗之兄之子。\n\n演：在诸葛亮的「出师表」裡出现。精通军事，刘备对他也有不错的评價，因此被推举为都督。在诸葛亮出发北伐後，以御林军总督的身份防守成都。\n\n史：在刘备时代成为牙门将军。在夷陵之战蜀军败北的时候，只有向宠的军营毫发无伤。２４０年，在讨伐汉嘉郡的異族时战死。\n\n",
