    "biography": "魏国官僚。\n\n演：２６３年，在司马昭命令锺会发起蜀国讨伐战时，进言说「锺会是个野心家，不应该把兵权委任给他」。在锺会和邓艾灭了蜀国後，锺会上奏说邓艾有谋反的嫌疑，当司马昭打算出兵逮捕邓艾时，进言「只要命令锺会逮捕邓艾就好了」。司马昭就反问邵悌「你以前不是说过锺会很危险吗。所以这次的出兵是为了讨伐锺会的」，邵悌回答说「以为您已经忘了，所以故意说的」。\n\n史：没有「我以为您已经忘了我以前的进言等等」这些话的记载。\n\n",
