    "biography": "诸葛诞的武将。後改仕晋国。\n\n演：和反叛司马昭的诸葛诞死守寿春城。在城受司马昭军包围时，和同僚焦彝主张在城外进行早期决战，而险被固执於笼城战的诸葛诞所杀，於是就同焦彝向司马昭投降。\n\n史：在毌丘俭和文钦反叛司马师时，追随诸葛予以镇压。接著击破前来救援文钦的吴国孙峻、吕据，並杀了留赞。後来侍奉於晋国，２７９年参加吴国讨伐战。在版桥之战中和薛勝一起击败张悌、沈莹、孙震等人。\n\n",
