    "biography": "蜀国四相之一·蒋琬之子，蒋显之兄。\n\n演：２５８年，参加姜维的北伐，同王含指挥左翼军队，却因为受到邓艾的夜袭而败退。之後就担任汉城的守备。２６３年，在锺会攻陷汉中之後就向魏军投降。\n\n史：在被锺会包围在汉城时，交换书信表达彼此的敬意。刘禅投降之後降於涪的锺会，受到锺会如好友一般的对待。翌年，被捲入锺会的叛乱，在乱战中和其弟蒋显一同死亡。\n\n",
