    "biography": "魏国重臣。锺毓、锺会之父。\n\n演：後来服侍曹操，就任长安太守。２１１年，被马超和韩遂所攻夺走长安。当曹操成为魏王後担任相国，在曹叡时代成为太傅。在诸葛亮北伐时，推薦司马懿为迎击的指挥官。\n\n史：服侍受李傕和郭汜支配下的长安的献帝，之後在荀彧的推薦下服侍曹操。在官渡之战中除了指挥马超击破袁绍军的郭援，还尽力於後方支援，被赞为足以和汉朝的萧何匹敌。２１９年，因身为兴起谋反的魏讽的推薦人，曾经一时被免职。\n\n",
