    "biography": "刘备的幕僚，向宠的叔父。\n\n演：在诸葛亮前往援助苦战於压制益州的刘备时，奉命留在荆州辅佐关羽。\n\n史：以司马徽为师，和徐庶、韩嵩、庞统等人有著深交。虽原本服侍刘表，但在刘表病死後转为刘备效命。在刘备平定蜀国後，历任巴西、房陵太守。在诸葛亮前往压制南蛮时代理丞相府的职务，在诸葛亮开始北伐时前往汉中赴任。但却为了袒护朋友马谡遭到免职而返回成都。之後成为光禄勋、左将军，被授予仅次於三公的特进之位。\n\n",
