    "biography": "东汉荥阳太守。董卓的部下。\n\n演：出迎迁都长安途中的董卓，並攻击追击董卓而来的曹操。遵从李儒的作战以伏兵大破曹操，之後並追击用箭射伤曹操的肩膀。但是由於遭遇到前来援救曹操的夏侯惇，战了数回合後被杀死。\n\n史：向董卓推薦同郡出身的公孙度，让公孙度成为辽东太守。虽然在荥阳大勝曹操，但见到曹操军兵力虽薄却極为奋战，判断不易获勝之下，便放弃追击撤退而返。\n\n",
