    "biography": "吴国官僚。诸葛瑾的长子，诸葛乔之兄，诸葛亮的外甥。\n\n演：聪明伶俐受到孙权宠爱，为太子·孙登的学友。在陆逊死後掌握实权，於孙权死後让孙亮即位。之後遭到魏国司马师的攻击，但成功地击退。虽趁势进攻合淝新城，但因夏季暑热而败退。企图将败战的责任转嫁他人以求自身安全，但却被孙峻、藤胤等人所暗杀。诸葛瑾生前就曾经预测，诸葛恪因过於聪明而将对诸葛家带来灾难。\n\n史：在孙权临终之际，被孙峻称为是无人能出其右的大才。曾关係亲近的滕胤並未参加暗杀之事。\n\n",
