    "biography": "吴国诸葛瑾的次子，诸葛恪之弟，诸葛亮的外甥。原本字仲慎，成为诸葛亮的养子。\n\n演：没有记述。\n\n史：与其兄诸葛恪齐名，得到的评價很高。虽然才能不及其兄，但性格受评较其兄为佳。受到尚无子嗣的诸葛亮收为养子。进入蜀国之後将字改为伯松。２２７年，在诸葛亮北伐时同行前往汉中，並和霍弋以记室（承相事务官）的身份到各军视察。死於２２８年。\n\n",
