    "skills": [],
    "biography": "吴国官吏。诸葛恪、乔之父，诸葛亮、均之兄。\n\n演：在鲁肃的推薦下服侍孙权。赤壁之战前，在诸葛亮为了刘备和孙权的结盟一事来访时再会，並遊说诸葛亮侍奉孙权。之後为了荆州的领土问题，作为孙权的使者和刘备与关羽交涉。在夷陵之战後，曹丕进攻吴国之际，同陆逊击退曹真和夏侯尚的军队。後来响应诸葛亮出征五丈原进攻襄阳，却败给曹叡。\n\n史：无论於公於私都避免和诸葛亮见面。和孙权彼此有超越生死的信赖关係。\n\n",
