    "biography": "诸葛珪之子。诸葛瑾、亮之弟。\n\n演：因诸葛珪早死，和其兄便由叔父诸葛玄所养育长大。在诸葛玄死後，同诸葛亮在卧龙岗的草庐务农为生。刘备第二次来访诸葛亮时还被误认为是诸葛亮。在第三次来访诸葛亮决定为刘备效命时，於是将草庐交由其管理。\n\n史：为蜀国效命，成为长水校尉，並没有在草庐和刘备应对的记载。\n\n",
