    "biography": "魏国雍州刺史，诸葛冲之父。\n\n演：２６３年，奉讨伐蜀国总将的邓艾所命令，断绝沓中姜维的後路。但见姜维有进攻雍州之意，於是举兵返回雍州让姜维得以突破。之後，攻击死守剑阁的姜维败退。险遭盛怒的锺会斩首，在诸将士的请命下逃过一劫，並被送到洛阳。\n\n史：在远征蜀国时，由於害怕蜀军而举兵不前，因而遭到锺会告发。被夺去军队及招回首都。後来为晋国效命，历任太常等职。\n\n",
