    "biography": "蜀国丞相·诸葛亮之孙。诸葛瞻的长子。\n\n演：在魏国邓艾攻打蜀国时，在绵竹关和父亲一同迎击。初战时立起诸葛亮的木像迎击邓艾军的邓忠、师篡等人，亲自奋勇作战击退二人。但等不及吴国援军到来就出阵的诸葛瞻战死後，不顾张遵的劝谏执意出阵，在乱战中战死。\n\n史：感叹「深受国家大恩，却未能及早剷除黄皓以致败北，活著何用？」之後，便冲向魏军战死。\n\n",
