    "biography": "魏国武将·诸葛诞之子。\n\n演：在诸葛诞叛乱时，作为向吴国要求援军的人质，和吴纲一同被送到孙綝的手下。之後为吴国效命，升至右将军。２７９年晋国发起吴国讨伐战时，同张悌、沈莹前往迎击，因太过居於劣势而主张投降时，却被张悌所拒。\n\n史：孙皓迁都武昌时，同丁固防守建业。山贼施但来袭时以牛屯击退。２６８年同丁奉进攻合淝。吴国灭亡後，虽被曾在年少时相当亲近的武帝·司马炎所邀任职侍中，但是断然拒绝。\n\n",
