    "skills": [],
    "biography": "蜀国丞相·诸葛亮的长子，母亲为黄氏（月英）。诸葛尚之父。迎娶刘禅的女兒，然後继承父亲的爵位。\n\n演：２６１年，被任命为行军护卫将军，因为黄皓掌握政权的缘故，就宣称生病窝在自家。２６３年，在绵竹关迎击侵略蜀国的邓艾。在战争序盘和诸葛尚一起立起诸葛亮的木像成功的击退了敌军。拒绝邓艾的劝降通告，诸葛尚也有继续战鬥的意願，可是最後却因为等不及吴国的援军而再度出阵，最後因为负伤而自杀。\n\n史：虽然无法成功保护蜀国，却因为没有背叛蜀国且遵从亡父的遗志，被称为忠孝之人。书画的技巧很高明。\n\n",
