    "biography": "西汉名臣·诸葛豐的子孙。虽是吴国诸葛锦、蜀国诸葛亮的堂弟，但却是为魏国效命。诸葛靓之父。\n\n演：在司马师讨伐叛乱的毌丘俭时从军，並有所表现。司马昭掌握实权时与其对立，得吴国孙綝之助而举兵。在初期战时杀了乐綝。但却被司马昭包围寿春城，並将反对迎击策的文钦斩首陷入孤立。结果寿春被敌军攻入，最後被胡奋所杀。直属士兵数百人皆拒降战死。\n\n史：和夏侯玄、邓颺等人颇为深交。以「四聪八达」自称，以才人自居的态度被曹叡所厌恶，因此未受到重用。\n\n",
