    "biography": "魏国武将。操使大斧的能手。\n\n演：曾经是杨奉的部下，被满宠说服转而为曹操效命。在吕布讨伐战时逮捕陈宫。虽在官渡之战败给颜良、文醜，但因突击乌巢而助其获勝。之後也参战赤壁、渭水、汉中等地，在关羽包围樊城时迎击阻止前进。此後孟达叛乱，响应诸葛亮的北伐，同司马懿前往镇压时，却身中孟达的箭而亡。\n\n史：迎战关羽後，受到见其一丝不乱地率兵的曹操赞为「可与西汉名将·周亚夫並称之风」。\n\n",
    "aptitudes": {
      "spear": 2,
      "halberd": 3,
      "cavalry": 2,
      "archer": 1
    },
    "skill": "长驱直入",
    "trait": "破阵削弱"
