    "biography": "孙权之弟·孙翊之妻。才色兼备並精通占卜。\n\n演：在孙翊打算聚集县府官员开宴时，因卜出大凶之兆而劝告孙翊中止宴会。但是孙翊依然照预定举办酒宴，结果被妫览、戴员、边洪等人暗杀。之後被妫览强迫再婚，一时假装同意顺从，然後和孙翊的心腹孙高和傅婴商量復仇一事。孙翊的丧事结束後，计诱妫览、戴员並使孙高等人将其杀死。因此事而获得江东人民的称赞。後来徐氏在孙权的馆邸度过餘生。\n\n史：妫览和戴员是孙权所杀死的盛宪的部下。\n\n",
