    "biography": "魏国武将。操使大斧的能手。其武艺受到司马师的评價。\n\n演：２５３年，在姜维联结羌族进行北伐时，成为司马昭的先锋击退廖化和张嶷。但却在铁笼山遭遇姜维的伏兵而战死。\n\n史：２４９年，当姜维在进攻麴山时，在陈泰的指挥下同邓艾迎击，並包围蜀国的句安、李歆等人迫使投降。２５４年，在狄道和蜀军交战时杀死张嶷，却因防守狄道的李简向姜维投降，使得被包围在襄武，最後被杀死。\n\n",
