    "skills": [],
    "biography": "刘备的幕僚。司马徽的弟子，是诸葛亮、庞统的学友。\n\n演：被在新野的刘备任用为军师，在初次对阵时击败曹操所派遣的吕旷、吕翔部队。之後来袭的曹仁和李典也因为曹仁所设的「八门金锁阵」被破而撤退。欲得其才的曹操便逮捕徐母以假信骗诱。满是孝心的徐庶未看穿假信，在发誓不为曹操提供任何计谋後離开刘备。在告别之际，推薦诸葛亮为後任。之後徐庶之母因感叹自己误子前途而自杀。\n\n史：原名徐福。在曹丕时代升到御史中丞。\n\n",
