    "type": "halberd",
    "formation": "front",
    "skills": [],
    "biography": "吴国武将。\n\n演：被继承孙策之位的孙权招揽。参与赤壁之战、南郡攻略战、关羽讨伐战、夷陵之战等战役。其中以２１５年进攻合淝时，在魏国大军的包围下，依然奋战突破重围的表现最受注目。在孙权被进攻荆州的刘备的气势压倒、臣服曹丕为吴王时叹道「都是因为我们没有用，才让主公受取别人的爵位」。之後，曹丕侵略南徐时，利用假城墙欺骗魏军将其击退。\n\n史：虽曾和蒋钦、周泰各执己见，但最後和解並共同奋鬥。\n\n",
