    "biography": "魏国官吏。\n\n演：没有记载。\n\n史：在曹操平定河北时被发掘，历任南安、平阳、安平等地的太守，在各地建立了不少政绩。曹叡时代成为凉州刺史，尽力於水田开发、教育、以及西域通行等事务。还曾接受过西方異族的进贡。之後回到中央，历任大司农、司隶校尉、光禄大夫等职，受百官们所敬重。晚年虽被任为司空但却推辞。好酒，曾因违反禁酒令而招曹操所怒，最後靠鲜于辅求情才免於受罚。\n\n",
