    "biography": "吴国武将。\n\n演：左将军。在晋国发起讨吴战时，同张悌、诸葛靓迎击。看到晋国的大军便劝张悌投降，当知道张悌有决一死战的觉悟时便也出阵。战到最後被周旨杀死。\n\n史：丹阳太守时，率领著名为青巾兵的精锐部队。在晋军来袭时，同张悌、诸葛靓、孙震迎击。在版桥包围张乔並降伏後，和张翰、周浚交战。三度展开攻势却未能获勝，撤退之际被薛勝、蒋班、张乔攻击而败北。在被俘掳後被王浑斩首。\n\n",
