    "biography": "魏国武将，申耽之弟。\n\n演：当曹操在汉中被刘备击败，在刘封、孟达、王平进军上庸时向刘备投降。之後跟随因为不输送援军给关羽而立场险恶的孟达再次为魏国效命，和徐晃联手击退刘封。因此功绩成为魏国的金城太守。之後孟达倒戈蜀国时通报司马懿，同申耽将孟达诱出城外。\n\n史：和孟达赶走刘封，再次为魏国效命後，继承申耽的原职成为魏兴太守。之後因和孟达不和，屡次上奏孟达别有贰心。\n\n",
