    "skills": [],
    "biography": "吴国中常侍（宦官）。\n\n演：得到孙皓的宠爱，濮阳兴、张布因劝谏这点而令孙皓不悦，便连诛其三族。在晋军逼近时，提出以铁锁封锁扬子江的策略。但铁锁被晋国的王濬所破，於是晋军就沿扬子江往下进攻。之後，因吴国阵营的人接二连三的投降，便受到上奏吴军之所以衰退原因在於岑昏，於是在孙皓还来不及阻止下便被群臣所杀。\n\n史：巴结孙皓，官升至九卿之位。好兴土木事业，不顾人民劳苦而施加劳役。\n\n",
