    "biography": "甄逸之女，为绝世美人。甄家是汉朝名门。原袁熙之妻，後为曹丕之妻，生下曹叡、东乡公主。\n\n演：曹操压制邺时，同袁绍之妻·刘氏受到曹丕的保护。被曹操赞为「适合成为我兒子的新娘」，便成为曹丕之妻並生下曹叡。之後登上帝位的曹丕因迎娶郭贵妃而失去宠爱。在曹丕生病时，甄氏被郭贵妃的宠臣·张韬告发是诅咒曹丕的兇手，被命令自杀。後来被追封为文昭皇后。\n\n史：据说曹植「洛神赋」裡登场的水神·宓妃就是甄氏，为曹植爱慕甄氏所吟咏的缘故。\n\n",
