    "biography": "魏臣·辛毘之子，辛宪英之弟。为曹爽的参军。\n\n演：司马懿夺取曹爽政权之时，受鲁芝所邀到曹爽麾下。之後得到其姐辛宪英的建言，通知曹爽司马懿举兵的事。在曹爽一派被司马懿处刑後险被蒋济问罪。但被司马懿认为是「有义气之人」而逃过一劫。便为庆幸得到其姐的建言而感叹。\n\n史：成为河内太守。後来为晋国效命，升到卫尉。\n\n",
