    "biography": "魏国武将，申仪之兄。\n\n演：曹操於汉中被刘备击败时，在刘封、孟达、王平进军上庸後投降。之後说服因不派援军给关羽以致自身之立场陷於险恶境地之孟达投降魏国，並放逐刘封。因此功绩成为上庸太守。当孟达与诸葛亮暗中协定投诚於蜀後，通报司马懿要求救援，並同申仪将孟达诱出城外杀害。\n\n史：上庸之豪门贵族。和张鲁联手，後来服侍曹操。在蜀国投降後，以上庸太守的身份成为征北将军。其弟申仪与孟达於一同放逐刘封後投降魏国，移居南阳。\n\n",
