    "biography": "袁绍的幕僚。\n\n演：在袁绍决定和曹操开战後，同逢纪出征黎阳。但却如荀彧所评论的「刚愎自用」，和同僚许攸等人对立，並在官渡之战中败北。袁绍死後，同逢纪共迎袁尚为继承人，和袁谭、郭图对立。之後在曹操北上时，同陈琳死守奋战，並将倒戈曹操的辛毘一族杀尽。但因外甥审荣将城门打开而被徐晃所捕，朝向袁尚所在的北方受斩而死。\n\n史：原本虽和逢纪交恶，在和解之後变得很亲近。\n\n",
