    "biography": "袁绍的幕僚·辛评之弟。後来成为魏臣。辛宪英、辛敞之父。\n\n演：在袁绍死後，袁尚和袁谭对立时，以袁谭的使者向曹操请求援军。由於邺攻略战中家族皆被审配所杀的关係，在曹操杀掉审配後服侍曹操。曹操死後，同华歆、王朗等人逼献帝让位给曹丕。五丈原之战中，察觉到司马懿的想法，於是勒令禁止诸将出兵，得到司马懿的感谢。\n\n史：被审配所杀的是其兄辛评的家族。在五丈原之战以大将军军师的身份参战，即使司马懿希望和诸葛亮决战依然不允许，司马懿也遵从辛毘的指示。\n\n",
