    "skills": [],
    "biography": "袁绍的幕僚，辛毘之兄。\n\n演：韩馥的参谋。在袁绍夺取韩馥手中的冀州後服侍袁绍。当袁绍决定推举么子袁尚为继承人时，同郭图共推长子袁谭，並袁谭在青州整备军队。袁绍死後，同郭图共推举袁谭，和袁尚对立。当受到曹操攻击时，以袁谭的使者身份提出投降的要求但却遭到拒绝，之後被袁谭懷疑为内奸悲愤而死。\n\n史：在袁谭和袁尚决裂後曾被袁尚逮捕。曹操军包围邺时，为了警示追随曹操军的辛毘，於是其家族皆被审配赶尽杀绝。\n\n",
