    "biography": "蜀国的幕僚。\n\n演：服侍刘璋。在刘备的使者·简雍劝告刘璋投降时斥责他无礼的态度。在刘璋投降後为刘备效命，並同诸葛亮等人为刘备即帝位而努力。当刘备打算为关羽復仇出阵时，抱著被斩首的决心向刘备劝谏，而被打下大牢。在刘禅时代，和吴国使者·张温应对，回答出张温所提出的难题，反将张温辩的无话可说。\n\n史：在刘备平定益州後被广汉太守·夏侯篡招揽，开始当官。最後升为大司农。\n\n",
