    "biography": "魏国武将，幼名阿苏。吕布的武将·秦宜禄之子。母亲杜氏为曹操的侧室。其母杜氏也曾为关羽所望成为自己之妻。\n\n演：以前将军的身份参加五丈原之战。假装向蜀军投降和郑文合作进行夜袭。但却被诸葛亮看穿策略而被杀。\n\n史：受到曹操的宠爱，年轻时曾遊走各个诸侯之间，但是却没有被曹操或曹丕责备过。在曹叡时代成为骁骑将军，前往并州镇压反叛的鲜卑的步度根。並没有和诸葛亮的蜀军在五丈原战鬥的记载。\n\n",
