    "biography": "河内太守·张杨的武将。原本是黑山山贼。\n\n演：为救援被曹操军包围在下邳的吕布而出阵的张杨被部下杨醜杀死後，杀了杨醜。之後进入犬城，被曹操军的史涣追讨。\n\n史：１９１年，和同是黑山贼的于毒、白绕等人攻陷魏郡，但在翌年败给了曹操撤退。在１９９年杀掉杨醜後，率领原张杨军联合袁绍驻紮在射犬。虽被巫女劝道「字中有兔，待在以犬为名的土地是为不吉」，但並未接受。之後於犬城和史涣、曹仁、于禁、徐晃等人交战，败战而死。\n\n",
