    "biography": "董卓的武将·张济之妻，张绣的叔母。\n\n演：其夫张济在进攻南阳时死去，之後便投靠外甥·张绣。１９７年，张绣向曹操投降时，进驻南阳的曹操对邹氏一见锺情。之後，曹操就经常进出逗留邹氏所居之处，盛怒的张绣便因此攻击曹操。为了保护曹操的典韦和曹昂便在此丧命。\n\n史：在张绣投降时成为曹操的侧室。当曹操聽到张绣因此事感到不快时，就秘密策劃杀掉张绣的计劃。但计劃却在事前败露，被张绣突袭的曹操遭到惨败。\n\n",
