    "biography": "东汉武将。\n\n演：在黄巾之乱时，向幽州太守·刘焉提议募集义勇军讨伐黄巾黨被採用。之後，率领募集而来的刘备、关羽、张飞等人击破青州的黄巾黨。当刘备等人前往援护卢植时，採取别的行动。\n\n史：在黄巾之乱时，只有带领刘备等人参加黄巾黨讨伐战的记录。在正史中，刘焉並未赴任幽州，也没有邹靖为刘焉效命的记载。\n\n",
