    "biography": "韩遂的武将。\n\n演：呼应马超和韩遂为曹操所杀的马腾復仇战，攻陷长安。在渭水之战，夜袭渭水北岸的曹操阵营之计被识破，遭到夏侯渊砍杀。\n\n史：东汉末期，以长安以西（关中）一带为势力範围的军阀之一。２１１年，看出曹操西征的动向，和马超与韩遂共同举兵。却因中了贾诩的離间计和马超与韩遂对立。此间隙为曹操军所攻，同李堪战败身亡。\n\n",
