    "biography": "魏国、晋国武将。\n\n演：诸葛诞叛乱时，参加司马昭指挥的反叛镇压军。聽从锺会的计策，以伏兵大破前来援救诸葛诞的吴国军队。司马炎成为晋王後，被认命为骠骑将军。\n\n史：和同是农民出身的邓艾都是郭玄信的马伕，两个人皆被评为是可任大臣出人头地的人才。当时和管辂相遇，曾请教有关於阴阳术的说明。在长安卖铁时被司马懿发掘，历任青州刺史和镇东将军。\n\n",
