    "biography": "吴国官吏·薛综之子，薛珝之弟。\n\n演：光禄勋。当晋国大军逼近建业，建议吴帝孙皓仿效蜀国的刘禅向晋军投降。\n\n史：在孙休时代当上散骑中常侍，一时曾因病辞职。在孙皓时代再次被任用，同韦昭、华覈等人共编撰「吴书」。陆凯临终之前送给孙皓的书信中写著，薛莹和楼玄、贺邵、张悌、滕脩、陆抗等人同是担任吴国基幹的大臣。在吴国向晋国投降时起草投降书。为晋国效命，升至散骑常侍。\n\n",
