    "biography": "吴国重镇·全琮之孙。演义中虽是全端之子，但正史中是全绪之子。全仪之兄。全怿的外甥。别名全辉。\n\n演：２５７年，诸葛诞在魏国掀起叛乱时，奉孙綝的命令前去助阵诸葛诞。被魏国大军包围，向司马昭投降後，也劝告寿春城内的父亲全端、叔父全怿一起投降。在出征时，受到孙綝「要是输给魏军，你们父子就没命了」的威胁所言。\n\n史：因为家族内部掀起纷争，和其弟全仪偕同母亲亡命到魏国。之後，遵从锺会的计策，转告全端和全怿家人在吴国遭到迫害，使其投降。\n\n",
