    "biography": "吴国重镇·全琮之子。全端之弟。全禕的叔父。\n\n演：２５７年，魏国诸葛诞在寿春反叛时，奉孙綝之命前往救援，同其兄全端进入寿春城。但却被先向司马昭投降的全禕所劝，而向魏国投降。\n\n史：收到外甥全禕所送来的，如果在寿春没有战果，全家一族将被吴国所灭杀的书信，便同其兄全端投降。其实此为锺会的策略，而全禕等人实因一族内部纷争才亡命天涯。降於魏国後成为平东将军。\n\n",
