    "biography": "吴国黄门侍郎。全尚之子。母亲是孙綝的堂姐。\n\n演：２５８年，收到吴帝·孙亮传来的讨伐实行暴政的孙綝的密令。但由於父亲全尚将计劃洩漏给妻子（全纪之母），进而让孙綝知道，以致於全家满门抄斩。也因此事件，孙亮被废帝位。\n\n史：在孙亮和全纪商谈时，曾劝告全纪，其母为孙綝一族的人，所以要多加注意。但不仅如此，最後，对父亲全尚将此告诉母亲一事感到羞耻，在孙亮被孙綝废位的同时自杀。\n\n",
