    "biography": "演义中虽为曹丕之子，但正史中是曹操之子，母亲是环氏。其妻是张鲁之女。其子曹奂（曹璜）为魏国最後一位皇帝。燕王。\n\n演：受到卧病在床的曹叡所託，辅佐成为大将军，並将继承帝位的曹芳，但却断然拒绝。\n\n史：年轻时曾和曹叡共同起居生活缘故，所以备受宠爱。在曹叡即位後也受到了特别的待遇。曹叡临终之前受託担任曹芳的辅佐者，但诏令却遭政敌刘放和孙资改写，同曹肇、夏侯献、秦朗一起被罢免。\n\n",
