    "skills": [],
    "biography": "曹操之孙，曹丕和甄氏之子。魏国的第二代皇帝·明帝。\n\n演：因生母甄氏被曹丕命其自杀，於是由郭皇后所扶养，受封为平原王。曹丕死後即帝位。蜀国诸葛亮开始北伐时，派遣夏侯楙、曹真、司马懿迎击，成功阻止攻击。在诸葛亮进军五丈原时，亲自前往对吴战线，阻止陆逊的侵略。诸葛亮死後无视重臣们的劝谏拼命营造宫殿。重用司马懿，在公孙渊叛乱时任命讨伐一职，且病在危笃之际曾託付辅佐次帝·曹芳。\n\n史：受曹操疼爱，被曹操认同为继承自己的帝业者。\n\n",
