    "biography": "魏国燕王·曹宇之子。演义中是曹丕之孙，但正史中却是曹操之孙。常道乡公。魏国的第五代皇帝·元帝。原名为曹璜。\n\n演：２６０年，当第四代皇帝·曹髦被杀时，被司马昭迎上帝位，並改名为曹奂。２６５年，受司马昭之子·司马炎所迫让位。虽曾受动之以情而不接受，最後在贾充、裴秀的劝说之下决定禅让。魏国就如此灭亡，而曹奂自己则成为陈留王。\n\n史：禅让後，移住邺城。\n\n",
