    "biography": "魏国重臣·曹真之子。曹爽之弟，曹训、曹彦之兄。\n\n演：在曹方时代，其兄曹爽为大将军掌握政权时，任中领军统率近卫部队。曾对经常出外围猎的曹爽，说明无人留守时情势变化所发生的危险性，但曹爽却不聽劝。２４９年，在曹爽出外打猎时，被司马懿夺取政权。虽劝其兄投降，但最後一连三族皆被司马懿所监禁，並遭处刑。\n\n史：在司马懿夺取政权後，虽受桓範建议拥立曹芳反讨司马懿，但仍迟迟无法下决心和曹爽一起举兵。\n\n",
