    "biography": "曹操的外甥。\n\n演：在铜雀台落成式中展现高超的弓技，而濡须口之战时射中凌统的马。曹操死後，同曹洪潜入宫中逼迫献帝让位给曹丕。之後负责指挥对吴战线，在曹丕临终时受託辅佐曹叡。２２８年，不疑吴国周鲂的诈降，不顾贾逵等人的制止出征石亭。结果惨败给陆逊，不久之後病死。\n\n史：在曹操举兵攻打董卓时从军。受到曹操疼爱，同曹丕一样的方式养育长大。在与刘备的汉中争夺战中，和张既共任曹洪的辅佐。\n\n",
