    "biography": "魏国重臣·曹真之子。曹爽、曹羲之弟，曹彦之兄。\n\n演：曹芳时代，其兄曹爽为大将军掌握政权後，任武卫将军统率近卫部队。２４９年，跟随曹芳，同曹爽等人前去围猎之际，被司马懿夺走政权。虽受桓範建议拥立曹芳並讨伐司马懿，却无法实行，叹到「曹真曾对自己的智谋自傲，怎麼兄弟个个都像头猪猡呢？」。结果曹爽一派被司马懿所抓，全部都被杀光。\n\n史：在掌握政权後，虽受到曹羲劝谏其过於放荡，但其实是暗警曹爽。\n\n",
