    "biography": "吕布的武将。\n\n演：参加与曹操争夺兖州之战，在定陶山败北後进入徐州。同魏续购买军马的途中受到张飞的袭击，之後跟随盛怒的吕布将刘备军赶出徐州。被曹操和刘备包围在下邳，当同僚的侯成受到吕布棒刑後，便同侯成、魏续共逮吕布降於曹操军。之後，白马之战时和袁绍军交战中挑战颜良，三招就被砍死。\n\n史：和侯成、魏续等人合作逮捕陈宫。並未有之後成为曹操部下的记载。\n\n",
