    "biography": "孙权的武将。操使方天画戟。\n\n演：赤壁之战後，孙权进攻合淝时，迎击向孙权挑釁的乐进，却被李典的箭所射穿战死。\n\n史：服侍孙权参加江东侵略战。在孙策和太史慈交战时，同韩当、黄盖共担孙策的护卫。演义中是战死於赤壁之後的合淝之战，但正史中却未有死於合淝之战的记载。２２２年参加夷陵之战，在陆逊的指挥下和朱然、潘璋、韩当、徐盛、鲜于丹、孙桓等人共同击败蜀军。\n\n",
