    "biography": "曹操之长子。因生母刘氏早逝，由丁氏抚养成人。\n\n演：在宛的张绣有进攻许昌之举时，随曹操前往共伐並降伏了张绣。但在驻留宛城时受到张绣的夜袭，将自己的坐骑让给失去自己马匹的曹操，而战死在乱战之中。\n\n史：曹昂战死之後，丁氏责难曹操「杀死了我的兒子，竟还能这麼心平气和」，便下堂求去並回乡。\n\n",
