    "biography": "曹操的堂弟。\n\n演：曹操在陈留举兵时从军，並参加董卓讨伐战。当曹操在荥阳惨败给徐荣时，捨命救出曹操。之後也跟随曹操转战各地，杀死黄巾残黨何曼和袁谭。渭水之战中被马超夺去潼关，而险遭曹操斩首，但是当曹操被马超追杀时挺身相救，反而受到曹操的感谢。此後就驻紮汉中，多次和刘备军展开激战。\n\n史：因为拒绝借钱给曹丕而两人不合，在曹丕即位後被免职。曹叡时代復职成为骠骑将军。\n\n",
