    "biography": "曹操的武将，曹仁之弟。\n\n演：赤壁之战後，同曹仁共防南郡。虽曾数次击退周瑜的攻势，却被周瑜的假丧礼所骗，受诱而出时遭到攻击。此时，南郡就被刘备军的赵雲给夺走。\n\n史：率领名为「虎豹骑」的精锐骑兵，在南皮包围战时杀死袁谭，白狼山之战时逮捕了乌丸的蹋顿。在长阪之战时追赶刘备军，並接收了物资跟残兵。赤壁之战後随曹操返回谯，不久後死去。好学，並敬爱学者。\n\n",
