    "skills": [],
    "biography": "曹操的三子。母亲是卞氏。曹丕之弟，曹植、曹熊之兄。武艺優秀可赤手空拳打倒猛兽。因鬍鬚是黄色，故被曹操称为「黄鬚兒」。任城王。\n\n演：平定在代郡反叛的乌丸後，参加和刘备军的汉中攻防战。虽杀死了刘备军的吴兰，而战况毫无改变，结果曹操军便从汉中撤退。曹操死後虽率大军前往京城，但被贾逵所说服，交还兵权之後回到领地。\n\n史：虽被曹操强迫唸书，但自己却是希望如西汉名将的卫青和霍去病一般，以武将功绩扬名立万。\n\n",
