    "biography": "曹操之族子。曹邵（原名秦伯南）之子。\n\n演：曹丕讨伐吴国时，同夏侯尚进攻南郡。曹丕临终之际，和陈群、司马懿受託於後事。蜀国诸葛亮开始北伐，夏侯楙迎击失败後，成为大都督担任防卫。虽抗阻了蜀军侵略长安，但才能不及诸葛亮和司马懿，导致心劳而病，最後因看了诸葛亮的书信气愤填腔而死。\n\n史：因曹邵代曹操而死的缘故，曹真就被曹操所领养，和曹丕如兄弟般地被扶养成长。在与蜀国交战後病死，对於诸葛亮的书信並无相关的记载。\n\n",
