    "biography": "曹操的堂弟。\n\n演：追随在陈留举兵的曹操，之後以曹操军的主力身份转战各地。同李典攻打新野的刘备军时摆出「八门金锁阵」应战，但败给徐庶，反而被夺走樊城。赤壁之战後，担任南郡的守备。之後虽使进攻而来的周瑜负伤而退，但仍因诸葛亮的计谋使城被夺而撤退。之後，关羽进攻襄阳时，同满宠死守樊城抗战。徐晃前来救援，直到关羽撤退之前成功守住樊城。\n\n史：因用法的手腕获得曹丕的信赖，升到大司马。\n\n",
