    "biography": "吕布的武将。\n\n演：参加和曹操军争夺兖州之战，因调集兵粮中吕布败北，而和吕布逃往徐州。在曹操军进攻徐州时迎击，虽射中夏侯惇的左眼，却被继续奋战的夏侯惇所杀。\n\n史：服侍吕布的郝萌的部下。在郝萌串通袁术背叛吕布时，与郝萌交战，虽然负伤依然砍断郝萌的一隻手臂。当郝萌被高顺杀死後，郝萌的部队便交任给曹性统率。夏侯惇在和吕布军交战时的确失去了左眼，但是並未有曹性所射中的记载。\n\n",
