    "biography": "宦官·曹腾之孙，曹嵩之子。魏国的武王。幼名为阿瞒。\n\n演：被许劭评为「治世之能臣，乱世之奸雄」。在讨伐黄巾黨时十分活跃，当董卓掌握实权时，呼籲各地诸侯举兵响应打倒董卓。之後，平定兖州並增青州兵，将献帝迎至许昌而掌握政权。击败吕布、袁术等人，在官渡之战时击破袁绍並支配河北。接著虽攻下刘琮逼近江东，却在赤壁之战败给了孙权和刘备的联军，失去了统一全土的機会。之後致力於平定关中以西之地。２１３年为魏公，２１６年为魏王。\n\n史：政战两方都非常優秀，並且是精通诗歌文学的万能英雄。\n\n",
