    "biography": "魏国重镇·曹真之子。曹羲、曹训、曹彦之兄。\n\n演：受到曹叡所託，同司马懿共辅次帝·曹芳。曹叡死後，接受心腹何晏的进言，从司马懿手中夺取实权佔为私有。但却被司马懿假扮老衰所骗，安心且频繁地举办围猎活动。２４９年，同曹方外出打猎之际，被司马懿夺去兵权。虽被其智囊桓範建议拥立曹芳讨伐司马懿，却没有魄力执行。於是被感叹而到道「简直是个猪猡」。结果曹爽一派被捕，一连三族皆被处刑。\n\n史：２４４年，和夏侯玄进攻蜀国，未得任何战果而退。\n\n",
