    "biography": "吕布的武将。後来服侍曹操。\n\n演：为了争夺兖州和曹操军交战，因调度兵粮时吕布败给曹操的缘故，和吕布逃往徐州。袁术进攻徐州时，同张辽击败雷薄。在曹操军侵略徐州时，和尹礼、吴敦、孙观等人共率泰山的山贼迎击。吕布战败身亡後归顺曹操。在赤壁之战中同徐庶共制西凉的马腾、韩遂。\n\n史：在黄巾之乱中，跟随陶谦镇压叛乱。归顺曹操之後统括青州、徐州的军事，並且牵制袁绍和孙权。曹丕时代击败吴国的吕範，升至执金吾。\n\n",
