    "biography": "曹操的次子。母亲为卞氏，是曹彰、曹植、曹熊的亲兄长。和甄氏所生下的孩子为曹叡。魏国的初代皇帝·文帝。\n\n演：攻下袁家居城的邺之後迎娶袁熙之妻·甄氏。和曹植竞争继承者之位，因重视长幼有序的贾诩等人的意见就任皇太子。曹操死後成为魏王，在接受献帝的禅让後成为魏国的初代皇帝。之後，虽屡次进攻蜀国及吴国却毫无战果。在位七年，拜託曹真、陈群、司马懿辅佐次帝·曹叡後就病逝。\n\n史：曹丕执政时制定九品中正，奠定後来贵族制度的基础。同曹操、曹植並称为建安文学的代表人物。\n\n",
