    "biography": "陶谦的武将。\n\n演：曹操攻击陶谦时，出迎曹操军先锋的夏侯惇。在陶谦死後服侍刘备。此外，其女成为吕布之妻。在刘备进攻袁绍时，同张飞奉命共备下邳，却因拒绝张飞强迫劝酒，而遭到了鞭打之刑。当晚便迎接吕布企图杀死张飞，却反而被张飞所杀。\n\n史：並未有和吕布之间婚姻关係的记载。\n\n",
