    "biography": "魏国明帝·曹叡的养子。虽然传说是任城王·曹楷之子，但身世依然是个谜。齐王。魏国第三代皇帝。张皇后是张缉之女。\n\n演：曹叡死後以仅８岁之龄即位。最初虽由曹爽掌握政权，２４９年司马懿打倒曹爽後，政权遂由司马一族所掌握。２５４年，因憎恨蔑视自己的司马师，於是给予夏侯玄、李豐、张缉等人打倒司马一族的密令，不料却事迹败露而被降格为齐王，夏侯玄等人和张缉之女的张皇后则被杀。\n\n史：退位後離开都城之际，受到司马孚等数十位群臣流泪送别。\n\n",
