    "biography": "魏文帝·曹丕之孙，曹霖之子。高贵乡公，第四代皇帝。\n\n演：第三代皇帝·曹芳被司马师所废之後，以新帝的身份即位。司马师死後任命司马昭为大将军。当诸葛诞举兵企图打倒司马家时，被司马昭强迫亲征。２６０年，和王经、王沈、王业等人图谋共讨司马昭，却因王沈和王业向司马昭密告而事情败露。虽然亲自率领亲卫队讨伐司马昭，但被司马昭的心腹贾充等人包围，被成济所杀。\n\n史：年轻时好学，以英才闻名。受到锺会评为才能足以和曹植、而武艺足以和曹操匹敌。\n\n",
