    "biography": "曹操的五子。母亲为卞氏。是曹丕、曹彰、曹植之弟。\n\n演：天生體弱多病，曹操死後亦未能参加丧礼而关在领地裡。当曹丕派遣使者前来责问时，因怕被兴师问罪而自杀。\n\n史：只有早死的记载，並有未被曹丕责问而自杀的记录。\n\n",
