    "biography": "刘表的部下·黄祖的武将。江夏都督。\n\n演：向黄祖进言提拔同僚甘寧时，因甘寧是江贼出身而遭到反对。在甘寧见黄祖如此而决定投效孙权之际，便助其脱離。之後，成为孙权军一员的甘寧在杀了黄祖时逮捕了苏飞。虽险被孙权斩首，但在甘寧的求情下而得救。\n\n史：在孙权击败黄祖时準备了两副棺材，原打算将黄祖和苏飞两人放进去。\n\n",
