    "biography": "孙权的三子。孙登之弟，孙霸、休、亮之兄，孙皓之父。\n\n演：受到关係交恶的全公主（孙鲁班）向孙权散播恶评，因而被孙权疏远，最後含恨而死。\n\n史：年幼时期受孙权宠爱，接受阚泽的教育。２４２年孙登死後成为皇太子。但因受到和其母王氏对立的全公主搬弄是非，而遭到孙权的疏远。之後更因孙权之弟·孙霸受宠而引发了继承者之争。拥护孙和的陆逊、吾粲、顾谭、朱据遭到处罚，孙和遭到废嫡，孙霸也被命自杀。之後因被流言受诸葛恪所拥，而被与全公主串通的孙峻命令自杀。\n\n",
