    "biography": "孙河（俞河。因深得孙策欢心，而得孙姓）的三男。\n\n演：在刘备为关羽復仇进攻荆州时，同朱然迎击。在战争序盘，部下李異、谢旌、谭雄被蜀国的张苞、关兴所杀，退到夷陵城後遭蜀军包围。之後受到成为迎击指挥官的陆逊所信任说「孙桓深得部下信赖，所以能够坚持到底」，而正如所言孙桓最後撑过了这一役。在蜀军因为陆逊的火计而大败时，击败了蜀将张南、冯习等人。\n\n史：从一开始就同陆逊迎击刘备，並没有在战争序盘中战败的记载。之後，於建设横江的要塞时猝死。\n\n",
