    "biography": "和吕布联手的泰山山贼。之後服侍曹操。孙毓之父。\n\n演：在曹操攻吕布之际，和吕布军的陈宫、臧霸联结。和山贼同夥的吴敦、尹礼等人共守萧关，但却被曹操军击破。当吕布在下邳战败身亡後被臧霸说服，同吴敦和尹礼等服侍曹操。\n\n史：和臧霸共同起兵参加黄巾黨讨伐战。在服侍曹操後同臧霸出战，常任先锋，並将青、徐州的盗贼平定。成为偏将军、青州刺史。之後跟随曹操和孙权交战，虽遭流箭所伤依然持续奋战。其勇虽受到曹操称赞，但终因箭伤而死。\n\n",
