    "biography": "孙权的六子。孙登、孙和、孙霸之弟，孙亮之兄。吴国的第三代皇帝·景帝。孙[0xFA][0x44]之父。\n\n演：２５８年，受到废除孙亮的孙綝所迎，登上帝位。之後就使丁奉等人杀掉企图反叛的孙綝。当蜀国诸葛瞻受到魏国攻击而要求援军时，虽派遣丁奉等人前往却未能赶上。蜀国灭亡，魏国也被司马炎所灭时，因为心痛发病，指名孙[0xFA][0x44]为继承者後死去。但由於万彧、张布的策劃，由孙皓成为次帝。\n\n史：虽振兴教育和农业，並减轻租税。於晚年时将政治交给濮阳兴、张布，自己则埋头研究古典。\n\n",
