    "skills": [],
    "biography": "孙和之子，孙权之孙。吴国第四代皇帝。幼名为彭祖。\n\n演：２６４年，第三代皇帝·孙休死後，受万彧、张布推举即帝位。重用宦官岑昏，逐渐步向暴政。接连更改年号，並胡乱不断的大兴土木，使得人民、士兵怨声载道。且将劝谏这点的濮阳兴、张布、万彧、留平、楼玄等重臣相继处刑。企图进攻晋国，並将反对的陆抗降职。２７９年，晋国发起吴国讨伐军，翌年，被攻至建业时投降。吴国灭亡，三国时代就此闭幕。\n\n史：即位初期广施仁政，被称为名君。\n\n",
