    "biography": "孙静之三男。孙瑜之弟。孙权之堂弟。\n\n演：於孙权攻打关羽之时，与吕蒙奉命共同指挥讨伐关羽。但吕蒙以指挥官若为两人将混淆指挥系统为由拒绝，故受派至後方担任补给工作。\n\n史：於曹操军侵略濡须时迎击曹操军並予以抵挡，被评为精锐。於程普、黄盖、孙瑜等人死後，成为继任接掌军队。与演义相異，於关羽讨伐战中与吕蒙一同出征，对荆州平定颇具贡献。曾因细故与甘寧口角，而由孙权出面仲裁。\n\n",
