    "biography": "孙坚之长男。孙权之兄。其妻为大乔。吴之长沙桓王。\n\n演：与其父一同与刘表军对战，於其父殁後将玉玺过让於袁术以换取兵力。並讨伐侵略江东之刘繇、严白虎、王朗等人，人称「江东小霸王（霸王指项羽）」。尔後自袁术阵营独立，建立起足以与曹操匹敌之势力。却因杀与曹操勾结之许共，遭许贡之食客袭击，负伤。将後事託付於其弟之孙权、及义兄弟之周瑜後辞世。\n\n史：於袁术之庇护讨伐「吴之四姓」之陆康，与江东之名士阶层对立。虽於最後孙权与陆逊（与陆康同族）和解，尔後於吴国皇帝及臣子之对立，仍旧频频发生。\n\n",
