    "biography": "孙策之女。陆逊之妻。\n\n演：並无记载。\n\n史：於陆逊服侍孙权後，奉孙权之命成为陆逊之妻。於孙策进军江东时，因讨伐「吴之四姓」其中一人·陆家之陆康之故，致使孙策与陆逊一族处於敌对关係。陆逊仕官於孙权，並迎娶孙氏为妻等事成为两家和解之象徵。但其後孙权与吴国之重臣们依然持续著对立，陆逊亦因遭捲入孙权之继位者问题，悲愤而死。\n\n",
