    "biography": "吴国武将。孙权之弟·孙匡之孙。孙泰之子。\n\n演：以晋国之骠骑将军身份登场。於孙皓向晋国投降时，感叹「昔讨逆壮年，以一校尉创立基业，今孙皓举江南而弃之，悠悠苍天，此何人哉！」。\n\n史：於孙皓时代成为前将军、夏口都督。於吴国之皇族中極有可能继承帝位，且掌握绝大的兵权，故为孙皓所防範。２７０年，有感自身性命危险，故带其妻及自小养育成人之士兵亡命晋国，成为骠骑将军。因倍受礼遇，尔後吴国将领即陆续亡命至晋。於吴国灭亡後，虽降格为伏波将军，其後仍受重用。\n\n",
