    "biography": "孙坚之弟·孙静之曾孙。孙恭之子。孙綝之堂兄。\n\n演：获孙权赏识肩负统率近卫，却遭诸葛恪夺走职权。２５３年，斩杀与滕胤共谋之诸葛恪，成为丞相、大将军玩弄政权。尔後病死，由堂弟之孙綝接掌其位。但因孙綝亦施行暴政之故，故遭孙休所讨伐。於同时，孙峻之墓亦遭破壞。\n\n史：孙权临终之时，推举诸葛恪为次帝·孙亮之辅佐。暗杀诸葛恪後，逼迫与当时有私通之全公主（孙鲁班）对立的孙和自杀。虽险遭孙英、孙仪等人所杀，但幸得以阻止，並使朱公主（孙鲁育）受连座处分。\n\n",
