    "biography": "吴国武将。孙河（俞河。自孙策处得孙姓）之外甥。\n\n演：孙权从自俞家领养之子。２２４年，於曹丕侵略吴国时，跟随徐盛迎击。因不服命令险遭徐盛处刑，藉孙权之调停免於一死。於徐盛之交战中，单独突击魏军致使曹丕之水军瓦解，立下仅次於徐盛之功绩。\n\n史：１７岁时接掌孙河之兵力镇守京城。於孙权登上帝位後，成为镇北将军与魏国对峙，守卫国境数十载。善用斥候侦察敌情及动静，近乎百战皆捷，尔後成为幽州牧。\n\n",
