    "biography": "孙坚之女。其母为吴国太。为孙策、孙权、孙翊、孙匡之同父異母之妹。孙朗之亲妹。因拥有武功優異人称「弓腰姬」\n\n演：２０９年，为拉拢刘备加入吴国阵营，奉命与刘备成亲。但孙尚香本人及其母吴国太皆喜爱刘备，故於其归返荆州时追随之，並击退欲擒拿刘备之吴国将领。２１２年，自孙权处得吴国太病危之伪报，即欲带刘禅返吴，但刘禅为赵雲及张飞带回。得知刘备於夷陵战亡後，投长江自杀。\n\n史：並无归返吴国後之记载。\n\n",
