    "biography": "吴国武将。孙贲之孙。孙邻之子。孙述之弟。孙歆之兄。\n\n演：並无记载。\n\n史：没有缺点的一位都督。於晋国发动吴国讨伐战时，与张悌、沈莹、诸葛靓共同迎击，尔後於版桥包围张乔迫其投降。因於与张翰、周浚交战时，沈莹之部队受薛勝、蒋班、张乔之攻击而遭歼灭，以致兵败如山倒。遭逮捕後为王浑所杀。\n\n",
