    "biography": "孙坚之么弟。孙策、孙权之叔父。孙瑜、孙皎之父。\n\n演：董卓讨伐战後，劝谏孙坚攻打敌对之刘表，但未受採纳。於孙坚殁後，与孙策共同进军江东，並追击王朗防守会稽郡。於孙权斩杀黄祖时防守吴郡。尔後其曾孙之孙峻、孙綝一手掌控吴国政权。\n\n史：因於讨伐王朗有功，孙策欲授其与重要地位，辞退並返乡吴郡富春县任守备一职。虽於孙权时代任昭义中郎将，但尔後辞官，於家中辞世。\n\n",
