    "biography": "黄巾之武将。\n\n演：於张角病故後，与赵弘、韩忠共同於宛城进行笼城持续抵抗。於朱[0xFA][0x45]与刘备率领讨伐军来袭时虽试图突破包围脱逃，却身中刘备所射之箭战亡。\n\n史：於南阳黄巾黨之张曼成、赵弘、韩忠遭朱[0xFA][0x45]等人讨伐後，孙夏成为总帅继续抵抗。但孙夏亦遭朱[0xFA][0x45]所斩，南阳黄巾黨解散。一般认为於演义中之孙仲之原型即为此孙夏。\n\n",
