    "biography": "孙坚之弟孙静之曾孙。孙绰之子。丞相孙峻之堂弟。\n\n演：於孙峻主亡後，依然掌握政权为所欲为，杀滕胤、吕据、王惇等人並施行暴政。於魏国之诸葛诞发起反叛时，派朱異、全端、唐咨等人为援军出动但无成果，故处刑朱異，並将投降之全端、唐咨等家族全员抄斩。险遭暴虐之第二代皇帝·孙亮斩杀，为防範於未然废立孙亮。拥立孙休为新帝，自身则成为丞相、荆州牧。却遭奉孙休命令之丁奉、张布逮捕，遭受处刑。\n\n史：於废立孙亮时，亦将共谋者之全公主处以流放之刑。\n\n",
