    "biography": "孙权之长男。孙和、孙霸、孙休、孙亮之兄。\n\n演：其母为徐氏。２２９年，於孙权成为吴国皇帝後受立为皇太子。２４１年，因早其父先亡之故，故其弟之孙和受立为皇太子。\n\n史：因生母身份低微，故由徐氏代为养育。於孙权成为吴王後受立为太子，诸葛恪、张休、顾谭、陈表等人为其学友，故此东宫（太子之宫殿）有人才济济之好评。与受孙权疼爱之孙和深交，於临终之际遗言盼立孙和成为皇太子。个性温厚深谋远虑，施行以民为主之政治。\n\n",
