    "biography": "孙坚之弟孙静的次男。孙权的堂哥。孙皎的哥哥。\n\n演：於周瑜以蜀国压制为名，袭击荆州却惨败於诸葛亮时，做为援军赶往救援。\n\n史：孙翊死後，成为丹阳太守人望高昇。２０６年与周瑜一同攻下山越族之麻与保之砦。於曹操进军濡须之时，劝谏孙权积極攻击。於孙权因不採纳意见导致失败後成为奋威将军，对九江、庐江之势力扩大颇具贡献。孙瑜不同於将领，不仅专注军务，且爱好古典文学，於远征途中亦手不释卷。礼遇学者马普，使部下向学。\n\n",
