    "biography": "孙坚之三男。其母为正室之吴氏。孙策、孙权之亲弟。孙匡之亲兄。孙朗、孙尚香之同父異母之兄。其妻为徐氏。\n\n演：任丹阳太守，但因脾气暴躁，常於酗酒後鞭打士兵。无视其妻徐氏之占卜显示大凶一事，仍邀请县府官员举宴，而遭妫览、戴员、边洪暗杀。尔後徐氏决意復仇，与孙翊之心腹孙高、傅婴共同讨伐妫览等人。\n\n史：勇猛果敢，与其兄孙策相似。孙策临终之时，张昭等人建议孙策将兵权委任孙翊。易流於感情用事，曾受朱治劝谏。\n\n",
