    "biography": "孙权之七男。其母为潘氏。孙登、孙和、孙霸、孙休之弟。吴国第二代皇帝。其妻为全氏（全尚之女）。\n\n演：於孙和遭废立之後成为皇太子。２５２年，孙权殁後以１０岁稚龄成为第二代皇帝。聪明才智广为人知，但政权掌握於诸葛恪、孙峻、孙綝等人之手。２５８年，因憎恨孙綝施行暴政，与全纪、刘丞等计劃讨伐孙綝，却遭全纪之父·全尚之妻（孙綝之表姊）洩漏计劃而事迹败露。遭贬为会稽王。\n\n史：２６０年，因遭谣传孙亮意图復位，故遭贬为侯官侯。於前往任地途中自尽。亦有遭毒杀一说。\n\n",
