    "biography": "魏国武将。\n\n演：因斩杀袭击曹叡之虎，获曹叡信任。於诸葛亮开始北伐，蜀军逼近街亭之时与辛毘共同援护曹真。尔後即追随曹真，多次与诸葛亮之北伐军对战。於曹真殁後，遵从司马懿之指挥与郭淮並肩作战。\n\n史：受平定幽州之曹操拔擢，历任山阳、平原、平昌、琅邪太守。於曹休进攻吴国之时劝谏不宜深入敌阵，並反对曹叡营造宫殿。於曹叡殁後与曹爽对立，受命成为扬州刺史发配前线，击退吴国之全琮。於曹爽殁後归返中央，成为司空。\n\n",
