    "biography": "孙坚之庶子。其母为续弦之吴氏（吴国太）。孙策、孙权、孙翊、孙匡之同父異母之弟。孙尚香之亲兄。\n\n演：孙坚殁後，与一族人共同移往曲阿。制霸江东之孙策於临终之际，嘱咐遗训兄弟同心协力辅佐孙权。\n\n史：演义中，虽记载吴国太之子为孙朗及孙仁，但孙仁实为孙朗之别名。於洞口之战，吕範与曹休交战时，孙朗违反吕範命令而用火，烧毁军用资材大为失策。致使为之盛怒之孙权将孙朗之姓由孙改为丁，並处以终身监禁。\n\n",
