    "biography": "孙权之长女。其亲为步氏。孙鲁育（朱公主）之亲姐。嫁予全琮，人称全公主。\n\n演：介入孙权之继位者纷争，对孙权谗言孙和之恶评，致使孙权疏远孙和。\n\n史：嫁予周瑜之长子周循，於周循早逝後嫁予全琮。於孙和与孙霸争夺继位者之时与孙和之母·王氏对立，故对孙权谗言孙和之恶评致使孙和失势。孙权殁後，唆使狼狈为奸之孙峻胁迫孙和自尽。与孙亮深交，尔後参与孙亮之孙綝讨伐计劃，但事迹败漏，遭流放至予章郡。\n\n",
