    "biography": "乔氏。孙策之妻。周瑜之妻·小乔之姐。\n\n演：乔国老之女。与嫁於周瑜之其妹小乔人称「二乔」之绝世美女。於孙策临终之际，向其妹之夫周瑜託嘱代为处理後事之遗言。铜雀台落成後曹操梦想迎娶二乔为其侧室，而将其心境交付曹植以「铜雀台赋」咏唱。自诸葛亮得此事之周瑜激怒，故毅然地与曹操军开战。\n\n史：为桥公之女，理应称桥氏。因於戏曲中桥公受混淆为乔玄（东汉太尉·桥玄），其二女则人称大乔、小乔。\n\n",
