    "biography": "於服侍孔融、刘繇後为孙策效命。太史享之父。\n\n演：为报其母恩，援助遭黄巾残黨包围之孔融，自刘备处求得援军。尔後服侍刘繇，与进军江东之孙策展开激烈战鬥。虽顽强对抗但仍遭擒拿，率领刘繇之残兵归顺孙策。於赤壁之战後翌年，进攻合淝与张辽展开激战。虽串通合淝城内之戈定等人做攻城内应，却为张辽识破並身中其箭，於大声叫喊「大丈夫生于乱世，当带三尺剑立不世之功；今所志未遂，奈何死乎！」後死去。\n\n史：於赤壁之战前死亡，临终之言相同。\n\n",
