    "biography": "孟获之妻·祝融之弟。\n\n演：於诸葛亮率领蜀国之南蛮压制军进攻时，建议孟获向木鹿大王求援。木鹿大王战亡後，虽佯装已擒拿孟获及祝融之模样欲接近诸葛亮，但遭识破而与孟获同遭逮捕。於受释放後，建议投靠兀突骨。但兀突骨亦遭讨伐，再度遭擒拿後，孟获与祝融均对诸葛亮心悦诚服。\n\n史：並无记载。\n\n",
