    "biography": "魏国武将。\n\n演：２２９年，於诸葛亮进行第三回之北伐进军祁山时，成为张郤之副将迎击。遵从司马懿之作战，攻入蜀军阵营反遭包围，最终为张郤所救。翌年，於司马懿之指挥下进攻蜀国领地，参与诸葛亮与司马懿互比阵势之战局。与张虎、乐綝共同攻击诸葛亮之八卦阵但攻难不破，受俘並遭脱衣裸身驱赶回阵。\n\n史：劝谏曹丕好狩猎之兴趣，曹丕甚感不悦而险遭处刑，幸得减刑一等而逃过一劫。\n\n",
