    "biography": "南蛮秃龙洞之洞主。\n\n演：藏匿为诸葛亮率领之蜀国南蛮压制军所追缉之孟获。以毒泉让蜀军饱嚐苦头，但於孟获之兄·孟节之协助下使蜀军顺利突围。於其後，遭误认为援军之银冶洞主·杨锋之美女军团所逮。於受诸葛亮释放後死守於三江城。虽利用毒箭让蜀军倍嚐艰辛，但遭蜀军所堆积之土囊突破城墙，於乱战中战亡。\n\n史：並无记载。\n\n",
