    "biography": "吴国武将。\n\n演：於刘备军为替关羽復仇而侵略荆州之时，於孙桓之指挥下迎击。於初战同僚之李異与张苞苦战之时，虽意图射张苞之坐骑以援助李異，但李異却遭关兴砍杀。於翌日之对战中为关兴所擒拿後，遭张苞斩首以弔唁其坐骑。\n\n史：並无记载。\n\n",
