    "biography": "刘表之武降。尔後服侍曹操。\n\n演：於刘表殁後，参与欲使刘琮成为继承者之蔡瑁一派之计劃。於决定向曹操投降後，与蔡瑁共同成为投降使者，二者皆奉曹操之命指挥水军。虽於赤壁之战初期战败於吴国水军但受饶恕，更加强化水军之实力。警觉敌方日渐强大之周瑜，故意散播同蔡瑁二人与吴国通敌伪报，致使二人遭盛怒之曹操斩首。\n\n史：因掛念重病之刘表而向刘琦请求面会时，与蔡瑁一同遭到驱赶。並无向曹操投降後之记载。\n\n",
