    "biography": "赵统、赵广之父。蜀国五虎将军之一。\n\n演：受刘备招揽而仕官公孙瓒，但於公孙瓒灭亡後即为刘备效命。於长阪坡之战一夫当关，杀进曹操军救出甘氏与阿斗（刘禅）。於汉中攻防战中，仅以单枪匹马即阻止曹操军进军，受人赞叹「子龙一身是胆」。即使於街亭大吃败仗，亦仅只赵雲之部队，不费一兵一卒而成功撤退。其他诸如於蜀国攻略战、南蛮平定战时亦常与诸葛亮共同远征，受刘备与诸葛亮之完全信赖。\n\n史：於博望之战时擒拿同乡之夏侯兰，为其说情求饶。尔後赵雲即谨慎小心不接近夏侯兰。\n\n",
