    "biography": "五斗米道教祖张鲁之弟。\n\n演：於张鲁与马超联手与刘备交战之时，奉中诸葛亮離间计之张鲁命令，固守重要据点致使马超遭受孤立。於其後，於阳平关迎击进攻汉中之曹操军，但为夏侯渊及张郃所败。於汉中即将遭攻陷之际，对其兄进言火烧汉中。於巴中与许褚交战，战亡。\n\n史：曹操侵略汉中之时，与欲投诚之张鲁意见相左，於阳平关做迎击。於阵营遭野生之鹿破壞而惊愕不已之际，遭曹操军高祚等之攻击，投降。\n\n",
