    "biography": "扬州刺史刘繇之武将。\n\n演：於孙策进军江东之时，置太史慈於不顾以一己为先锋迎击，却败於蒋钦、周泰等人之火攻。虽险遭盛怒之刘繇斩首，因同僚笮融、薛礼等为其求情而免於一死。尔後於秣陵之战时，误认孙策中箭战亡，故遭引诱而出为陈武所弑。\n\n史：驻紮於当利口，为防止袁术势力扩大，与樊能共同与吴景、孙贲等对战。败於孙策军後之消息不明。\n\n",
