    "skills": [],
    "biography": "响应黄巾之乱而蜂起之黑山贼将领。本名为褚燕，接掌张牛角位成为黑山贼首领，改名张燕。因武功高强行动敏捷，故人称「张飞燕」。\n\n演：遭驱赶出城，尔後败於受袁绍庇护之吕布。受即将灭亡之公孙瓒之援军要求时，使者却遭袁绍所捕，无法前往救援。尔後於曹操驱逐袁尚平定冀州後，投降曹操。与乐进、李典一同进攻笼城壶关之高幹。\n\n史：於黄巾之乱後曾一度臣服於朝廷，却於董卓迁都长安後再次举兵，与公孙瓒联手对抗袁绍。\n\n",
