    "biography": "吴国官僚。「吴之四姓」中张家之後。\n\n演：於孙策殁後，受继位之孙权招揽。於赤壁之战前，欲向前来与刘备及孙权结盟之诸葛亮挑发辩论战，但为黄盖所阻。刘备殁後，做为报答为蜀国、吴两国之结盟来访之邓芝之使者，造访蜀国。有伤孙权威严一事並非本意，但仍遭蜀之秦宓驳倒，並由诸葛亮仲裁。\n\n史：以外交手腕荣获蜀国名士颇高评價，返国後赞扬蜀之政治。但此事使孙权甚感不悦，並将肃正官吏纲纪失败而自尽的暨艳之责归咎於其，因而失势。\n\n",
