    "biography": "徐州太守陶谦之部下。\n\n演：原为黄巾之残黨。奉陶谦之命，受曹操招揽前往兖州护卫曹操之父·曹嵩。却为曹嵩一行所持之财宝财迷心窍，故与部下共谋杀尽曹嵩一行，夺取财宝逃往淮南。曹操盛怒难抑故侵略曹徐州，但兖州却因此遭吕布所夺。\n\n史：与演义相同。曹操令陶谦肩负暗杀曹嵩之责，侵略徐州並杀害大量民众。尔後孙盛批评道，责任所在於陶谦，却迁怒破壞陶谦所支配之地区一事实属错误。\n\n",
