    "biography": "黄巾之乱之指导者，太平道教祖。张宝、张梁之兄。自称天公将军。\n\n演：藉由南华老仙所授与之「太平要术书」学得咒术。透过治病组织太平道，自称大贤良师。於各地散佈於苍天（东汉）之後黄天将取而代之等言论，企图颠覆朝廷。於计劃进行当中，同黨之马元义遭捕致使计劃暴露後，率领各地教团纷纷发动反叛。虽对抗卢植及董卓所率领之反叛镇压军处於優势，却於不久後病亡。\n\n史：於张角举兵後，黑山、白波等地之贼军亦开始举兵，各自率领著数千至数万不等之兵力。\n\n",
