    "biography": "吴国重臣·张昭之么子。张承之弟。\n\n演：於孙权即位成为吴国初代皇帝之时，担任皇太子·孙登之辅佐。\n\n史：与诸葛恪、顾谭、陈表同为孙登之学友，对孙登讲解「汉书」。因其兄张承受封为其他爵位之故，於张昭殁後即继承其爵位。於孙登早逝後，返回中央晋昇为侍中、杨武将军。却遭捲入孙和与孙霸之继承者之争，因遭孙霸一派造谣抹黑，故而受命调往交州。尔後，因受对立之孙弘之计所害，奉命自杀。\n\n",
