    "biography": "魏国武将。\n\n演：於响应诸葛亮第五次北伐号召之吴国陆逊来袭之时，於曹叡之指挥下，与满宠同夜袭吴国之巢湖口之水上要塞，击破诸葛瑾之水军。因受夜袭，故使陆逊迫不得已而撤退，使得魏国终可专注於与诸葛亮北伐军之对战。\n\n史：並无记载。\n\n",
