    "biography": "蜀国武将。\n\n演：参与诸葛亮之压制南蛮行动。与孟获之妻·祝融对战，却因身中飞刀而受捕。尔後於诸葛亮与姜维之北伐中表现傑出。２５６年，段谷挺身救出受邓艾包围之姜维，自身却於乱矢箭雨中战死。\n\n史：於诸葛亮之北伐时，遵从马忠之指挥讨伐羌族，尔後成为越巂太守，以民族融合方式统治南方之異民族。据说此即为演义中，诸葛亮压制南蛮剧情之原型。２５４年，与魏国徐质交战身亡。南方之異民族因惋惜其之死，建庙宇以供祭祀。\n\n",
