    "biography": "袁术之武将。\n\n演：於袁术自封皇帝後奉命为大将军，率领二十万大军进攻吕布之徐州。却因吕布部下陈珪之计谋致使韩暹与杨奉背叛，故大吃败仗。\n\n史：於袁术前往九江後，与桥蕤等人奉命为大将军。由衷地尊敬孙策，於袁术殁後与杨弘等人一同投靠孙策。却遭庐江太守刘勋埋伏，故遭逮捕。於孙策攻下庐江之时逃走，投靠曹操。\n\n",
