    "biography": "魏国武将。原为袁绍部下。\n\n演：於官渡之战时加入袁绍之军队。於乌巢遭曹操突袭时，採纳郭图之策，与高览共同进攻曹操之本营，败退。因遭郭图转嫁战败之责，不得已向曹操投降。尔後成为魏将转战各地。於进攻汉中张鲁时与夏侯渊一同担任先锋。於与刘备之汉中攻防战惨败於张飞，险遭曹洪斩首。於诸葛亮发起北伐时，虽於街亭击破马谡，让蜀军大吃苦头，却於第四回北伐时战亡於木门道。\n\n史：黄巾之乱时，於韩馥之指挥下进行镇压。\n\n",
