    "biography": "蜀国武将。赵雲之次男。赵统之弟。\n\n演：於诸葛亮第二回北伐前赵雲死後，告知诸葛亮讣闻。受刘禅任命为牙门将，与其兄一同奉命令防守赵雲之墓地。\n\n史：２６２年，追随姜维於沓中驻紮。尔後前线阵亡。\n\n",
