    "biography": "黄巾之武将。\n\n演：於张角病故後，与韩忠、孙仲共同率数万兵力佔领宛城。遭朱[0xFA][0x45]与刘备所率领之讨伐军攻击，於韩忠大吃败仗後提出投降请求，但遭朱[0xFA][0x45]拒绝。虽因奋战曾一度夺回宛城，却遭前来援助朱[0xFA][0x45]之孙坚军攻击，操槊欲刺杀孙坚之时反遭讨伐。\n\n史：於南阳黄巾总帅·张曼成遭秦颉讨伐後接掌其位，以十万餘兵力佔领宛城。於朱[0xFA][0x45]包围下努力苦撑数月，但最终遭朱[0xFA][0x45]突袭所杀。\n\n",
