    "biography": "董卓之武将。张绣叔父。其妻为邹氏。\n\n演：在董卓被王允和吕布杀掉後，与李傕、郭汜、樊稠一同佔据长安，杀王允後拥立献帝。成为骠骑将军驻紮於弘农。於面临马腾及韩遂之进攻时与樊稠共同迎击予以击退。１９５年，於李傕及郭汜发生争执时，前往长安进行调停，使献帝逃出长安。翌年，於攻击南阳之时遭流箭击中死亡。残存势力即由外甥张绣率领。\n\n史：驻紮於长安後，因兵粮耗尽之故迁往南阳。於攻击穰时中流箭身亡。\n\n",
