    "biography": "董卓之武将·张济与邹氏之外甥。後服侍曹操。\n\n演：叔父张济於攻击南阳时战亡，故接掌兵权佔领宛城。１９７年，遭曹操攻击，採纳参谋贾诩之进言投降。但尔後因曹操与邹氏私通相当愤怒，故突袭曹操。讨伐典韦、曹昂而夺回宛，並与刘表联手与曹操续继对战。於袁绍与曹操之对决逼近时，聽从贾诩助言归顺曹操。\n\n史：於官渡之战时从军並屡建功绩。２０７年，於讨伐乌丸之时病故。亦有一说为因受曹丕责备「杀我兄长，还能装作若无其事地来见我」而自杀。\n\n",
