    "biography": "魏国官僚。张既之子。曹芳之张皇后之父。\n\n演：光禄大夫。於吴国诸葛恪掌握政权後，司马师预言其之政权将维持不久。不久後诸葛恪即灭亡。２５４年，与夏侯玄、李豊一同为曹芳所唤商量讨伐司马师之事，於归途时密诏为司马师所夺，东窗事发。其他参与者亦遭受处刑。\n\n史：与李豐为同乡。２５２年，虽其女曹芳成为皇后，但尔後对远離政治实务此事甚为不满。２５４年，与李豐共同让司马师失势，订定计劃使夏侯玄成为大将军，自己则成为骠骑将军，却因事迹败露而被杀。\n\n",
