    "biography": "蜀国武将。张飞之孙，张苞之子。\n\n演：尚书。於魏国邓艾侵略蜀国时防守绵竹关，於诸葛瞻之指挥下战鬥。於诸葛瞻因等候不及吴国援军到来即出击战亡後，劝谏诸葛瞻之子诸葛尚追随父亲出征。但诸葛尚並不聽劝告，於出征後战亡。尔後受邓艾总攻击，与同僚黄崇、李球等人自始至终奋战不懈，战亡。\n\n史：与演义之描述相同。\n\n",
