    "biography": "司马懿之妻。司马师、昭之母。晋国之宣穆张皇后。\n\n演：並无记载。\n\n史：於司马懿装病以拒绝曹操邀其仕官要求时，因整理书籍之时遭傭人所见，为不使装病一事被拆穿故杀傭人。因此事而使司马懿对其另眼相看。但於柏氏受宠爱後，则为司马懿疏远。前往探望司马懿病情之时，因遭拒绝会面愤而断食。因其子们亦一同断食，故使司马懿谢罪。博学多闻，故常愚弄司马懿。\n\n",
