    "biography": "吴国幕僚。与张紘一同被称为「江东二张」之策士。\n\n演：於孙策进军江东之前，於周瑜之建议下与张紘同受招揽。孙策於临终时，留下盼其於内政方面辅佐继位者孙权。於赤壁之战时主张向曹操投降。於诸葛亮欲与孙权结盟共同对付曹操时，企图以辩论战驳倒诸葛亮但失败。尔後则以吴国元老名份继续辅佐孙权。\n\n史：曾为徐州名士，为避开战乱而逃往江东。个性刚直，曾因拒绝陶谦之推薦而遭入狱，亦曾因与孙权口角而遭纵火烧屋。\n\n",
