    "biography": "刘璋之幕僚。张肃之弟。\n\n演：於刘璋受张鲁胁迫时，成为使者向曹操要求援军。因受曹操粗暴对待，故驳倒杨修，背诵曹操之「孟德新书」使操大为震惊。但其态度激怒曹操，交涉决裂。於回程时受刘备欢迎，计劃欲使刘备代替刘璋成为蜀国统治者。故将蜀国地图交予刘备，以防禦张鲁之名目使刘备成功进入蜀国。虽催促刘备崛起，却遭张肃通风报信而被刘璋处刑。\n\n史：於与刘备会面之时，画蜀国地图，传达内情。\n\n",
