    "biography": "蜀国官僚。张飞之次男。张苞之弟。\n\n演：於张飞殁後，代替夷陵出征之兄长张苞，防守领地。日後成为私署侍中、尚书僕射。２６３年，绵竹关为魏国之邓艾所突破後，遵照刘禅之决定，与谯周、邓良一同将玉玺交予邓艾宣告投降。於蜀国灭亡後，与张峻一同周遊国内诸郡，说服抵抗不懈之军民。翌年，与谯周、樊建、郤正一同追随刘禅迁移洛阳。\n\n史：於其兄张苞早逝後继承。於蜀国投降後，並未追随刘禅前往洛阳。\n\n",
