    "biography": "吴国武将。张绍长男。张休之兄。因其妻子早逝之故，娶诸葛谨之女为续弦。两人所生之女日後成为孙和之妃。张震之父。\n\n演：２３４年，当孙权呼应诸葛亮第五回北伐攻击魏国时，奉命与孙韶一同自广陵往淮南进攻。\n\n史：年少时即以才学出名，与诸葛瑾、步骘、严畯等有深交。於长沙讨伐山间異民族後，成为濡须都督、奋威将军。观人眼力颇高，发掘蔡款、谢景等人，並预言诸葛恪之灭亡。\n\n",
