    "biography": "刘璋之武将。\n\n演：於刘璋欲迎接刘备进入蜀国对抗张鲁之时，提出反对但不为刘璋所採纳。於刘璋举宴欢迎刘备时，阻止假装舞剑实为企图砍杀刘璋之魏延。於刘备向刘璋开始进攻後，与刘[0xFA][0x41]、冷苞、邓贤等人一同於雒城迎击。並於落凤坡射杀庞统让刘备军吃尽苦头。却因诸葛亮之策略於金雁桥受捕，因拒绝投降而遭斩首。\n\n史：虽力抗刘备侵略近一年，仍於雁桥被捕。大声喊道「老臣不事二主」後遭斩。\n\n",
