    "biography": "吴国官僚。丞相。\n\n演：於晋国之吴国讨伐军逼近时派遣军队迎击，自身亦追随沈莹及诸葛靓出征。对深知与晋军兵力之差距而建议投降之诸葛靓曰，「吴国即将灭亡一事，为众所皆知之事，无一人殉於国难，岂不为可耻之事！」。於决战当日，与沈莹一同向晋军突击，奋战至最终遭斩杀。\n\n史：预见魏国将平定蜀国。於晋军逼近之际，与孙震、沈莹、诸葛靓共同於版桥迎击。虽於序盘击败张乔，但无法防止张翰、周浚等人之攻击，最後为王浑所杀。\n\n",
