    "biography": "蜀国武将。赵雲之长男。赵广之兄。\n\n演：於诸葛亮第二回北伐前，与其弟赵广一同造访诸葛亮，告诉其父赵雲病故之事。奉刘禅之命为虎贲中郎，与赵广一同奉命守护赵雲之墓。\n\n史：於赵雲死後接掌其位，昇至虎贲中郎、督行领军。\n\n",
