    "biography": "魏国武将。\n\n演：牙门将军。防守合淝新城。２５３年，於遭诸葛恪包围，攻垮城墙之时，对吴军道「依魏国法律百日之内若援军未至，纵使投降亦不被问罪。於数日後即满百日请再稍做等待」。於吴军停止攻击後，即趁隙修復城墙。再次展开战鬥後以箭射中诸葛恪，尔後奋战不懈至吴军因暑气及疾病而鸣金收兵。\n\n史：诸葛诞对张並无任何评價。但为诸葛诞之後任之毌丘俭认同，受命担任合淝新城守备。\n\n",
