    "biography": "袁熙之武将。\n\n演：於曹操灭袁谭後，与同僚焦触一同向曹操投降，攻击逃至幽州之袁熙及袁尚。於曹操侵略荆州时从军。於长阪坡之战虽想阻止抱刘禅逃跑之赵雲，为赵雲所突破。於赤壁之战初战向曹操表示希望能担任前锋，与焦触一同挑战孙权军却遭吴国之周泰所击倒。\n\n史：於袁谭受曹操之攻击灭亡後，倒戈转而攻击袁熙及袁尚，将其等驱赶至幽州。並无此後之记载。\n\n",
