    "biography": "蜀国武将。\n\n演：於关羽遭孙权讨伐後，刘备为夺回遭孙权所夺之荆州而举兵，於此时与冯习一同成为副将从军。初战与吴班、冯习共同攻击吴国孙桓，包围夷陵城。於刘备惨败於陆逊後前往援救刘备，却遭陆逊与孙桓夹攻，与冯习一同战亡。\n\n史：於刘备於荆州之时仕官，共同进入益州。於夷陵之战败於陆逊，与冯习一同战亡。\n\n",
