    "biography": "东汉之陈留太守。清流派名士，为「八厨」中之一人。袁绍、曹操之友。广陵太守张超之兄。\n\n演：响应曹操发起之讨伐董卓檄文之其中一位诸侯。於曹操攻击徐州之陶谦时担任仲裁但遭拒。尔後与陈宫及吕布联手，企图自曹操夺取兖州但失败。尔後因遭曹操攻击，故投靠袁术。\n\n史：虽加入反董卓联盟但与袁绍对立。虽险遭暗杀，但为曹操所救。尔後採张超之计与吕布联手，与曹操对战遭败北。与吕布一同投靠刘备，最後於前往袁术处，请求救援之途中遭部下杀害。\n\n",
