    "biography": "东汉之桂阳太守。其兄嫂为樊氏。\n\n演：赤壁之战後，遭刘备之部下赵雲攻击，投降。因与赵雲同姓、同年、同乡故意气相投。却因引见未亡人兄嫂．樊氏一事使赵雲心生不快，二人反目成仇。命令部下鲍隆、陈应袭击赵雲但失败。最後向刘备投降，留任桂阳太守之位。\n\n史：赤壁之战後向刘备投降。赵雲奉命为新任桂阳太守。不久後逃亡。\n\n",
