    "biography": "刘备、关羽之义弟。张苞、张绍之父。正史中字为益德。\n\n演：於桃园立誓与刘备、关羽结为义兄弟。虽正义好汉，却常喝酒误事，奉刘备之命守护下邳之时，因烂醉遭吕布夺城。但论武勇可谓数一数二，於长阪坡之战亦曾单枪匹马赶走曹操大军。於益州侵略战时，利用智谋逮捕严颜时亦知礼数，以将军身份看来成长甚多。但於关羽復仇战时，却因鞭打要求再通融準备出阵时间之范彊及张达，故遭懷恨在心，於酒醉之时遇害。\n\n史：其妻为夏侯霸表妹，其女则成为刘禅之皇后。\n\n",
