    "biography": "吴国之左将军。孙休之亲信。\n\n演：察觉孙綝除废立吴帝·孙亮外亦欲加害新帝·孙休一事，故与丁奉一同讨伐孙綝一黨。於孙休死後，与万彧共谋违背遗言，推举孙皓为皇帝。尔後因劝谏其施行暴政而触怒孙皓，一族满门抄斩。\n\n史：自孙休为王之时即为臣子，於孙休成为皇帝後受特别之待遇。讨伐孙綝後，与丞相之濮阳兴共掌权势。孙皓施行暴政之时，後悔使孙皓即位一事，尔後因言行遭密告，故遭杀害。\n\n",
