    "biography": "张飞之长男。张绍之兄。张遵之父。关兴之义兄。\n\n演：於张飞遭部下范彊、张达所杀，而范彊等人逃往吴国後，加入刘备指挥下之吴国讨伐军。於互争先锋一职之时与关兴缔结为义兄弟，二人同心协力於初战获勝。杀遭吴国遣返之范彊及张达为父报仇。但刘备军却於夷陵之战惨败於陆逊。其後参加诸葛亮之北伐。於第三回北伐时於追击魏国之郭淮、孙礼中跌落谷底，因受伤之故不久後死亡。\n\n史：仅有英才早逝，由其弟张绍接掌其地位之记载。\n\n",
