    "biography": "黄巾首领张角之次弟。张梁之兄。地公将军。\n\n演：与张梁一同率领颖川之黄巾军，皇甫嵩与朱[0xFA][0x45]率领官军迎击。於长社遭火攻，亦受曹操突袭而败北。张宝使用可掀起烈风及招引落雷之妖术使官军倍感艰辛，但因法术为朱[0xFA][0x45]所破，亦中刘备之箭故逃往阳城。受朱[0xFA][0x45]包围，而落城快被攻陷时，遭部下严政刺杀，首级被献与朱[0xFA][0x45]。\n\n史：於下曲阳为皇甫嵩及郭典所败，被杀。\n\n",
