    "biography": "黄巾之武将。\n\n演：並无记载。\n\n史：自称『神上使』，率领数万兵力於南阳举兵。杀太守褚贡並佔领宛长达数个月，最後为後任太守秦颉所杀。南阳黄巾於其後以赵弘、韩忠、孙夏等人为中心团结一致，於孙夏遭朱[0xFA][0x45]讨伐前抵抗不懈。\n\n",
