    "biography": "东汉之河内太守。\n\n演：於任上黨太守之时，响应曹操讨伐董卓之号召。尔後成为河内太守。於献帝脱離李傕、郭汜之支配迁移至洛阳之时，因援助食粮之故受任命为大司马。於吕布遭曹操包围时，为援救吕布而欲自曹操背後进行攻击，却遭曹操之部下杨醜所杀。\n\n史：於袁绍发起董卓讨伐军时驻紮於上黨，与匈奴之於夫罗共同协助袁绍。却因於夫罗企图反叛而瓦解，一时为於夫罗所捕。尔後受董卓任命为河内太守。\n\n",
