    "biography": "蜀国武将。\n\n演：於刘备与刘璋起纷争时，做为刘[0xFA][0x41]部下与刘备军对战，眼见大势已去杀刘[0xFA][0x41]投降。其後参与曹操之汉中攻防战、夷陵之战、压制南蛮、诸葛亮之北伐。於诸葛亮殁後支援姜维之北伐，於剑阁奋战不懈至投降於钟会为止。於蜀国灭亡後翌年，於姜维及钟会反叛魏国之际，遭捲入混乱，死亡。\n\n史：於刘备成为益州牧後受登用。执法严厉，亦严格统治異民族，受诸葛亮之信赖。昇至左车骑将军。反对姜维之北伐。\n\n",
