    "biography": "吕布之武将。尔後服侍曹操。张虎之父。\n\n演：於吕布战亡下邳之时被捕，因刘备及关羽之建议而受曹操任用。於曹操军将关羽包围於下邳时说服其投降。於官渡之战後负责指挥讨伐乌丸、於白狼山讨伐蹋顿。於赤壁之战後进入合淝，防守魏吴国境。２１５年，与李典、乐进共同於逍遥津大败孙权军，其令人可畏可使哭泣中之孩童，仅闻其名则立即安静无声。２２４年，追随曹丕进攻吴国之时，身中丁奉之箭，不久後因箭伤而亡。\n\n史：２２２年，与曹休共同击败吴国之吕範，病亡。\n\n",
