    "biography": "黄巾首领·张角之三弟。张宝之弟。人公将军。\n\n演：协助其兄张宝与皇甫嵩及朱[0xFA][0x45]率领之官军对战。却於长社遭火攻，再加上受曹操军突袭而败逃。其後亦遭受皇甫嵩及曹操之追击，虽曾七度力做抵抗，但仍被突破遭砍杀。\n\n史：於广宗与皇甫嵩军作战，於初战时获勝。却於翌日早朝遭皇甫嵩军之奇袭，惨败被杀。\n\n",
