    "biography": "蜀国军前都督、粮秣官。\n\n演：於关羽指挥下防守荆州。关羽攻击樊城之曹仁时，奉命随军。是为无比忠诚之人物，王甫亦曾推薦关羽「与其潘濬，不如交由赵累留守荆州为妥」。於关羽进攻樊城，荆州遭孙权所夺之时，进言向刘备请求救援。於关羽逃離麦城返回益州之时从军，遭孙权军伏兵战亡。\n\n史：与关羽父子同遭潘璋之部下马忠所捕。\n\n",
