    "biography": "东汉之汉寧太守。五斗米道之祖·张陵之孙。张卫之兄。\n\n演：察觉曹操於讨伐马超後，因故做西进之举，策劃欲夺取刘璋之蜀与之对抗。於刘备攻击刘璋之时，派遣马超与曹操军对战。２１５年，於曹操进攻汉中时，命令张卫与庞德迎击但败北。张鲁认为仓库为国家託付之物，因此不予烧却而仅与查封，於逃亡至巴西郡後，投降。尔後因未烧仓库一事获颇高评價。\n\n史：奉刘焉之命令指挥汉中之攻击，夺取兵力於汉中独立。时至刘璋时代因不从之故，其母与家族皆遭刘璋所杀害。\n\n",
