    "biography": "袁术武将。\n\n演：於自封皇帝之袁术向吕布进攻之时从军，却因杨奉、韩暹等人向吕布军倒戈而大败。尔後，於曹操进攻寿春之时候与李豐、乐就、梁纲共同防守寿春城。然而因不敌，故与其他僚将领共同受捕，遭处刑。\n\n史：受袁术任命为九江太守。但因袁术曾应允孙策赐其九江太守之位，而致使不服此事之孙策，脱離袁术而独立之心油然而生。\n\n",
