    "biography": "东汉之中牟县令。服侍曹操後，转向吕布效命。\n\n演：虽逮捕暗杀董卓失败之曹操，却於得知曹操之志向後与其共同行动。但於曹操因误会而斩杀礼遇自己之吕伯奢时，领会曹操之无情即分道扬镳。於曹操攻击陶谦之徐州之际，企图说服曹操放弃做战却失败，联合张邈、吕布自曹操手中夺取兖州。尔後成为吕布参谋，持续与曹操军抗战，最後与吕布一同於下邳遭捕。顽强地抗拒服侍曹操，进而将颈项迎向刀刃，斩首。\n\n史：並无援助暗杀董卓失败之曹操之描写。\n\n",
