    "biography": "魏国幕僚。陈本、陈骞之父。\n\n演：於赤壁之战後，与曹仁一同防守江陵。迎击进攻而至之周瑜，於曹仁为周瑜战亡谎报所骗而出征期间，负责守城。但城却为奉诸葛亮之命之赵雲所夺，战败逃亡。於曹操殁後，建议曹丕无需等候诏令直接即位为魏王，与华歆、王朗等人一同逼迫献帝让位。\n\n史：拒绝孙策与袁术之招揽，与陈登一同防禦孙策之侵略。尔後前往中央成为魏郡太守，於讨伐汉中後就任尚书。尔後历经尚书令昇至司徒。\n\n",
