    "biography": "魏国官僚。陈泰之父。祖父陈寔、其父陈纪、叔父陈谌都皆为东汉之名臣。\n\n演：於曹操临终之际，与曹洪、贾诩、司马懿等人共同受託付後事。曹操殁後逼迫献帝让位。而於曹丕死後成为司空，与曹真、司马懿共同辅佐曹叡。\n\n史：服侍首次支配豫州之刘备，於刘备败於吕布後前往徐州。於吕布战亡後服侍曹操。於曹丕仍为皇太子之时，与司马懿、吴质、朱铄共同成为学友。於曹丕成为皇帝後献策「九品官人法」。此法成为魏晋南北朝时代任官制度之基础。\n\n",
