    "biography": "魏、晋国武将。陈矫之次男。陈本之弟。\n\n演：於诸葛诞叛乱之时，成为安东将军做反叛讨伐军之副先锋。於吴军进攻前来援护诸葛诞时，与主先锋之王基共同与吴军交战。因锺会之策略，受物资所诱之吴军遭伏兵击溃。尔後於司马炎成为晋王时，受任命为车骑将军。\n\n史：於尚书在任之时，曾因赋诗太慢险遭罢免。於蜀国灭亡後，於元蜀臣罗宪遭陆抗、步协等人攻击之时，接受罗宪之救援请求，派遣胡烈前往援救。为晋朝立国之功臣，高昇至太傅。\n\n",
