    "biography": "蜀国官僚。尔後为晋国效命。正史「三国志」作者。\n\n演：並无记载。\n\n史：尊蜀国之谯周为师，学习「史记」「汉书」等。於蜀国灭亡後，受罗宪推薦为晋国效命。因著「诸葛亮集」「古国志」受张华颇高评價，尔後编纂「三国志」。有一说为陈寿之父为陈式，亦有一说则为陈寿为於街亭败北之马谡之参军（无论为何皆遭诸葛亮之处罚），但不详。其外，亦有陈寿遭诸葛亮之子·诸葛瞻疏远。据说此为於「三国志」中，诸葛亮及诸葛瞻评價不高之故。\n\n",
