    "biography": "袁绍幕僚。尔後服侍刘备。\n\n演：於刘备败於曹操而与关羽離散之时，担任刘备与关羽之联络人。尔後，成为袁绍使者造访孙策，欲说服孙策共同讨伐曹操，但不久後孙策猝死。袁绍败北後服侍刘备，於诸葛亮之「出师表」中，与郭攸之、费褘、张裔、蒋琬等人並称为忠义之士。於孙权登上帝位时，做为祝贺使者访问吴国。\n\n史：於刘备担任荆州牧之时，受刘备起用，全权承揽诸郡之政务。\n\n",
