    "biography": "魏国重臣·陈群之子。其妻为荀顗之女。\n\n演：与郭淮同击退反叛魏国之夏侯霸。尔後连与姜维之北伐军对战。对在狄道之战时援救身陷绝境之王经，故僚将邓艾给予其颇高之评價，二人结为「忘年之交（无视年龄差之交友）」。因马昭之心腹·贾充之计致使皇帝·曹髦遭暗杀後，魏国臣子中仅其一人拒绝司马昭之召集。於荀顗前来迎接之时，其感叹「义父大人竟不如我」，而果决地对司马昭说道「不杀贾充，则无法对天下交代」。\n\n史：统率军队建立功绩，能力之评價远勝其父。\n\n",
