    "biography": "吴国武将。陈武之妾所生之子。陈脩之弟。\n\n演：並无记载。\n\n史：与诸葛恪、顾谭、张休同为皇太子·孙登学友。与暨艳深交，於暨艳因任用官吏失败而遭问罪之时，仅其一人因未责备暨艳而受佳评。陈表提出欲成为有如陈武般之将军之请，因厚待受士兵而使得其等心悦诚服。２３４年，与诸葛恪一同讨伐山越，尔後於镇压反叛之时，亦因奖励归顺获得士兵。於３４岁时死亡。财产因礼遇士兵而如数用罄，故其妻受孙登所保护。\n\n",
