    "biography": "吴国武将。陈脩，陈表之父。\n\n演：面黄目赤，容貌怪異。於孙策进军江东时受录用，讨伐刘繇之部下张英。尔後，参与赤壁之战、南郡攻略战。於刘备及孙尚香重返荆州之时，欲与潘璋等人一同带回，却於孙尚香一声喝令下撤退。２１５年，於濡须口与曹操军交战，虽与庞德展开激战，却因上衣遭树所缠，动弹不得遭讨伐。\n\n史：指挥庐江之精锐部队，人称所向无敌。於攻击合淝中战亡，爱妾亦奉孙权之命殉死。\n\n",
