    "biography": "袁术之武将。\n\n演：与雷薄共同成为纪灵副将，进攻位於小沛之刘备，但因吕布之仲裁退兵。於袁术自封为帝後，吕布於讨伐战中率领第五军，却因杨奉及韩暹向吕布倒戈大吃败仗。尔後放弃追随袁术，与雷薄共同死守於嵩山，於袁术遭刘备攻击战败而逃之时，袭击袁术军夺取金银财宝。\n\n史：於曹操与袁绍对战时，梅乾（梅成）、雷绪一同率领数万兵力於长江、淮河一带为恶作乱。尔後为张辽、张郃、于禁等人讨伐处斩。\n\n",
