    "biography": "曹操之参谋。程武之父。程晓之祖父。本名为程立。\n\n演：受荀彧推薦服侍曹操，其自身亦推薦郭嘉。於曹操侵略徐州，而兖州为吕布所夺之时，与荀彧协力守住三县而得以保住地盘。於仓亭之战时献上「十面埋伏之计」，大破袁绍军。於曹操军苦战於刘备军之军师·徐庶之时，献上「送出其母受我方保护之伪信，设法拉拢徐庶成为我方」之策。赤壁之战时，对曹操进言应警戒火攻，亦早已看穿黄盖诈降一事，惜亦无法阻止败战。\n\n史：因梦见泰山支撑太阳之梦，故改名为程「昱」。\n\n",
