    "biography": "韩遂之武将。\n\n演：追随为向杀害马腾之曹操復仇而举兵之马超及韩遂，攻陷长安、潼关。於渭水之战，虽夜袭曹操阵营，却误入陷阱与张横一同战亡。\n\n史：於东汉末期，为割据长安以西（关中）之军阀之一。２１１年，与马超及韩遂会合开始反叛，却於渭水之战败於曹操，与侯选一同投靠汉中之张鲁。２１５年，因曹操之汉中讨伐使张鲁降服之故，亦同时向曹操投降。\n\n",
