    "biography": "东汉之群雄。\n\n演：荆州刺史。吕布之养父。於何进遭宦官暗杀前，受招集之群雄之一。反对早一步上洛而得政权之董卓所主张之少帝废立，率领吕布击溃董卓军。但因李肃之说服向董卓阵营倒戈而遭吕布暗杀，军力亦遭夺取。\n\n史：并州刺史。驻紮於河内时，因赏识吕布而录用之。受何进招集上京成为执金吾，却遭受董卓唆使之吕布所杀，军力遭夺取。\n\n",
