    "biography": "服侍孙坚、孙策、孙权三代之吴国老臣。程咨之父。\n\n演：成为参与反董卓联盟之孙坚之参谋对抗董卓军、於汜水关讨伐胡轸。至洛阳後，与孙坚共同发现玉玺。於孙坚战亡後辅佐孙策、孙权，於赤壁之战时为主张与曹操交战之武鬥派中心人物。虽於最初受分发至年若之周瑜底下而心懷不满，但於知晓周瑜之指挥能力为适才适所後，心悦诚服。尔後追随周瑜於赤壁、南郡接连抗战。\n\n史：於讨伐黄巾後追随孙坚。周瑜殁後成为南郡太守。因与刘备分割荆州而迁移至江夏後，死亡。\n\n",
