    "biography": "吴国武将。丁封之兄。\n\n演：於孙策殁後受孙权招揽。参与赤壁之战、南郡攻略战、关羽讨伐战、夷陵之战等战役。２２３年於曹丕进攻吴国之时，援护施伪城计做迎击之徐盛，射中魏之张辽。２５２年，於魏军趁孙权之死而进攻之时，於东兴击退胡遵。２５８年受孙休密令诛杀孙綝。２６３年，於魏国发起蜀国讨伐战时，应允诸葛瞻之请求前往救援。\n\n史：於甘寧、陆逊、潘璋等人之指挥下表现傑出。於演义中为较同僚徐盛年轻之世代。高昇至大将军。\n\n",
