    "biography": "曹操之武将。手操八十斤之双铁戟。\n\n演：虽原服侍张邈，但受夏侯惇赏识担任曹操之护卫。於濮阳与吕布军战鬥时，救出遭火攻之曹操。於讨伐黄巾残黨之何仪时，与出现於当时之许褚交战不分高下。１９７年，於曹操接受张绣投降而进驻宛时，守卫曹操之住所。遭谋叛之张绣参谋·贾诩施计夺走武器。於曹操住所遭夜袭之时挺身而战，战亡。\n\n史：为单手可举起论谁皆无法扬举之牙门旗之怪力士。不分昼夜守卫曹操宅邸。\n\n",
