    "biography": "魏国武将。田畴之姪孙。\n\n演：２６３年，参与锺会及邓艾之蜀国讨伐战。於攻下江油城之时，向邓艾进言，应使士兵休生养息，险遭邓艾处斩。於蜀国灭亡，锺会殁後，奉畏惧邓艾报仇之卫瓘命令，杀害邓艾父子。\n\n史：田畴获德义之评價颇高，於曹丕即位之时，奉命继承其位。参与蜀国讨伐战，因拒绝江油之战之进军命令而险遭邓艾斩首。於锺会殁後，奉卫瓘之命杀害邓艾父子。\n\n",
