    "biography": "东汉之议郎。\n\n演：服侍袁绍。於袁绍殁後曹操计劃欲讨伐乌丸之际，受招揽成为路径嚮导。讨伐乌丸之後，受命担任柳城之防卫，但坚决推辞。\n\n史：服侍刘虞，早已警戒公孙瓒。做为拜会献帝之使者前往长安，却因刘虞遭公孙瓒所杀之故隐居。不回应袁绍及袁尚之招揽，退隐至北方施行德政。因痛恨於四处破壞乡里之乌丸，故协助曹操讨伐乌丸。事後却坚决请辞曹操之任用，由其深交之夏侯惇进行劝说亦遭拒。\n\n",
