    "biography": "袁邵之参谋。\n\n演：於袁绍压制冀州後，统治冀州。将与曹操进行决战时主张长期战，但未受採用。於官渡之战前反对短期决战，遭打击士气之罪名入狱。袁绍败於官渡之战後，遭逢纪控诉「田豐於狱中大笑」，奉命受处。但自知难逃一死之田豐却早已自尽。荀彧评其「刚直故忤逆上司」。\n\n史：於曹操与张绣对战之时献上夺回献帝之策，但未受採纳。\n\n",
