    "biography": "魏国武将。\n\n演：２３４年，於吴国响应诸葛亮之第五回北伐，向魏国进攻之时，援助襄阳之守备。\n\n史：服侍刘备之时，亦受颇高之评價，但因其母高龄之故而返乡。尔後服侍公孙瓒。於公孙瓒灭亡後服侍曹操，历任县令太守政绩斐然。２１８年参与曹彰之乌丸讨伐战，高昇为南阳太守。於曹丕即位後担任防禦北方異民族之任务，因杀乌丸王骨进之故，威名大噪。２３４年，於吴军进攻之时，成为汝南太守负责防卫。历任并州刺史、卫尉。\n\n",
