    "biography": "吴国官僚。滕冑之子。\n\n演：太常卿。与丞相诸葛恪对立，２５３年，与孙峻共谋讨伐诸葛恪。尔後成为大司马，却遭丞相孙綝所杀。\n\n史：曾投靠同乡，亦有亲戚关係之刘繇。因其父及孙权亲近之故，於孙权成为吴王後即倍受礼遇迎娶公主为妻。於孙权殁後，奉命遗嘱与诸葛恪共同辅佐次帝·孙亮。尔後当孙綝掌握实权之时，企图欲与吕据一同讨伐孙綝，但因计劃暴露遭杀害。因与诸葛恪为好友，並未协助暗杀诸葛恪。\n\n",
