    "biography": "董和之子。与诸葛亮、蒋琬、费禕並称「蜀国四相」。\n\n演：於诸葛亮北伐中，与郭攸之、费禕一同负责留守。於诸葛亮殁後，魏延及杨仪发生对立之时支持杨仪。並为说服魏延而前往汉中，但到达之时魏延已遭马岱所杀。\n\n史：於刘备立刘禅为太子之时，负责担任刘禅之教育。於诸葛亮殁後亦辅佐刘禅，扼阻黄皓等恶臣之抬头。历任辅国大将军、侍中守尚书令等，於好友·费禕成为大将军後，做为其次官担当国政。董允死後，由黄皓掌握政权，致使蜀国迈向灭亡之路。\n\n",
