    "biography": "刘璋之幕僚。尔後服侍刘备。董允之父。\n\n演：於刘璋麾下任益州太守。蜀国受刘备攻击时，进言邀请张鲁援助。於刘备逼近成都时主张彻底长期抗战，於最後刘璋降服。尔後服侍刘备、辅佐诸葛亮。\n\n史：东汉末期，率领一族成员移住益州，为刘璋所任用。力行勤俭节约，与異族融合为努力方针，施行良好统治。於刘备平定蜀国後服侍刘备、辅佐诸葛亮。以直言之士获诸葛亮之信赖。\n\n",
