    "biography": "魏国武将。邓忠之父。\n\n演：以兖州刺史之身参与镇压毌丘俭反叛之战後，接连与姜维之北伐军交战。受共同作战之陈泰之颇高评價，二人结为「忘年之交（超越年龄之交）」。２６３年，奉司马昭之命，与锺会共同挑起蜀国讨伐战。趁锺会於剑阁与姜维交战之时，通过阴平之山道。於绵竹关杀诸葛瞻，並使刘禅投降。但於战後因旧蜀国领地之统治问题与锺会对立。遭冠以谋反嫌疑，於护送洛阳途中遭田续所杀。\n\n史：受司马懿赏识其才能，实行屯田政策立下功绩。\n\n",
