    "biography": "蜀国幕僚。\n\n演：於诸葛亮征伐南蛮及北伐时从军，与樊建共同辅佐诸葛亮。尔後成为辅国大将军防守剑阁。於魏国之锺会与邓艾突破阳平关进入蜀国境内後，与姜维、张翼、廖化一同於剑阁抗战。但因成都先遭攻陷之故，而向锺会投降。於刘禅移往洛阳之时，称病拒绝同行，不久後病亡。\n\n史：蜀国末期，与诸葛瞻、樊建等人一同担任政务。但因无法阻止姜维之远征及黄皓之专横，致使国力日渐疲软。於蜀国灭亡後与樊建共同追随刘禅，移住洛阳。\n\n",
