    "skills": [],
    "biography": "蜀国武将。孟达之外甥。尔後为魏国效命。\n\n演：与因未派遣援军於关羽而险遭处罚之孟达一同对魏国投降。於诸葛亮开始北伐之际，孟达欲向蜀国倒戈之时，与李辅一同通报司马懿。於孟达为司马懿所讨伐後，奉命任上庸之守备工作。\n\n史：刘璋的武将。於刘备侵略蜀国之时，与张任一同抗战，於绵竹笼城。尔後於刘璋向刘备投降後臣服。尔後与孟达一同移往魏国。２２８年，於孟达为司马懿所包围之时，应司马懿之号召打开城门。\n\n",
