    "skills": [],
    "biography": "蜀国官僚。汉朝司徒邓禹之么孙。\n\n演：刘璋之部下。於刘璋向刘备投降後，追随刘备成为尚书。於刘备殁後，受诸葛亮推举为对吴之亲善使者，而与孙权会面。驳倒烧红大锅示威之孙权，缔结和谈合约。於诸葛亮第一回北伐之时辅佐赵雲。尔後参与北伐战役。\n\n史：东汉末期前往益州，服侍庞羲。於刘备平定益州後，历任广汉太守、尚书。因吴国谈和一事获孙权颇高评價，尔後孙权亦掛心其安危。於诸葛亮殁後就任车骑将军。姜维对其评價颇高。\n\n",
