    "skills": [],
    "biography": "吴国武将。\n\n演：２５７年，於魏国之诸葛诞反叛之时，奉孙綝之命派遣援军前往，却遭魏军包围而投降。留滞於吴国之家族遭孙綝杀害。２６３年，於锺会进攻蜀国之时，负责调度登州及莱州（东莱郡）之船舰。\n\n史：於魏国利城郡之郡民发动叛乱之时，成为首谋者。但败於曹丕之讨伐军，逃往吴国。尔後昇为左将军。２５７年，赶往救援於魏国发动反叛之诸葛诞，却遭魏军逮捕，受司马昭任命为安远将军。留滞吴国之家族平安无事。\n\n",
