    "skills": [],
    "biography": "吴国武将。身高八尺（１９０cm）。\n\n演：於孙策进军江东时，因杀严白虎而受孙策任用。於周泰为保护受山贼袭击之孙权而负伤时，推薦华佗为其看病。２０８年，於孙权攻击黄祖时成为甘寧副将从军。於赤壁之战中从汉中袭击曹操之阵营。尔後於合淝战线与魏军对峙。２１５年，於濡须口与徐盛一同指挥水军，但因暴风雨导致船团全毁，战亡。\n\n史：受孙策任用，讨伐山贼黄龙罗、周勃。於２０８年之黄祖讨伐战中与凌统共同於前锋率领敢死队。\n\n",
