    "biography": "吴国官僚。别名滕循。\n\n演：於孙皓时代成为司空。於杜预等人率领晋军进攻吴国之时，为孙皓所召集徵求对抗策略。\n\n史：於孙皓时代成为广州刺史。２７９年，虽受命为司空，但於就任前逢郭马发动反叛，就任广州牧前往讨伐。\n\n",
