    "biography": "吴国武将。\n\n演：於王濬率领之晋国水军进攻吴都之际，进言欲率领两万名兵力及水军迎击。率领御林军（近卫军）欲进行战鬥。但先锋之张象因部下之士兵逃走之故而投降，並因打开石头城门之故，迎击军尚未作战即遭歼灭。\n\n史：徐陵督。２７９年，郭马於交州叛变之时前往讨伐。但因晋国大军向吴国进攻之故而自武昌归返。虽率领两万兵力準备迎击，但於出征前士兵逃亡之故，作战未能实行。\n\n",
