    "biography": "车骑将军。灵帝之母董太后外甥。献帝之叔父。於演义中其女为献帝之妃，身为国舅（皇帝之舅）。\n\n演：於献帝逃離长安前往洛阳之时，击败郭汜军保护献帝。於受曹操救援而成功进入洛阳後，受封为列侯。尔後，由憎恨曹操势力增长之献帝之处，受藏有打倒曹操密令之玉带，即与王子服、吴子兰、马腾、刘备、吉平等人共同讨论计劃。但遭僕人所密告，与其女董贵妃同遭处刑。\n\n史：虽与杨奉、韩暹、张杨等人共同辅佐逃離长安之献帝，但彼此间互相对立。招致曹操之介入。\n\n",
