    "biography": "事实上，是为毁灭东汉，並导致群雄割据时代之枭雄。\n\n演：於讨伐黄巾时並无战果，凭藉贿赂十常侍保有地位。於凉州整备军力，趁何进召集诸侯欲剷除宦官之时上洛。於暗杀何进，十常侍瓦解之混乱之中保护少帝。追随最强豪傑·吕布，废立少帝等，掌握权势为所欲为。於遭袁绍及曹操等人之联合军攻击之时，强行迁都长安。因王允之连环计使其为貂蝉一事与吕布对立，遭吕布所杀。\n\n史：以拥有怪力自豪，擅长骑射。黄巾之乱後，镇压叛乱西羌族表现優異，渐进地不从中央之统治。\n\n",
