    "biography": "魏国武将。邓艾之子。\n\n演：追随邓艾，与姜维之北伐军作战。２５８年，於长城之战与姜维单挑，但不相上下。２６３年，於锺会与邓艾发起之蜀国讨伐战时，邓艾为先锋踏破阴平山岳。攻陷江油城、涪城，並於绵竹关击败诸葛瞻。虽於不久後向蜀国投降，但因战後之统治策略问题与锺会及邓艾对立。因锺会之计谋致使自身及其父一同为卫瓘所捕。其後，虽锺会为企图自立而遭讨伐，於混乱中自身亦遭卫瓘、田续所杀。\n\n史：於洛阳之兄弟亦遭处刑。\n\n",
