    "biography": "孟获之部下。第二洞之元帅。\n\n演：於诸葛亮之南蛮征伐中，遭张嶷袭击被捕。虽与阿会喃一同为诸葛亮所释放而感心服，但奉同样受释放却不服之孟获之命再度出征。於遭马岱斥责寡廉鲜耻後撤退，受孟获棒打之刑，故与阿会喃联手将孟获交於蜀军。孟获再度受释放後，误以为此回孟获已心服口服，而遭孟获之突击，与阿会喃同遭孟获所杀。\n\n史：並无记载。\n\n",
