    "biography": "晋国武将。杜畿之孙，杜恕之子。司马懿之婿。\n\n演：奉羊祜之遗言受任为镇南大将军、都督荆州诸军事。２７９年，指挥吴国讨伐军，连续攻下江陵、武昌。致使吴国投降。对於当时鼓吹慎重论之胡奋说道「若以劈竹般之气势进军，吴国将不战而降」。尔後成为「势如破竹」一语之语源。因喜读「春秋左氏传」，故自称「左传癖」。\n\n史：因其父之杜恕与司马懿对立之故，政界之参入较晚。於锺会之蜀国讨伐战时以副官参战。其著作有「春秋左氏经传集解」。不擅马术、武术。\n\n",
