    "biography": "元黄巾之武将。\n\n演：於黄巾之乱後，与周仓一同成为山贼。２００年，於关羽突破曹操之五道关卡，而欲返刘备旗下之时，与周仓一同向关羽要求盼能成为家臣。但此时仅周仓同行，其他之人则於山中等待。不久後，因欲夺偶然路过之赵雲之马，反遭讨伐。\n\n史：並无记载。\n\n",
