    "skills": [],
    "biography": "韩遂之武将。\n\n演：加入马超与韩遂为替遭曹操暗杀之马腾復仇而兴兵之军队。虽攻陷长安、潼关，却於渭水之战中战线陷入胶著状况。因中贾诩之離间计致使马超及韩遂不睦，便协议韩遂一同向曹操投降。但於协议之时为马超所闯入，最先遭到斩杀。\n\n史：东汉末，於长安以西（关中）割据之军阀之一人。２１１年，曹操故做欲西征之举，即与马超、韩遂等人一同举兵，败北。\n\n",
