    "biography": "马腾之次男。马超之弟。马铁之兄。\n\n演：追随受讨伐孙权敕令之马腾进许昌。但因马腾及黄奎召开讨伐曹操之秘密会议而事迹败露，故受曹操军包围。虽与马腾一同勇敢奋战，但於最终仍遭受擒拿处刑。得知此事之马超则向曹操挑发復仇战。\n\n史：与马腾、马铁共同上京，住邺。因其兄马超背叛曹操之故，其父弟全遭处刑。\n\n",
