    "biography": "魏国科学家。亦写为马均。\n\n演：奉魏帝曹叡之命负责营造宫殿之监督。应期能不老不死之曹叡要求，将西汉武帝於长安所建之承露盘运至洛阳。当时因烈风起故柱倒，牺牲者不在少数。\n\n史：年轻时虽放荡不羁，但於生计困苦之时改良织布機。使其发明之才能得以激发。於效命魏国後亦有多项发明，献给曹叡指南车、水车、及具機械装置之人偶。並著手於投石车之改良。晋国之傅玄评其为「天下之名巧也」。\n\n",
