    "biography": "黄巾之渠帅（头目）中一人。\n\n演：並无记载。\n\n史：１８４年，於张角举兵时，与南阳之张曼成、博陵之张牛角等人同时举兵，统率潁川之反叛军。虽於长社包围皇甫嵩所率领之官军，但因曹操、孙坚、朱[0xFA][0x45]军之奇袭而战败。\n\n",
