    "biography": "魏国之天水太守。\n\n演：２２７年，於诸葛亮率领蜀国之北伐军来袭时，採纳姜维之计击退蜀军。但因诸葛亮之计谋，使姜维降於蜀军後无法做彻底抵抗，与而夏侯楙一同抗投靠羌族。\n\n史：与姜维、梁绪、尹赏、梁虔等人於领地内巡察之时，接获诸葛亮北伐军来袭通报。於聽闻邻近诸郡已响应蜀军之风声，遽变得无法信任姜维等人，故於夜半独自逃亡。因姜维等人追赶而至亦紧闭城门，无路可去之姜维等人故向蜀军投降。\n\n",
