    "biography": "蜀国武将。马良之弟。\n\n演：於征伐南蛮时提倡「攻下南蛮人之心」，得诸葛亮之信任。自南蛮返国後，因谋反谣言致使司马懿失势，完成北伐之準备。２２８年，虽自願负责街亭之守备，但违反诸葛亮命令故惨败於魏国之张郃。因此场败仗，导致蜀军攻略长安陷入绝望，受诸葛亮之命遭处刑（挥泪斩马谡）。刘备於临终之际，曾留下「不可重用马谡」之遗言予诸葛亮。\n\n史：防守街亭理应由经验豐富之魏延或吴懿适才适任。於战败後，认同马谡逃亡之向朗失势。\n\n",
