    "biography": "马超之堂兄弟。马腾兄之子。\n\n演：於与马腾上京时同行，虽曹操军袭击但平安脱逃。向马超传达马腾父子死讯。马超则为向曹操挑发復仇战而从军，转战各地。最终与马超一同成为刘备之部下。尔後，参与诸葛亮之远征南蛮，仅以一招即斩杀忙牙长等，表现優秀。於魏严因北伐作战问题而欲反抗诸葛亮之时，依从诸葛亮之意，成为魏延副将而监视之。於魏延背叛之时，即遵从诸葛亮之遗计杀魏延，继承魏延之爵位。\n\n史：於杀魏延前，並无成为魏延副将之记载。\n\n",
