    "biography": "吴国潘璋之部下。\n\n演：２１９年，於吴国进攻荆州之时擒拿关羽父子。因此功绩受赐关羽之坐骑·赤兔马，但赤兔马完全拒食，於不久後饿死。２２２年，於刘备为报关羽之仇而进军荆州之时，前往迎击。於初战击退黄忠，且讨伐主将潘璋、追击关兴，表现傑出，却遭降将糜芳及傅士仁於就寝之际割下首级，供奉於关羽灵前。\n\n史：除关羽父子外，亦虏获赵累。並无事後之记载。\n\n",
