    "biography": "蜀国武将。别名狐笃。\n\n演：参与诸葛亮之南蛮征伐。虽连续战鬥表现傑出，但与孟获之妻·祝融夫人战鬥时，与张嶷同遭祝融夫人逮捕。尔後，参与诸葛亮之北伐。\n\n史：於夷陵刘备败於陆逊後，奉巴西太守阎芝之命前往救援，得刘备赞扬其曰「失之黄权，却得马忠」。尔後，於诸葛亮出征中之时，一方辅佐蒋琬、费禕等人执行政务，另一方则发挥羌族及南蛮等统治外族边境之本领。知晓體恤他人，为人心胸宽大，受異民族之敬爱。尔後高昇为镇南将军。\n\n",
