    "biography": "马腾之长男。马休、马铁之兄。蜀国五虎将军中一人。\n\n演：於其父及其弟为曹操所谋杀後，与马腾之义兄弟韩遂一同挑发復仇战。连破长安、潼关，於渭水与曹操对阵，但却因中曹操参谋·贾诩之離间计，致使得与韩遂反目而大败。虽夺取冀城並持续抵抗，但失去因中杨阜等之计谋而遭逐出之其妻。尔後，虽於张鲁之旗下与刘备军张飞进行激战，但因李恢之说服加入刘备阵营。另取别名「西凉锦马超」。\n\n史：虽因警戒曹操征伐汉中之动作而兴兵，败北。因此次叛乱，致使马腾、马休、马铁等人遭处刑。\n\n",
