    "biography": "凉州军阀之首领之一。马超、马休、马铁之父。\n\n演：为响应曹操讨伐董卓号召中之一位诸侯。虽参与董承暗杀曹操之计劃，但因事迹败露而逃往西凉。於赤壁之战後，曹操计劃杀马腾以绝後顾之忧。马腾明知曹操计谋却依然上京，与黄奎共谋意图反讨曹操，失败。同行之马休、马铁亦一同被讨。\n\n史：未加入董卓讨伐军，与韩遂等人共同於朝廷中保持独立之势力。上京後成为卫尉，但却因马超叛乱之故遭连座处刑。\n\n",
