    "biography": "蜀国武将。镇守江油关。\n\n演：２６３年，由魏国锺会与邓艾发起蜀国讨伐军时，汉中虽已攻陷，但因仅依赖前线之姜维故疏於防备。对由黄皓所掌之蜀国未来感悲观，故毫无做为遭其妻李氏斥责。不久後，穿越阴平山岳之邓艾军来袭，故顺势投降並向邓艾军指示路径。为此而感羞愧不已之李氏自杀。\n\n史：蜀国守备队长。仅有向穿越阴平逼近江油之邓艾军投降之记录。\n\n",
