    "biography": "蜀国幕僚。马谡之兄。眉色白，人称「白眉」。\n\n演：於刘备攻下南荆州後，受伊籍之推薦服侍刘备。诸葛亮前往蜀国之时，奉命担任防守荆州关羽之辅佐。於关羽进攻襄阳时从军，负伤之关羽接受华佗治疗之时，担任其下棋之对手。於荆州为吴国之吕蒙所夺之後，与伊籍一同前往成都请求援军，但於期间中关羽已战败身亡。夷陵之战之时追随刘备，败北。於诸葛亮征伐南蛮之时死亡。\n\n史：与诸葛亮深交，待其识如己兄。於夷陵之战时，虽获武陵之異民族协助表现傑出，战亡。\n\n",
