    "biography": "吴国官僚。\n\n演：２６４年，於孙休病故後，以嫡男之孙[0xFA][0x44]尚年少为由，主张由孙皓即位。於孙皓即位後成为宰相，却因告诫孙皓施行暴政而惹怒孙皓被杀。\n\n史：於乌程官员时代，与孙皓有深交。於孙皓即位後成为右丞相，负责守备巴丘。２７１年，於孙皓使民众遭受莫大牺牲，一意孤行巡幸各地时，与丁奉、留平商量返回都城一事。故激怒孙皓被迫饮毒酒，自杀。\n\n",
