    "biography": "蜀国官僚。\n\n演：於诸葛亮征伐南蛮及北伐之时从军，与董厥一同辅佐诸葛亮。２５６年，阻止於洮水之战获勝，欲继续进军之姜维但遭拒，姜维最後败於邓艾。２６３年，蜀灭亡後，谯周、张绍、郤正等人一同追随刘禅迁往洛阳。\n\n史：２５１年，成为使者前往吴国，诸葛恪评其为「才识不及预，而雅性超之」。蜀国末期，与诸葛瞻、董厥等人担当政务，与黄皓对立。於蜀国灭亡後，与董厥同往刘禅之洛阳行。\n\n",
