    "biography": "桂阳太守·赵範之兄嫂。美人。\n\n演：於赵雲奉刘备之命进攻桂阳之时，赵範向赵雲投降。二人立誓结为义兄弟。此时，赵範劝赵雲迎娶未亡人，貌美之兄嫂·樊氏为妻。但赵雲怕伤及刘备军之风评，故拒绝迎娶义兄弟兄嫂为妻。尔後刘备虽再次为赵雲及樊氏媒妁，但赵雲依然不允，刘备赞其为「男人中的男人」。\n\n史：赵雲因担心赵範並不心服於刘备故拒绝婚事。尔後正如同赵雲所料，赵範逃亡。\n\n",
