    "biography": "吴国武将。\n\n演：孙策殁後受孙权召集。於２０８年讨伐黄祖之时擒获苏飞。尔後，参加赤壁之战、南郡攻略战、合淝攻防战。２１９年，於吕蒙之指挥下进攻荆州，並擒获关羽父子。夷陵之战做先锋迎击蜀军。虽於初战击退黄忠，但因遇关羽亡灵，受关兴报仇时所杀。\n\n史：於夷陵之战後亦屡建战功，击退进攻南郡之夏侯尚而成为右将军。虽其部下抢夺财物等之不法行为甚多，但以战功赎罪。\n\n",
