    "biography": "董卓之武将。\n\n演：随董卓前往洛阳，防守虎牢关。於董卓为王允等人讨伐之後，与李傕、郭汜等人共同攻击长安。自王允一派手中夺回献帝，成为右将军。尔後击退进攻长安之马腾及韩遂。当时，因放过同乡之韩遂一事遭李傕之外甥李别密告，故遭李傕所杀。\n\n史：董卓死後，与李蒙、王方等人一同协助李傕佔领长安。迎击与侍中之马宇等人联手之马腾及韩遂，讨伐了马宇。当时，因与韩遂之会谈内容遭李傕外甥李利之密告，故遭李傕所杀。\n\n",
