    "biography": "扬州刺史·刘繇之武将。\n\n演：迎击企图侵略江东之孙策。因见同僚于糜遭孙策所捉故袭击孙策，却遭孙策一声大喝下落马，伤头致死。\n\n史：与于糜一同驻紮於扬子江沿岸之横江津，企图防止袁术与孙策进军江东，败退。虽曾一时夺回遭孙策所夺之据点，於孙策返回後又遭夺取。\n\n",
