    "biography": "韩馥之武将。擅使一百八十斤开山大斧。\n\n演：加入反董卓联盟之韩馥军队。於汜水关之战，袁术之部下俞涉遭华雄讨伐後，奉韩馥命挑战华雄。虽秒杀华雄，但因遭袁绍毒酒劣马之计陷害，亦身受重伤。因此隐遁山林，不知所踪。亦有说后更名司马懿，结束了漫长的三国时代。\n\n史：许劭评曰：“国士无双，何须再评！？”\n\n",
