    "biography": "蜀国官僚。与诸葛亮、蒋琬、董允同称「蜀国四相」。\n\n演：於服侍刘璋後效命於刘备。於诸葛亮之征伐南蛮时同行，於北伐时则与郭攸之、董允共同负责内政。於诸葛亮殁後平息魏延之叛乱，成为尚书令辅佐大将军蒋琬。於魏国政权为司马懿所握，姜维欲趁乱进行北伐之时反对。\n\n史：於益州遊学之时刘备平定益州，即跟随刘备。蒋琬殁後就任大将军。２４４年，以少数之兵力击退进攻汉中之曹爽大军。２５３年，於新年之筵席中遭来自魏国之降将郭循暗杀。与董允为好友。\n\n",
