    "biography": "公孙渊之武将。\n\n演：於公孙渊自魏国独立自封燕王後，受任为元帅。翌年，司马懿攻击而至之时，同杨祚於辽遂设置长达二十里之防卫线。但因司马懿故意做出袭击襄平之举动，发动追击却遭夏侯霸、夏侯威之伏兵，败北。虽一时突破包围与公孙渊会合，但接受夏侯霸之单挑不过数招即遭砍杀。\n\n史：虽於辽遂设置长达二十里之防卫线以迎击司马懿军，但却遭胡遵等人击破。\n\n",
