    "biography": "蜀国官僚。原为刘璋之部下。\n\n演：於刘璋向刘备投降後，即为刘备效命。於成为汉中王之刘备将五虎将军头衔封於关羽之时，说服不满与老将黄忠被视为同格之关羽，使其接受册封。尔後於诸葛亮北伐时，与郤正一同受命为秘书，滞留成都。\n\n史：刘璋部下，绵竹之令。於刘备攻至之时率先臣服。因反对刘备即位皇帝故贬至永昌，但为诸葛亮所重用，亦从军於征伐南蛮。蒋琬掌握政权後，就任谏议大夫。\n\n",
