    "biography": "刘备之第二夫人（第一夫人为甘氏）。糜竺之妹。\n\n演：於刘备与吕布之争鬥中，与甘氏同遭吕布所掳。於徐州独立之刘备败於曹操後，由关羽陪同投降曹操。尔後，於关羽护卫下突破曹操之五关，终能与刘备再度相逢。２０８年，於长阪坡受到曹操军之袭击、负伤带著年幼刘禅逃走。尔後将刘禅交付前来救援之赵雲，自身则投井自尽。尔後受追封为皇后。\n\n史：长阪坡之战中为赵雲所拯救之人为甘氏。於蜀之妃子传並无记述，亦无受追封为皇后之记载。\n\n",
