    "biography": "徐州之豪商。刘备之幕僚。糜芳之兄长。将其妹嫁予刘备。\n\n演：虽服侍於陶谦，但於陶谦死後，使其妹嫁予刘备。尔後，与孙乾一同为流浪各地之刘备，辅佐进行政治及外交。而於刘备进攻益州之时，则辅佐留守於荆州之关羽、平定益州後，受任命为安汉将军。２２０年，於曹丕篡汉登基成为魏帝後，与诸葛亮一同劝说刘备登基即位。\n\n史：於刘备平定益州後，论席次而言，所受厚遇甚於诸葛亮。尔後於关羽战亡後，原因为其弟·糜芳之背叛所致甚为羞愧，不久後病故。\n\n",
