    "biography": "糜竺之弟。与兄长一同服侍於刘备。\n\n演：於徐州与吕布及曹操交战，徐州沦陷後，亦同兄长追随刘备。於刘备进入益州後，辅佐留滞荆州之关羽。而於关羽欲进攻襄阳之前，因失火损失物资，故与傅士仁一同遭受处罚。不久後，遭受吴国吕蒙之攻击，同傅士仁投降。２２２年，於刘备进攻荆州之时，手提擒拿关羽之马忠首级，欲返刘备阵营求饶，未受原谅反遭关兴所斩。\n\n史：於夷陵之战後亦仕官於孙权，２２３年，与贺齐一同讨伐反叛而逃亡魏国之晋宗。\n\n",
