    "biography": "魏之武将。正史上为费曜。\n\n演：２２８年，於诸葛亮第二回北伐攻击陈仓之时，受曹真指挥巩固要塞。此时，自投诚於蜀之姜维处，传来对魏做内应之密函，而代信任姜维之曹直出征。陷於姜维之计遭受重围，於拒绝投降後，自杀。\n\n史：２２０年，於张进於酒泉发动反乱後、与张既、夏侯儒共同前往镇压。２２８年，於陈仓成功地防禦诸葛亮之攻击。２３１年，於诸葛亮向祁山出征时、於司马懿之指挥下，与张既、戴陵、郭淮一同参战但败退。\n\n",
