    "biography": "蜀之武将。\n\n演：为替关羽復仇，而成为进攻荆州之刘备之副将。於宜都与吴班、张南共同进行夜袭，击退孙桓。夏季，士兵为酷热所苦之时，进言理应将本营移往树阴处。不料却遭陆逊火攻，导致蜀军溃灭。於熊熊大火当中，与吴班、张南等人奋战，但前後皆为吴军所围，与张南一同战亡。\n\n史：於刘备平定益州之时从军。於刘备之伐吴战之时成为总指挥官，虽与吴班共同击破李異，却惨败於陆逊，遭潘璋手下所斩。\n\n",
