    "biography": "魏之官僚。傅介子之子。傅巽之外甥。\n\n演：代理曹芳成为尚书。於孙权殁後欲趁隙攻吴之时，无视司马师之谏言，致使魏军败退。於毌丘俭反乱时，加入司马师所指挥之讨伐军，策劃由乐嘉、项城、寿春三方进军之作战，受採用。\n\n史：由陈群遴选而仕官。通晓礼法及官制。於曹爽掌握大权之时，受何晏等弹劾而遭免职，但於司马懿掌权後重返。与何曾、陈泰、荀顗、锺毓等人深交。殁後，受追封为太常。\n\n",
