    "biography": "关羽之武将。\n\n演：与关羽一同守护荆州。关羽準备进攻襄阳之前夕，因失火致使物资毁损。於受到处罚後，被命留守公安，故憎恨关羽。不久後，吴军攻陷荆州，受虞翻说服不战而降，亦使僚友糜芳一同投降。尔後，於刘备为替关羽復仇进攻荆州後，提著擒拿关羽之马忠首级，欲与糜芳一同回刘备阵营但未受原谅，故遭关兴所斩。\n\n史：与关羽之感情向来不睦。\n\n",
