    "biography": "蜀之武将。傅彤之子。使用四角铁简（铁扇）。\n\n演：与蒋舒同受姜维赏识，参加姜维之北伐。於长城之战讨伐李鹏、王真。尔後守卫阳平关。２６３年，迎击钟会率领之蜀讨伐军但败北。虽返回阳平关，同僚之蒋舒却早已投降。於乱战中大喊「死後亦为蜀鬼」，自杀。\n\n史：傅彤之继承者，成为关中之都督。於钟会攻至之时，於阳平关进行笼城。但因同僚之蒋舒投降故使军队混乱，战败而死。\n\n",
