    "biography": "刘表幕僚。尔後服侍於曹操。傅嘏之伯父。\n\n演：於刘表死後，见曹操有意进攻荆州动向，对刘表之继承人刘琮进言理应投降。此事令曹操对其有所好评，故任用。\n\n史：容貌端正、博学。评價庞统为「不完全之英雄」、裴潜「品行清风亮节名扬四方」、魏讽「谋反为早晚之事」等，且一言命中。对曹操就任魏公，曹丕就任皇帝有所贡献。於曹丕时代成为侍中尚书。\n\n",
