    "skills": [],
    "biography": "魏之武将。文钦之次男。文虎之兄。本名为文淑（正史中则为俶）。幼名阿鸯，文鸯为其通称。身高八尺。使用钢鞭。其之奋发表现可称媲美於赵雲之猛将。\n\n演：与文钦一同加入毌丘俭之反乱，突击司马师之阵营。受邓艾迎击後，单骑脱逃亡命至吴。於诸葛诞发动反乱後，与文钦一同率领吴之一军前往救援。文钦却为感情不睦之诸葛诞所弑，尔後同其弟文虎投降於魏军。\n\n史：於晋代因镇压凉州之異民族声名大噪，却为司马炎所厌恶，遭罢免。尔後被冠上反叛罪名，遭受处刑。\n\n",
