    "biography": "魏之扬州刺史。文稷之子。文鸯、文虎之父。\n\n演：愤慨司马师废立曹芳，故与毌丘俭共同发起反乱。本欲突击司马师之本营却因迷路而败北，後投靠吴之孙峻。当时，並未察觉欲通知司马师病情而至之尹大目之本意，而击退之。尔後於诸葛诞发动叛乱，以吴之一将之身前往救援，但因笼城策略与诸葛诞对立而遭斩杀。\n\n史：自於魏之时以来，即与诸葛诞不睦。於吴之时受孙峻厚待礼遇，受命为镇北大将军，幽州牧等官职。但於吴之时亦与朱異等人感情不睦。\n\n",
