    "skills": [],
    "biography": "刘表之武将。尔後仕官於曹操。\n\n演：於宴席上聽从企图暗杀刘备之蔡瑁，使担任刘备护卫之赵雲与王威，一同離开刘备身旁。於刘琮决心向曹操投降时，与欲将襄阳让予刘备之魏延交战。於曹操入城荆州之时，以未能保卫国家为耻並未出席，欲受曹操信任。尔後，参与长阪城之战、赤壁之战等战役。２２４年，曹丕进攻濡须，大败於徐盛之时救出曹丕。\n\n史：成为魏将後便长年驻紮於江夏，防禦蜀吴来击。於寻口击退关羽，於石阳则击退孙权。\n\n",
