    "biography": "曹操之侧室。曹丕、彰、植、熊之母。原为歌姬。\n\n演：因曹操之正室膝下无子之故，於曹操成为魏王後，即受立成为正室。於曹操殁後，因继位问题，於曹植将遭曹丕所杀之际，为曹植求情，使其免於一死。\n\n史：於２０岁时成为曹操侧室。於曹操与正室丁氏離缘後，即成为正室。因其人品谦虚、节俭家。且具获曹操死亡之误报时亦不为动摇之冷静性格。相当礼遇与曹操離缘之丁氏、养育所有丧母之曹操之兒女们。曹丕即位後成为皇太后，曹叡即位後则成为太皇太后。\n\n",
