    "biography": "魏之武将。庞德四子中之一人。\n\n演：於庞德与关羽面临最後决战前，与庞德泪别。２６３年，钟会及邓艾发起蜀讨伐军，其以一员大将之身份屈居於钟会之指挥下。\n\n史：拥有与庞德同样之风範，非常勇敢。立下镇压诸葛诞叛乱等功绩。２６３年，参入钟会之蜀讨伐军。与胡烈、田续等人一同追击姜维。於蜀投降後，为讨父仇而灭关羽一族，成功地达成復仇。\n\n",
