    "biography": "南蛮王·孟获副将。骑白鹿毛之马，使用剃刀。\n\n演：於金环三结被杀，董荼那、阿会喃遭蜀军擒拿之时，奉盛怒之孟获之命，前往攻击蜀军。但因追击诈败而逃之王平而遭伏兵攻击，败北。尔後，为确保粮道前往夹山峪，遭马岱以一招受斩。\n\n史：並无记载。\n\n",
