    "biography": "袁绍之幕僚。\n\n演：於反董卓联合解散後，对为调度兵粮而苦恼之袁绍，进言攻夺食粮豐饶之冀州。於袁绍追放韩馥进邺之後，担任冀州之行政。与於官渡之战时，提倡慎重论之田豐对立。而於果真如同田豐所指责，袁绍军战败之後，则向袁绍谎称田豐指责袁绍不是，致使田豐被杀。於袁绍殁後与审配共同拥立袁尚。因对立之袁谭派之策略被唤至袁谭之阵中，被迫书写向袁尚要求援军之书信，拒绝後遇害。\n\n史：起初亦与支持袁尚之审配感情不睦。\n\n",
