    "biography": "刘璋之武将。其女为刘循之妻。尔後效命於刘备。\n\n演：成为巴西太守，防备汉中张鲁之南下。２１１年，当张鲁做出南下之举动後，便向刘璋急报。於刘璋投降於刘备之後，侍奉刘备。\n\n史：与刘璋为旧识。因将刘璋之子自危难中救出而受厚遇，成为巴西太守。但因沉醉於权力而变得横暴，而与刘璋关係恶化。为防备战乱集结私兵，而遭刘璋疑其有叛乱意图，为此激怒。其一时当真兴起反叛之念头，但受程畿之谏言，向刘璋谢罪。\n\n",
