    "biography": "於「花关索传」中登场之女性。为鲍家莊鲍员外之千金。\n\n以拔群之武艺及美貌自豪，为众多男性求婚皆不与理睬。南山头目·廉康包围住鲍家莊欲求婚时，亲自挥舞长枪将其驱逐。数日後，虽有其他武者前来挑战，败北。其人为关索，二人因意气投合而成婚。虽为架空之人物，但於四川省仍现存有鲍三娘墓，並记述夫妇共同守护葭萌关一事。於其他，亦流传如夫妇二人曾共同参与诸葛亮之南蛮征伐等轶事。\n\n演：並无记载。\n\n史：並无记载。\n\n",
