    "biography": "东汉济北之相。\n\n演：於董卓掌握大权、进行暴政统治时，向袁绍及王允进言打倒董卓。於曹操发出打倒董卓之号令後，即参入反董卓联合。於反董卓联合解散後，於与曹操一同参加青州之黄巾黨讨伐之时，於寿阳战亡。\n\n史：於参加反董卓联合後，於其他诸候皆服从於袁绍之时，即视曹操为英雄，与其深交。１９２年，为接掌於青州之黄巾黨交战中战亡之兖州刺史·刘岱之後任，迎进曹操。但於战场视察中时，与黄巾黨进行肉搏战，为拯救曹操战亡。\n\n",
