    "biography": "刘璋之幕僚。尔後效命刘备。\n\n演：与张松、孟达等人不看好刘璋，策劃将益州委託於刘备。与庞统共同担任刘备之益州平定战之参谋。於刘备平定益州後成为蜀郡太守。与曹操之汉中攻防战中亦以参谋之身份表现卓越。传授黄忠计略，继而讨伐夏侯渊。对其智谋，诸葛亮亦予以颇高评價，於刘备强行对夷陵出兵时，诸葛亮感叹「若法正仍然在世，或许就不需出兵了吧」。\n\n史：虽有小仇必恨必报等缺点，但因其智谋受赏识，而为诸葛亮所容忍。\n\n",
