    "biography": "马超心腹。尔後服侍於张鲁、曹操。\n\n演：於马腾遭曹操暗杀後，追随马超一同挑起復仇战。因马超与韩遂感情不睦遭败北後，马超、马岱一起投靠汉中张鲁。於马超等人投降於刘备之後，依旧留於张鲁旗下，与攻击汉中之曹操军抗战。人称其勇猛，战後受曹操重用。於樊城遭关羽包围时，与于禁一同前往救援。於于禁投降後依然对战到底，遭周仓逮捕，为关羽所斩。\n\n史：於与马超及钟繇一同讨伐郭援之时，斩杀郭援。於樊城，以箭射中关羽额头，被称为白马将军而叫人恐惧。\n\n",
