    "biography": "南蛮八纳洞之洞主。骑乘白象，驱使豹、狼、毒蛇、蝎子等猛兽。亦使用引起暴风之妖术。武器为两把大刀。\n\n演：於诸葛亮与孟获之鬥争中，以孟获之援军身份前来支援。曾用妖术擾乱赵雲、魏延之部队，再以猛兽做突击大破其军。但其後遭亲自出征之诸葛亮大破其妖术，形势逆转。遭人工巨兽「木兽」之火燄放射，使得猛兽们做鸟兽散，於混战中受讨致死。\n\n史：並无记载。\n\n",
