    "biography": "吴之幕僚。\n\n演：於赤壁之战前，与前来与孙权结盟之诸葛亮进行辩论战，惨遭败北。於孙权攻击关羽防守之荆州之际，进言使曹仁与关羽交战，再趁隙抢夺荆州之计策。此计成功，使荆州重返孙权之手。於夷陵之战时，反对陆逊就任指挥官。\n\n史：２１０年、成为交州刺史，讨伐苍梧太守吴巨。使士燮降服，为吴之进军南方建立桥头堡。孙权即位後就任骠骑将军、西陵都督。於陆逊殁後，成为丞相。\n\n",
