    "biography": "曹操之幕僚。\n\n演：受刘晔之推举，与吕虔共同效命於曹操。尔後推举毛玠。曹仁於樊城遭受关羽包围之时，叱责受水攻而欲逃走之曹仁，尔後击退关羽。２３４年，吴兵分三路攻魏，与曹叡一同朝巢湖出征，以夜袭及火攻大破吴军。\n\n史：与袁绍之对战中，成为袁绍本籍地汝南之太守，防範了袁绍之後方搅乱。曹丕即位後，成对吴战线之重镇。２２５年，於曹丕攻吴之际，视破孙韶之夜袭计劃，减低了受害。於其後，高昇至太尉。\n\n",
