    "biography": "曹操之幕僚。\n\n演：受满宠及吕虔之推举，为曹操所招揽。於曹操拥护献帝之时，成为税务监督官之典农中郎将。於徐州讨伐刘备之时，见旗帜遭强风吹断，故察觉刘备军之夜袭。於赤壁之战时，於蔡瑁与张允被杀後，与于禁一同成为水军都督。\n\n史：与崔琰共同担任官吏选拔。虽遭受人选清廉公明但过於严苛之陈情，但受曹操支持拥护。２１６年，因脱口说出对崔琰之处刑心感不满而遭起诉下狱。幸得桓阶、和洽之辩护免於一死，但遭革职。\n\n",
