    "biography": "南中之土豪（演义中为南蛮王）。祝融之夫婿。孟優之兄。\n\n演：刘备殁後，担任司马懿向曹丕献策之五路攻蜀作战中之一角，进而攻打蜀国。２２５年、与雍闓联手兴兵攻蜀，与诸葛亮所率领之南蛮征伐军交战。但败於诸葛亮之临機计略。虽受逮六回皆不臣服受释放，但於第七回受捕後终告心服（七擒七纵）。受委任进行自治，尔後立誓不叛蜀国。\n\n史：於２２３年刘备殁後，於蜀之南方相继发生反叛，孟获为其中一角。於孟获臣服後，南蛮依然反叛不断，李恢、马忠等人为平定而疲於奔走。\n\n",
