    "biography": "刘璋之武将。尔後服侍刘备、曹丕。本名子庆。\n\n演：与张松、法正合力，策劃驱逐刘璋，迎刘备入蜀成为蜀主之计谋。於刘备入蜀後，同霍峻共守葭萌关。於曹操撤離汉中时，与刘封、王平等人共夺上庸。却因未拯救败於魏吴之关羽，而遭刘备怨恨，逃亡至魏。受魏帝·曹丕宠爱，但於曹丕殁後，於魏亦遭到孤立。以诸葛亮之北伐为契機，图谋重返蜀国，但为司马懿所杀。\n\n史：於刘备入蜀之际守护江陵，尔後成为宜都太守。与刘封、申仪感情不睦。\n\n",
