    "biography": "刘璋之武将。白水都督。\n\n演：为阻止张鲁之攻击，於刘备进入益州之时，与高沛一同就任涪水关（白水关）之防守。於受刘备告知，为防卫荆州而返国一事後，与高沛共谋企图暗杀刘备而送行。但为庞统察知，而遭刘封及关平处刑。\n\n史：庞统评其为刘璋军之名将。於欲支援刘备之张松被杀之後，奉刘璋之命不可向刘备告知此事。此事令刘备愤怒，故被传唤遭斩杀\n\n",
