    "biography": "蜀之幕僚。\n\n演：参与诸葛亮之北伐。忧心因接连出兵，造成之兵力耗损。在２３１年之北伐，进言士兵应採轮番制。诸葛亮殁於五丈原之後，成为丞相代理指挥撤退，聽从诸葛亮之遗策讨伐魏延。於返回成都後，成为中军师，但对於经历尚浅之蒋琬成为诸葛亮继承者一事感不满，诉诸於费禕。因遭人通报刘禅，故遭流放至汉嘉郡後，自杀。\n\n史：因其性格偏狭，故与刘巴、魏延对立。虽受诸葛亮赏识其才华，但性格狷狭，故遭排除成为继承者。\n\n",
