    "biography": "魏之金城太守。\n\n演：２６３年，参加钟会及邓艾所发起之蜀讨伐战。於邓艾之指挥下与姜维对战，烧毁於甘松之蜀军阵地。\n\n史：於晋代成为凉州刺史，斩杀统治敦煌之令狐宏。２７８年，与进攻凉州而至之鲜卑之若罗拔能交战，战亡。\n\n",
