    "biography": "晋之武将。其姊为司马师之妻。其妻为夏侯霸之女。\n\n演：与吴之陆抗对战，驻紮於襄阳。彼此认同对方之才华，於陆抗生病之时赠药。於陆抗遭孙皓疑与晋勾结而遭贬官後，呈表上奏现为伐吴之好时機。但因贾充等人反对，错失出兵佳機。不久後生病，於推薦杜预为继承者後死亡。领民感叹其殁，建立庙宇，尔後人称「堕泪碑」。\n\n史：２７２年，为解救降服晋之步阐而前至西陵救援，但遭陆抗阻止。为讨伐吴，命令王濬建造军船。使用於杜预讨伐吴国之时。\n\n",
