    "biography": "袁术之幕僚。於演义中为杨大将。\n\n演：於袁术欲讨伐宣告独立之孙策时，进言应先讨伐刘备。当时，为不使吕布协助刘备，献策赠与吕布食粮。但袁术却因无法拉拢吕布，而败於刘备。尔後，於曹操向其领地内侵略之时，劝袁术渡淮水逃亡，自身亦同行。\n\n史：於袁术殁後，与张勋一同前住投靠孙策。但於途中遭刘勋埋伏，成为俘虏。\n\n",
