    "biography": "张鲁之武将。\n\n演：於曹操军进攻汉中之时，与杨任一同防守阳平关。展开夜袭击退曹操军先锋之夏侯渊及张郃。尔後与杨任联手，袭击前来侦察张卫阵地之曹操，但遭许褚阻止。尔後无顾於杨任之制止，於雾中出征後遭张郃讨伐。\n\n史：於渭水之战败北後，援助进攻陇西之马超。於曹操攻陷汉中後，与张卫共同於阳平关进行防战。\n\n",
