    "biography": "东汉太尉杨彪之子。曹操之幕僚。\n\n演：禰衡评论其为，優秀人物仅孔融及杨修而已。於刘璋之部下张松因激怒曹操，而险遭杀害之时为其求饶。尔後虽成为曹植之监护人，但为讨曹操欢心而製作模範解答集误导曹植，而遭曹操憎恨。於与刘备进行汉中攻防战时，将曹操随口而出之「鸡肋」一词，解释为撤退命令而擅自进行撤退準备，故遭斩首。\n\n史：於曹操自汉中撤退後遭处刑。亦有因杨修为袁术外甥，故遭曹操疏远之说。\n\n",
