    "biography": "韩遂之武将。\n\n演：追随为替马腾復仇而举兵之马超及韩遂，接连击破长安及潼关。於渭水之战时，因中贾诩之離间计，致使马超与韩遂决裂後，则以韩遂使者之身份拜访曹操阵营，传达投降之意。战後，与侯选共同受封为列侯，担任渭口之防守。\n\n史：东汉末期，割据长安以西（关中）之军阀。派遣孔桂为使者前往侦察曹操之状况。渭水之战败北後，亡命安定。遭夏侯渊所包围，降服。於曹丕时代成为讨寇将军，颇受重用。\n\n",
