    "skills": [],
    "biography": "张鲁之幕僚。\n\n演：杨柏之兄。於刘璋提议若与刘备对战即让出２０个州予张鲁时，建议张鲁允诺此要求。但於已收受自刘备使者孙乾所赠之金银财宝後，通报以援军前往刘璋处之马超倒戈，致使马超及张鲁决裂。於曹操进攻汉中，庞德进行防守战之时，亦因收受曹操军贿赂，故而刻意处处阻挠扯庞德。最後因欺骗张鲁将其交付曹操军，贪求自身安泰之故，为曹操所杀。\n\n史：並无记载。\n\n",
