    "skills": [],
    "biography": "张鲁之武将。\n\n演：於曹操军进攻汉中之时，与杨昂一同於阳平关展开防守战。初战时以夜袭攻击曹操军前锋·夏侯渊及张郃，获得勝利。於曹操外出巡察之时，与杨昂合力袭击曹操，但遭许褚击退。於大雾中，与迷失於杨昂阵势中之夏侯渊对阵，最後因受张郃自背後突击而败退。此事激怒张鲁，虽再度出征，却演变为同夏侯渊单挑之局势。於交手三十餘回合後穷追佯装败逃之夏侯渊却反遭讨伐。\n\n史：於阳平关与曹操军对战，被杀。\n\n",
