    "skills": [],
    "biography": "公孙渊之武将。\n\n演：２３７年，於公孙渊自封燕王，並自魏国独立之後受命为先锋，同卑衍驻紮於辽遂。挖掘长达二十多里之壕沟及栅栏，以备对抗魏军之来袭。但因来袭之司马懿无视辽遂直捣襄平，故发动追击。却遭夏侯霸及夏侯威之伏兵而败退。\n\n史：辽遂於首山为司马懿所败，受包围於襄平。因辽水决堤而遭孤立，粮食亦耗尽，故而投降。\n\n",
