    "biography": "晋国武将。杨暨之子。杨潭、杨歆之父。\n\n演：並无记载。\n\n史：荆州刺史。２７２年，於吴国之步阐向晋朝投降後，同羊祜前往救援步阐所治理之西陵。但因吴国所派之陆抗使堤防决堤，阻挠羊祜进军，故单独与吴军对战。於屈居劣势之下对阵数个月後，指示趁入夜撤退。但遭察知此事之陆抗夜袭，大吃败仗。\n\n",
