    "biography": "张鲁之武将。正史中之名为杨白。\n\n演：杨松之弟。败於曹操军之马超投靠张鲁之时，阻止张鲁将女兒嫁给马超。因而与马超反目成仇。於马超以援军身份，前往刘璋之所在地与刘备对战时，以监视人之身份同行。与魏延对战，败北。尔後，为决心归顺刘备军之马超所唤出，遭砍杀。\n\n史：於马超归顺张鲁後，因畏惧马超之能力而企图杀害。察知此事之马超，即自武都逃入氐族居住地，向刘备军投降。\n\n",
