    "biography": "李傕之武将。东汉之骑都尉。\n\n演：１９５年，李傕发动反叛，却战败而逃。护卫脱離长安之献帝进入洛阳。翌年，当曹操拥护献帝，欲迁都许昌之时，协助韩暹向曹操挑战。却因部下徐晃向曹操军倒戈之故败北，投靠袁术。１９７年，加入袁术之吕布讨伐军。受陈珪之邀请与韩暹一同向吕布军倒戈。尔後因不断四处掠夺之故，遭刘备讨伐。\n\n史：於曹操拥立献帝後，同韩暹出走。於徐州及扬州流窜，为恶破壞而遭刘备诱杀。\n\n",
