    "biography": "银冶洞二十一洞之洞主。\n\n演：於孟获接连败於由诸葛亮所率领之蜀国南征军之时，与诸葛亮暗中协定。率领其子五人及三万精兵支援孟获军，於欢迎之筵席上表演美女之剑舞。生擒失之大意之孟获及朵思大王，交付於诸葛亮。\n\n史：並无记载。\n\n",
