    "biography": "刘备之武将。\n\n演：服侍刘璋。於刘备进攻蜀国之时，与吴懿、吴兰等人一同援救雒城之张任。庞统战死落凤坡等，致使刘备军倍嚐艰辛，但受到自荆州赶至之诸葛亮等人之救援後，情势逆转。与吴兰一同遭逮後降服。於刘备平定蜀国後，与张飞共同守备巴西郡。於与曹操进行汉中攻防战时，曾用伏兵击溃张郃一回。但於再次之战鬥之时，反遭张郃之伏兵，为张郃所刺杀。\n\n史：並无成为刘璋部下之记载。２１８年，与吴兰共同进攻武都，却遭曹操军歼灭，战败而死。\n\n",
