    "biography": "袁术之武将。\n\n演：参加纪灵所率领刘备讨伐军，却於吕布之仲裁下退兵。於其後之吕布讨伐战则率领第四军参加。却因友方之杨奉、韩暹向吕布倒戈因而大败。尔後，因对袁术之享乐行为大失所望，与陈兰共同死守於嵩山。於袁绍投靠之袁术败於刘备之後，即袭击袁术军，夺取其财物。\n\n史：於遭曹操败所之袁术前来投靠之时，与陈兰一同拒绝。尔後袁术将帝位让於袁绍，欲投靠青州之袁谭，但於途中死去。\n\n",
