    "biography": "蜀国武将。尔後效命於魏晋。罗蒙之子。罗袭之父。\n\n演：並无记载。\n\n史：於刘禅立刘璿为太子後，就任太子舍人。因不追随掌握政权之黄皓，故遭贬为巴东太守，成为都督·阎宇之副将。２６３年，於魏军入侵蜀国领地内时，阎宇受召重返中央後，接掌指挥阎宇之士兵防守永安。蜀国投降後，吴国陆抗、步协、留平、盛曼进攻而至之时，进行笼城逾半年以上，至晋国胡烈救援到达为止，成功地守护永安。因此功绩使其得以维持原职，为魏国效命。於晋朝时曾为冠军将军，攻陷吴国之巫城。\n\n",
