    "biography": "吴国武将。使用金色之斧。\n\n演：孙桓之武将。於刘备欲为关羽復仇，进攻荆州之时，於宜都予以迎击。同僚谢旌与张苞对战，並於谢旌屈於劣势之时前往救援。连战２０回合後，同僚之谭雄射中张苞之乘马，故使张苞落马。於举斧欲杀张苞之际，遭关兴砍杀。\n\n史：２１９年，於陆逊之指挥下与谢旌一同进攻荆州，击败詹晏等人，逮捕陈凤。２２１年，败於进攻荆州之蜀国之吴班、冯习。隔年，陆逊於夷陵大破蜀军之时，与刘阿共同追击至南山。\n\n",
