    "skills": [],
    "biography": "刘璋之武将。尔後服侍於刘备。\n\n演：刘璋向刘备求援时，提出反对但未受採纳。因对刘璋失望故转而效命於刘备，说服马超使其归顺。尔後，参加诸葛亮之北伐。\n\n史：受董和之推薦而前往州郡之途中，聽闻刘备攻击刘璋一事，预测刘璋必将败北而服侍於刘备。刘备殁後，於南方遭異民族之反叛军包围，但巧施计策突破包围網。协助诸葛亮镇压反叛。於诸葛亮殁後，平定再次掀起之反叛。将物资及人员送往成都，成为北伐之原动力。\n\n",
