    "biography": "董卓之武将。\n\n演：追随董卓进入洛阳，与郭汜一同防守汜水关。败於反董卓军後，向孙坚提议与董卓之女之婚事遭拒。於董卓遭王允讨伐後，採纳贾诩之献策，与郭汜、樊稠、张济等人共同袭击长安。杀王允拥献帝，就任车骑将军、司隶校尉。掌握政权。１９５年，因与郭汜决裂，致使长安荒废。於献帝逃出长安後，虽与郭汜联手追击献帝，但败於曹操。遭段煨讨伐。\n\n史：败於曹操所派遣之裴茂，遭处刑。\n\n",
