    "biography": "吴国武将。陆逊之次男。孙策之外孙。\n\n演：於孙休时代成为镇东大将军、荆州牧，一揽荆州战线全部军事。受孙皓攻略襄阳之命令，与晋国羊祜对阵。因互相认同彼此才能，赠酒予羊祜以表敬意。尔後，再次受攻略襄阳之命令，虽主张进攻晋国对吴国不利，却遭懷疑有内奸之嫌，故遭褫夺军权並降级。\n\n史：２７２年，於西陵讨伐谋反之步阐时，击退前来救援之羊祜。虽成为了大司马、荆州牧，但不久後病逝。並无演义中所描述之遭降格一事。\n\n",
