    "biography": "吴国官僚。「吴之四姓」陆家出身。陆康之子。陆逊之堂兄弟。\n\n演：６岁时与袁术见面，受盘问为何懷中有柑橘，其答道「我想要送给母亲」，使袁术为之感佩。孙策殁後，为孙权所採用。於赤壁之战前，欲试图以辩论战挑战为与孙权结盟而至吴国拜访之诸葛亮但失败。\n\n史：博学多闻，知晓天文、历法、算术，著有「浑天图」。因其自认为正确之事即毫无忌惮地发言惹恼孙权，故遭指派出任鬱林太守。\n\n",
