    "biography": "吴国武将。本名陆议。「吴之四姓」陆家出身。代替年少之堂兄弟·陆绩率领其一家族。陆抗之父。\n\n演：於孙策殁後，受招揽至孙权阵营。２１９年，发出陈言谦卑书信使关羽失之大意，支援吕蒙攻略荆州。於夷陵之战时，火攻刘备大军赢得勝利。於石亭之战亦击溃曹休，成为吴国之中流砥柱。\n\n史：少小丧父，故投靠亲族之陆康，陆康却为孙策所杀。於孙权时代得以和解，娶孙策之女为妻。其後，讨伐異民族表现傑出。２４４年，虽成为丞相，却因捲入孙和与孙霸继位者之争，悲愤而死。\n\n",
