    "biography": "刘璋之武将。尔後服侍於刘备。後改名为李平。\n\n演：与费观一同防守绵竹关。在刘备军进攻而来时进行防守战，虽与黄忠交战不分轩轾，最终於诸葛亮之包围下投降。说服费观释放绵竹关。诸葛亮评其「可媲美陆逊之人物」，於刘备殁後进入白帝城，留意防备吴国之动静。於诸葛亮之北伐中担任运送粮食之任务。２３１年之第四回北伐因不及调配兵粮，故散佈吴军来袭之伪报致使远征军返国，遭剥夺官职。２３４年，因诸葛亮之死使其復职无望，故悲愤而死。\n\n史：曾服侍刘表。因曹操侵略荆州逃往蜀国。\n\n",
