    "biography": "董卓之女婿、参谋。\n\n演：奉何进之命，与前往洛阳之董卓同行。暗杀少帝及何太后、迁都长安、没收富商财产等，暗地裡支持董卓暴政。於董卓为貂蝉而与吕布起争执之时，进言将貂蝉让予吕布。但董卓充耳不闻，故李儒感叹「莫非我等全员都将死於女人之手吗」。於董卓遭吕布杀害之後，即遭王允逮捕处刑。\n\n史：並无记载。\n\n",
