    "biography": "魏国之官僚。曹爽之心腹。\n\n演：於曹爽掌握政权後，成为河南尹参与政治。於转任荆州刺史之际，为探其病情拜访司马懿府。将佯装重病之司马懿演技信以为真，向曹爽报告「司马懿看来不久了」。获知此报告後曹爽失之大意外出围猎。於那段期间司马懿毅然夺取政权後，李勝遭逮捕处刑。\n\n史：被评为人风雅並具才智，与何晏同样受曹爽信用。但为曹叡所疏远，遭剥夺官职。\n\n",
