    "biography": "韩遂之武将。\n\n演：於马超及韩遂企图为马腾復仇而举兵之时，协助马超等人。攻下长安、潼关。但因马超及韩遂中贾诩之離间计关係决裂，於渭水之战中败北。尔後中于禁为射马超而放出之箭，战亡。\n\n史：东汉末，割据长安以西（关中）之军阀。於２１１年曹操讨伐张鲁之时，与马超、韩遂等人一同发动反叛，战亡。\n\n",
