    "biography": "曹操之武将。\n\n演：於曹操与张绣、刘表战鬥之时，派出援军拯救陷於绝境之曹操军，尔後即驻紮於汝南。２１１年，渭水之战与马超战鬥，数回合後遭刺死。\n\n史：於汝南与陈恭等人共同组织自卫团，活捉黄巾黨之吴霸，功绩卓越。於曹操迁都许昌後，臣服。於官渡之战时拒绝袁绍之邀约，平定袁绍出身地之汝南一带，而成为汝南太守。於南郡攻防战突破周瑜之包围網救出曹仁。２０９年，於远征後之归途上病亡。\n\n",
