    "biography": "袁尚之幕僚。尔後服侍於曹操。本姓为冯。\n\n演：受曹操包围於邺之时，伪装成曹操军之武将潜入城内。提议将平民放出城外，使防守邺之审配失之大意，进而由城内外夹攻曹操军之计策。\n\n史：受支配冀州之袁尚录用。於袁尚遭受曹操攻击，放弃邺逃往中山之时，因与袁尚分隔两地，故向袁谭投降。於袁谭遭曹操消灭後服侍於曹操。担任司隶校尉後，於阳平太守在任中时死亡。\n\n",
