    "biography": "蜀国武将。李严之子。\n\n演：於投降魏国之孟达对蜀提出要求内应时，担任孟达与诸葛亮之联络任务。２３１年，因其父李严无法顺利补给食粮，导致诸葛亮之远征失败遭罢免。代理其父受命为长史（丞相之属官）。\n\n史：２３０年，於李严为防止曹真之军力而出征汉中之时，代替其父担任江州都督督军之职。李严遭罢免之时，诸葛亮以「若与蒋琬协力从事职务，必可开启道路」一语予以鼓励。最後高升朱提太守。\n\n",
