    "biography": "袁术之武将。\n\n演：於由袁术发起之吕布讨伐战中以督战官身份参加。与吕布展开单挑，因惯用之手为枪所刺故逃走。其後立刻遭受曹操攻击，与乐就、梁纲、陈纪一同防守寿春。却力有未逮遭曹操军所捕，遭处死。\n\n史：１９７年，追随袁术，攻击曹操所支配之陈。但因袁术於聽闻曹操亲自迎击後逃走，故与桥蕤、梁纲、乐就一同担当後卫抗战。於败北後全员遭处刑。\n\n",
