    "biography": "东汉之幽州牧·刘虞之子。\n\n演：並无记载。\n\n史：以侍中身份服侍献帝。於迁都长安後，欲返洛阳之献帝命其催促刘虞出兵。於前往幽州途中拜访袁术，策劃欲藉刘虞及袁术之军力以期夺回献帝。但自刘虞处派遣而至之兵力却遭袁术夺取，自身亦遭袁术所逮捕。尔後虽自袁术处逃離，却遭受袁绍所拘留。\n\n",
