    "biography": "刘璋之武将。\n\n演：於刘璋因畏惧张鲁之侵略而向刘备请求救援之时，与张任共同反对。奉庞统命令之魏延佯装舞剑而欲砍杀刘璋之时，与张任等人一同阻止。当刘备夺下涪水关，进攻至刘璋之领地内时，与张任、冷苞、邓贤协力於雒城进行防卫战。於友方之将领接二连三投降时，欲持续战鬥至最後关头。但最後却遭部下张翼所杀，雒城则拱手让予刘备军。\n\n史：与张任、冷苞、邓贤共同於涪城迎击刘备军但惨遭击溃，而死守於绵竹。\n\n",
