    "biography": "荆州刺史刘表之长子。刘琮之兄。\n\n演：其母为陈氏。遭欲使刘琮成为继承者之继母蔡氏疏远。有感於自身生命危险，故聽从诸葛亮助言，出任江夏太守。於刘表临终时虽受指名为继承者，但因蔡瑁及蔡氏之阴谋，甚至无法见刘表临终一面，刘琮最终成为继承者。於刘琮对南下之曹操投降後，迎接逃亡而至之刘备。於赤壁之战後，虽成为荆州刺史，但不久後病亡。\n\n史：性格孝顺。欲前去探望重病之刘表，却遭蔡瑁及张允阻止，流著眼泪返回任地。\n\n",
