    "biography": "东汉之幽州牧。东海恭王刘彊（东汉光武帝之子）之子孙。刘和之父。\n\n演：为平定於渔阳进行反叛之张举、张纯，於是以幽州牧之身份赴任。於同刘备平定叛乱後，成为太尉。\n\n史：於皇族当中特显德高望重。於以幽州牧之身份赴任後，採融合政策统治东方異民族，使民心安定。於董卓拥立献帝後，虽曾受袁绍及韩馥推举为皇帝，但为表示对汉室之恭顺而拒绝。因统治異民族之策略相異，故与公孙瓒之间关係恶化。１９３年，与公孙瓒对战败北，遭处死刑。\n\n",
