    "biography": "袁术之武将。庐江太守。尔後效命曹操。\n\n演：１９９年，遭受孙策攻击，庐江被夺。\n\n史：於孙策击败陆康，平定庐江後，受袁术任命为庐江太守。於袁术战亡後，攻击前来投靠之杨弘、张勋並逮捕，保护袁术之妻。於惨败於孙策致使庐江遭夺後归顺曹操。因曾与曹丕一同喝酒等，妄自以为与曹操交好，故屡次犯法。甚至向司马芝请求放过其部下之过失。最後，因自身行不正之事受逮，遭受处刑。\n\n",
