    "biography": "零陵太守刘度之子。\n\n演：赤壁之战後，於刘备军攻入零陵时遣邢道荣迎击。待邢道荣战败返回之後，此回亲自出征欲对刘备军展开夜袭。却为诸葛亮所识破作战，而遭张飞逮捕。战後，於诸葛亮之说服下投降，於荆州担任军务。\n\n史：並无记载。\n\n",
