    "biography": "吴国武将。留略、留平之父。\n\n演：２５２年，於魏国之司马昭趁孙权死时进攻东兴之时，於诸葛恪之指挥下彻底防守对方之攻势。\n\n史：年轻之时即已成为郡之官员，讨伐黄巾黨首领吴桓。此时，虽单脚受重伤但自行治疗，尔後依然参与战列。受曾聽闻其评價之凌统推薦为吴国效命。２５２年，於东兴大败魏军，高升为左将军。２５５年，参加孙峻之淮南远征，却於到达寿春前发病，受命返回。於途中遭蒋班追击而战亡。\n\n",
