    "biography": "袁绍之侧室。袁尚之母。\n\n演：於官渡之战後，建议袁绍使袁尚成为继位者。２０２年，於袁绍殁後，与审配、逢纪共谋欲使袁尚成为继位者。秘密杀害袁绍之五位妻子。２０４年，於曹操击败袁尚平定邺之时，与甄氏同遭逮捕，受曹丕保护。\n\n史：因甄氏於丈夫袁熙赴任幽州之时亦滞留於邺，故与刘氏共同生活。於曹丕踏进袁尚之宅邸之时，自行缚绑双手表达恭顺之意。\n\n",
