    "biography": "益州牧刘璋之长子。刘阐之兄。其妻为庞羲之女。\n\n演：於刘备进攻益州之时，自願与吴懿、吴兰、雷铜一同负责雒城之守备。虽因张任等人之表现卓越，故得以屡次击退刘备军，但随著友方相继投降，便逐渐屈於劣势。最後，守将刘[0xFA][0x41]为张翼所杀後，城陷。单枪匹马脱逃返回成都。\n\n史：於雒城抵禦刘备军近一年。於刘璋降服於刘备後，成为奉车中郎将，於成都服侍刘备。因刘璋及其弟刘阐等人移住荆州，於关羽战亡後对吴国投降，以敌对之立场告分離。\n\n",
