    "biography": "益州牧刘焉之子。刘範、刘诞、刘瑁之弟。刘循之父。\n\n演：虽成为益州牧，但被评为愚昧之君主。於见张鲁有进攻益州之动静後，即向同族之刘备请求援军。但於不久後，与刘备成为敌对关係。２１４年，成都遭受包围，为不使民众受害而投降。与其妻一同移住荆州南郡之公安。\n\n史：其兄刘範、刘诞响应马腾之举兵而战亡。因刘瑁病亡故继承刘焉之位。因不遵从张鲁命令，致使其母及其弟遭杀害。於投降刘备後移住公安，但於关羽败於孙权後即向吴国投降。\n\n",
