    "biography": "魏国武将。\n\n演：２３４年，於孙权进攻魏国之时，奉曹叡之命前往防卫江夏，阻止陆逊之夹击作战。\n\n史：遵从诏敕参与将与五经关连之书籍，归纳整理之「皇览」之编纂。於曹叡即位後，著手制定魏国之法令，於整理「新律」十八篇之同时亦著作「律略论」。除此外亦製作评定官僚勤务基準之「都官考课」，通晓赋诗与音乐等多才多艺。２３３年，於孙权企图攻击合淝新城时，故意誇示即将有大军前往援救，不动一兵一卒逼退吴军。\n\n",
