    "biography": "吴国武将。\n\n演：於丞相孙綝欲施行暴政时，奉孙亮之命与全纪等人一同加入讨伐孙綝之计劃。但却因全纪之母（孙綝之表姊）密告致使计劃暴露，一族人满门抄斩。\n\n史：於吕据一同剿灭企图讨伐孙綝之滕胤。参加孙亮之孙綝杀害计劃但事迹败露，遭孙綝之弟·孙恩攻击死亡。此时於遇害者中另有刘承此一人物，但据闻与刘丞为同一人物。\n\n",
