    "biography": "刘禅之五男。刘璿之弟。北地王。\n\n演：於魏国邓艾攻下绵竹关逼近成都之时，责备主张投降之谯周，主张抗战。但因刘禅决定投降之故，遭待臣逐出。返家後向其妻崔氏曰「我将自尽谒见先帝（刘备），使其可知吾並未投降」。於崔氏先行自尽後，手刃其子三人进刘备之庙，尔後流著血泪自尽。\n\n史：与演义相同。\n\n",
