    "biography": "刘禅之长男。刘谌之兄。其母为王氏。\n\n演：蜀国向魏国投降後，捲入於成都企图独立而发起之锺会之叛乱，为魏国士兵所杀。\n\n史：２３８年，其１５岁之时成为皇太子。２６４年，捲入锺会之反叛，死亡。除於蜀国投降时自杀之刘谌外，其他兄弟皆与刘禅一同移住洛阳。\n\n",
