    "biography": "蜀国之第二代皇帝，後主。刘备之子。其母为甘氏。乳名阿斗则是由甘氏於懷胎之时，梦见吞下北斗七星之梦而来。\n\n演：於长阪坡之战由糜氏抱其逃亡，尔後为赵雲所救出。於孙氏（尚香）欲返吴国之时，欲挟持其至吴，但遭赵雲及张飞夺回。於刘备殁後，以第二代皇帝之身份即位。将政权委任於诸葛亮、蒋琬、费禕等人。尔後因起用宦官黄皓，导致政治荒废。１６３年，於邓艾包围成都时投降。翌年，被迫迁移至洛阳为安乐公，渡过长寿之一生。\n\n史：於後世，其乳名「阿斗」成为意指无能者之一词。\n\n",
