    "biography": "荆州刺史刘表之次男。刘琦之弟。其母为蔡氏。\n\n演：因聪明伶俐受刘表宠爱。刘表殁後，因蔡瑁及蔡氏伪造之遗言成为继位者。但因畏惧继承权遭横夺之刘琦及刘备之攻击，採傅巽等人之策略向曹操投降。於曹操进入荆州後，受命为青州刺史。於赴任途中遭于禁袭击，与蔡氏一同被杀。\n\n史：向曹操投降後赴任青州刺史，成为谏议大夫、参同军事。\n\n",
