    "biography": "东汉之兖州刺史。刘繇之兄。西汉齐孝王之末裔。\n\n演：呼应曹操之打倒董卓号召之联合诸侯之一。与董卓战鬥後，因向曾为同一联盟成员之桥瑁借调兵粮遭拒，故杀桥瑁夺取兵力。尔後成为曹操属下，刘备於下邳独立後，与王忠共同前往讨伐。虽遭张飞活捉但被释放，向曹操进言拥护刘备之时，险遭曹操斩首。\n\n史：虽受董卓任命为兖州刺史，但却与袁绍等人共同举兵反抗董卓。１９２年，於青州之黄巾黨攻击兖州之时，不採用鲍信之持久战建议进行出击，战亡。\n\n",
