    "biography": "刘璋之幕僚。尔後效命刘备。\n\n演：於刘璋欲招揽刘备以抵禦张鲁时提出反对。於刘璋向刘备投降後，与黄权一同拒绝为官。但因刘备亲身造访，大受感动而出仕。於诸葛亮之第一回北伐之时，以中参军之身份参加。\n\n史：自年轻之时即获名声，受刘表招揽但拒绝。於曹操支配荆州後出仕，並使长沙、零陵、桂阳归顺。於刘备支配三郡後，亡命至交趾，尔後移住蜀国。於刘备平定蜀国後，为亡命一事先行谢罪，受重用成为尚书令。\n\n",
