    "biography": "刘表之外甥。\n\n演：与黄忠一同防守长沙，刘备支配长沙之时隐居於攸县。受黄忠之推举为刘备所招揽，成为长沙太守。\n\n史：奉刘表之命，与黄忠一同防守长沙之攸县。生性勇猛屡次进攻艾、西安诸县，但受孙策指示太史慈抵禦之故，放弃攻击。\n\n",
