    "biography": "汉之中山靖王刘勝之子孙。蜀之昭烈皇帝。刘禅之父。\n\n演：於桃园三结义时与关羽、张飞结为义兄弟，於黄巾黨及董卓之讨伐战中表现傑出。虽受徐州牧陶谦之请求接掌其地位，却为吕布所夺，故投靠曹操。受献帝赐与皇叔称号，参与曹操暗杀计劃但事迹败露。故远走投靠袁绍及刘表。以三顾茅庐之礼迎请诸葛亮後，支配荆州益州建立起一大势力範围。自曹操处夺走汉中成为汉中王，於２２１年建蜀国。为报关羽之仇进攻吴国，但惨败於陆逊病亡。\n\n史：喜好狩猎及音乐，並重视自身之修养。\n\n",
