    "biography": "荆州刺史。西汉鲁国恭王之子孙。刘琦、刘琮之父。蔡氏为後母。与陈翔、孔昱等人並称之「江夏八俊」中之一人。\n\n演：於孙坚持玉玺脱離反董卓联盟之时，承诺袁绍之要求进行攻击。对此懷恨在心之孙坚於进攻之时迎击，並採蒯良之策讨伐孙坚。２０１年，收容逃亡而至之刘备，使其驻紮於新野。尔後病倒，指名长男刘琪为继位者。但於其死後，因蔡瑁之阴谋故使刘琮成为继位者，尔後刘琮向曹操投降。\n\n史：自年轻之时便以儒者有名。於黨锢之禁时逃亡而逃过一劫。於灵帝殁後成为荆州刺史。\n\n",
