    "biography": "曹操之扬州刺史。\n\n演：於扬州建立学校、实施屯田成功等功绩斐然。因於赤壁之战前指责曹操所咏唱之「短歌行」其中一节不吉，激怒曹操而被杀。\n\n史：说服袁术之属下戚奇与秦翊，一同为曹操效命。於曹操奔走於与袁绍一族之战争时，成为扬州刺史，处置梅乾、雷绪、陈兰之横行。尔後，进行建设学校、屯田、堤防及灌溉之整备、强化合淝之城墙等，功绩卓越。於２０８年死去。「短歌行」之逸事为演义之创作。\n\n",
