    "biography": "黄巾之武将。\n\n演：与龚都共同於汝南作乱，折磨苦恼前来讨伐之曹洪。於官渡之战时成为袁绍之友方，袭击曹操後方。於刘备自袁绍手中逃離後受招揽，共同企图於曹操不在之时进攻许昌。不料先受夏侯惇之袭击大败，遭高览讨伐。\n\n史：与何仪、黄邵、何曼等人一起共同於汝南、潁川两郡扩展势力、与袁术及孙策联手。１９６年，遭曹操讨伐而降服。於曹操与袁绍发生争鬥时，进行反叛成为袁绍之友方，与刘备联手。但最後败於曹仁。\n\n",
