    "biography": "樊城县令·刘泌之子。刘备之养子。本姓为寇。\n\n演：於刘备採纳徐庶之智略击溃曹仁进入樊城之时，因赏识刘封而认为养子。尔後，於博望坡之战、益州进攻战、汉中攻防战中表现傑出。於平定汉中後，与孟达、王平共同进攻上庸。尔後，受孤立於麦城之关羽向其请求援军，但受孟达之劝而拒绝。成为关羽战亡之因，遭刘备憎恨。２２０年，败於对魏投降之孟达，返回成都後遭处刑。\n\n史：与孟达感情不睦。性格刚勇。诸葛亮以刘备死後即无人可行牵制为由进言，赐死。\n\n",
