    "biography": "东汉之扬州刺史。刘岱之弟。西汉之齐之孝王末裔。\n\n演：聽闻同郡之太史慈之勇猛武艺，招揽至旗下。但於孙策进攻江东之时，因不採纳太史慈之助言而败退。最後逃亡投靠刘表。\n\n史：为避战乱迁往淮南居住後，被任命为扬州刺史。但因袁术早已在淮南之故，並无前往任地之寿春，於曲阿设立州都。尔後，驱赶吴景及孙贲，让樊能、张英等人防守扬子江沿岸，防止袁术之侵略攻击。於败给孙策後前往予章，讨伐反叛之笮融，但於不久後病亡。\n\n",
