    "biography": "吴国武将。留赞之子。留平之兄弟。\n\n演：２５２年，於司马昭趁孙权死亡进攻吴国之时，於丁奉之援军到来之前死守东兴之右城。\n\n史：２５２年，於诸葛恪之命令下防守东兴之右城，与西城之全端共同维持战线。尔後，於诸葛恪之指挥下击溃魏军。尔後成为东海太守。\n\n",
