    "biography": "袁绍之武将。\n\n演：於官渡之战中，跟随淳于琼防守乌巢之兵粮库。但因许攸背叛告知曹操兵粮库之所在地、亦因守将淳于琼亦醉倒，致使疏於守备，致使兵粮库遭曹操放火燃烧殆尽。\n\n史：防守乌巢。遭曹操袭击，与眭元进、韩莒子、赵叡等人一同遭砍杀。\n\n",
