    "biography": "黄巾之武将。尔後效命刘备。别名廖淳、廖惇。\n\n演：於关羽之千里行中登场，救出刘备夫人。於刘备将南荆州做为根据地後成为刘备之下属，与关羽共同防守荆州。２１９年，於关羽遭受包围於麦城之时，单枪匹马脱逃。向刘封及孟达请求援军但遭拒而返回成都。尔後，加入诸葛亮及姜维之北伐。２６３年，为防止邓艾与锺会之军力，与姜维並肩防守剑阁。但於成都遭攻陷後投降。不久後病亡。\n\n史：於关羽战亡後虽在吴国，但佯称死亡返回蜀国。於蜀国灭亡後，於受护送前往洛阳途中病亡。\n\n",
