    "biography": "韩遂之武将。\n\n演：为报遭曹操谋杀马腾之仇，故举兵协助马超及韩遂。攻打长安，进军至潼关。但因於渭水之战时中贾诩之離间计，致使马超及韩遂决裂，故而协议向曹操军投降。但协议地点为马超闯入，当场受斩身亡。\n\n史：东汉末，割据长安以西（关中）之军阀。於曹操举兵讨伐张鲁之时，与马超、韩遂等人共同发起反叛。於渭水之战败北後，逃亡並於各地进行掠夺，最後为夏侯渊所包围，遭砍杀身亡。\n\n",
