    "skills": [],
    "biography": "袁术之武将。演义中写为梁刚。\n\n演：於袁术发起吕布讨伐战时，与李豐、乐一同担任督战官，却遭杨奉、韩暹倒戈惨遭大败。亦遭受曹操之攻击，即与乐就、李豐、陈纪一同於寿春城进行防卫战。但可惜力有未逮，全员遭受逮捕受处刑。\n\n史：１９７年，追随袁术攻击曹操之陈。但因袁术於聽闻曹操亲自出征後即刻逃走之故，即与桥蕤、李豐、乐就共同成为殿後进行防守战。但无法抵抗曹操军之攻势，全军覆没。\n\n",
