    "biography": "魏国之并州刺史。\n\n演：並无记载。\n\n史：於曹操成为司空後，受聘历任各地方之县令，立下不少功绩。於曹操讨伐高幹，支配并州後成为并州刺史，且让匈奴们服从，维持边境地带之和平。於曹丕时代就任并州刺史。经营边境之功绩受评为天下第一。於曹叡时代重返中央，受命为大司农。\n\n",
