    "biography": "天水之武将。於效命魏国後，降於蜀国。\n\n演：姜维之友。於诸葛亮进攻天水之际，与降於蜀国之姜维取得连繫。与同僚尹赏因共同策劃进行开城门迎蜀军之功绩，受命为天水太守。\n\n史：於诸葛亮进攻天水之时，与姜维、梁虔、尹赏一同遭太守马遵懷疑别有二心。故於马遵逃走之际遭受遗弃，四人便一同降服於诸葛亮。虽最终升至大鸿胪，但於蜀灭亡之前即已身亡。\n\n",
