    "biography": "吴国武将。凌统之父。\n\n演：当严白虎因遭受孙策之讨伐，逃至余杭之时，率领居民们将之击溃，尔後为孙策效命。於孙权时代，江夏之黄祖进攻而来之际，虽一马当先杀入敌阵，却遭甘寧射杀。此事成为因缘，致使凌统视甘寧为仇敌企图杀之为快。\n\n史：於孙策举兵时成为其部下，於平定山越族具贡献。勇敢之性格经常驱使其冲向前线战鬥。２０３年，於孙权之指挥下攻击江夏之黄祖，身中流箭而亡。亦有一说是为身中甘寧之箭而亡。\n\n",
