    "biography": "吴国武将。凌操之子。\n\n演：於孙策讨伐严白虎时，与凌操共同迎接孙策。１５岁之时，於与黄祖之战鬥中凌操遭甘寧射杀，拼死收容其遗體。２０８年，於投诚之甘寧成功讨伐黄祖之庆功会上，试图为父报仇受阻。尔後参加赤壁之战、南郡攻防战。於逍遥津之战时挺身守卫孙权。尔後虽於濡须口攻防战时与张辽交战不分轩轾，但身中曹休之箭落马。於此危急之际遭受乐进狙击，因幸获甘寧拯救而终於得以和解。\n\n史：於出征中依然与贤者才人进行交流，重视信义。\n\n",
