    "biography": "蜀国官僚。\n\n演：因恃才傲物，因中伤未赐与崇高地位之诸葛亮，故遭贬为庶民。２３４年，诸葛亮阵亡於五丈原後，因失去受召回之希望而感叹。\n\n史：於刘备支配南荆州後，受赏识而成为长沙太守。受诸葛亮评为「与庞统並架齐驱，辅佐我功业之人」。２１５年，於长沙、零陵、桂阳遭吕蒙夺走後，脱逃並返回成都，就任巴郡太守。於刘备成为汉中王後受命为侍中，却於刘禅时代遭调为闲职，批判朝政而遭降为庶民。\n\n",
