    "biography": "蜀国官僚。\n\n演：为攻略南蛮，绘製军略图「平蛮指掌图」。２２５年，孟获攻入永昌郡之时，协助太守王伉进行笼城。於诸葛亮前来救援之际，递出「平蛮指掌图」，成为征讨南蛮之路线图。於孟获投降後，与王伉共同统治益州、越巂、牂牁、永昌四郡。\n\n史：刘备殁後，曾受与孙权联手发起反叛之雍闓再三请求成为友方但拒绝。诸葛亮前来救援时，称赞其之忠义，成为雲南太守。尔後遭发起叛乱之異族杀害。\n\n",
