    "biography": "曹操之武将。\n\n演：受刘晔之推薦，与满宠一同效命曹操，並推举毛玠。於与吕布之争战时射杀薛兰，对曹操之兖州夺返颇具贡献。其後，参与官渡之战、赤壁之战等战役。２２４年，於曹丕之吴国讨伐战以中护军之身份参战，却大吃败仗。\n\n史：受曹操任命成为泰山太守，组织精锐部队镇压济南之黄巾黨徐和。治理泰山十餘年，曹丕即位後升徐州刺史。将民政委任於德高望重之王祥，受世间之甚高评價。\n\n",
