    "biography": "袁尚之武将。後效命於曹操。於演义中为吕翔之兄长。\n\n演：於袁尚与袁谭争鬥时，以袁尚之先锋讨伐岑壁。但见袁谭与曹操联手，认为形势不利而投降。受曹操赐封为列侯，使袁尚阵营之马延等人归顺。於壶关佯装向高幹投降，让乐进、李典等人之伏兵策略得以成功。当曹操将目标放眼於荆州之时，於曹仁之指挥下欲攻击新野之刘备，却遭赵雲讨伐。\n\n史：於袁尚与袁谭争鬥後，与吕翔一同背叛袁尚，驻紮阳平。尔後向曹操投降。並无加入新野攻击之记载。\n\n",
