    "biography": "袁尚之武将。後效命曹操。於演义中为吕旷之弟。\n\n演：於袁尚与袁谭争鬥时，与吕旷一同担任先锋。但於得知袁谭曹操联手一事後投降。受曹操赐封为列侯。於壶关之战遵从荀攸之策，佯装投降引出高幹。於曹操开始南下後，做为曹仁之先锋攻击新野之刘备。郤反遭张飞所杀。\n\n史：於袁尚与袁谭争鬥之时，与吕旷一同離开袁尚向曹操投降。並无加入新野攻击之记载。\n\n",
