    "biography": "吴国武将。\n\n演：大司马。於孙权临终时，与诸葛恪一同被唤至床边託付後事。\n\n史：於孙权继承孙策後，就任地方官。２１５年，与吕蒙等人共起攻下长沙、零陵、桂阳，留滞长沙负责镇抚。２２０年，继承步骘就任交州刺史。於交趾太守士燮死後，杀士燮之子士徽，平定了交州。潘濬死後，与陆逊共同进入武昌防守荆州。於陆逊死後成为大将军，於孙亮时代则为大司马。\n\n",
