    "biography": "吴国重臣。吕据之父。\n\n演：原为袁术之下属。尔後支持投靠袁术之孙策，並支援孙策进军江东。赤壁之战後，筹备刘备与孙尚香之婚礼，计劃欲讨伐刘备。但遭赏识刘备之吴国太责难，将责任转嫁贾华。於讨伐关羽时占卜吉凶，预言将获勝利。２２２年，於曹丕攻击吴国时，击破曹修之军队。\n\n史：为避开战乱而前往寿春，因受孙策赏识成为其臣子。２２２年，於洞口与曹休战鬥後就任扬州牧。喜好豪华之服饰。\n\n",
