    "biography": "三国志之最强武将。成为丁原、董卓养子。\n\n演：自董卓处受赠赤兔马，杀丁原倒戈。人称「人中之吕布、马中之赤兔」，以无以伦比之强悍自豪。中王允之连环计圈套，为争夺貂蝉而弑董卓，却遭李傕等人夺走都城。其後投靠袁术、袁绍、张杨等人流浪各地，於曹操东征时趁虚而入强取兖州。於遭曹操追赶後，自保护自身之刘备手中夺取徐州。最终受曹操及刘备之联合军包围於下邳，遭部下之侯成等人背叛遭受处刑。\n\n史：与董卓之侍女私通，王允也参与此阴谋。\n\n",
