    "biography": "吴国武将。\n\n演：於孙策殁後效命於孙权。於参加赤壁之战、南郡攻略战後，进言於濡须口建築出城。吴军於合淝惨败之时，此出城发挥了助益。２１９年，聽从陆逊之策，促使关羽失之大意並攻下荆州。虽讨伐了关羽，但於不久後即为关羽之灵缠身，死亡。\n\n史：自孙策时代起为吴国效命。於受孙权建议钻究学问後得到了很高的学识，使得鲁肃为之惊叹「已非昔日之吴下阿蒙」。２１５年，攻下长沙、零陵、桂阳，让刘备承认湘水以东为吴国领地。於讨伐关羽後，不久後病殁。\n\n",
