    "biography": "空想之人物。吕布之女，以遗传其父之武勇自豪。\n\n演：並无记载。\n\n为吕布与严氏间所生之女孩。虽为吕布於为李傕所败，逃離长安之时遭遗留，但为庞舒藏匿後平安护送至吕布之处。尔後，虽与袁术之子曾有政治婚姻之谈，但於前往寿春途中被带回。当吕布於下邳遭曹操包围之时，婚事再次浮上檯面，但却为曹操及刘备所阻止。吕布死後，家族迁往许昌。\n\n史：並无记载。\n\n",
