    "biography": "刘璋之武将。\n\n演：警戒为防禦张鲁招揽而至之刘呗。於魏延佯装剑舞企图杀害刘璋之时，挺身成为剑舞对手予以阻挠。於刘璋与刘备之关係告决裂後，即与张任、刘[0xFA][0x41]、邓贤共同进行防守雒城。於战争之初与邓贤共同挑战刘备军，却为魏延所虏。此时诈降回到雒城。继而企图使涪江决堤以进行水攻，但於计劃实行前再次遭魏延所逮，此回则遭到处决。\n\n史：与刘[0xFA][0x41]、张任、邓贤共同於涪水关与刘备军战鬥。\n\n",
