    "biography": "曹操之幕僚。\n\n演：号梦梅居士，隐居於终南山。当曹操於渭水之战苦恼马超军之夜袭时，建议曹操利用寒气建造冰城。\n\n史：於年轻之时与曹操有段渊源。当诸侯发起打倒董卓之军队时，於荆州之北境聚集兵力与刘表结为同盟。尔後效命於曹操，必定参与及策劃军事、国家之大计。於讨伐马超之时亦立下卓越功绩，曹操评其为「子伯所立之策略，吾望尘莫及是也」。尔後因做出傲慢之发言，遭曹操处刑。\n\n",
