    "skills": [],
    "biography": "吴国武将。鲁肃之子。鲁睦之父。\n\n演：並无记载。\n\n史：受到濡须督·张承之赏识，被视为继承人。於孙休时代任武昌总督，孙皓时代则任夏口总督。常於在任地施行严厉公正之统治。於２７４年死去，由其子鲁睦继後。\n\n",
