    "skills": [],
    "biography": "东汉之第十四代皇帝。諡号献帝。灵帝之次子。其母为王氏。在位１８９～２２０年。\n\n演：於灵帝驾崩，少帝即位後，成为陈留王。不久後受董卓拥立而即位，强行迁都长安。虽於董卓死後受到李傕支配，但於脱離长安後受曹操保护，前往许昌。尔後政权为曹操所掌控，虽数次企图讨伐曹操，但皆告失败。２２０年，受魏王·曹丕逼迫禅让而退位。受封为山阳公，东汉灭亡。\n\n史：因其母王氏遭何皇后所杀，故由董太后抚养成人。\n\n",
    "aptitudes": {
      "spear": 0,
      "halberd": 0,
      "cavalry": 0,
      "archer": 0
    },
