    "skills": [],
    "biography": "东汉之第十三代皇帝·刘辩。灵帝之长子。其母为何进之妹何皇后。在位至１８９年止。\n\n演：於灵帝殁後，受伯父何进拥立即位。但不久後何进即遭十常侍所暗杀，受掌控政权之董卓贬为弘农王。尔後因董卓谋臣·李儒之故，致使其母何太后及其自身遭受毒杀。\n\n史：因被识为不具继承帝位之器量，故於灵帝在位之时未能受立为太子。於灵帝殁後，与宦官蹇硕所推举之刘协（日後之献帝）争夺继承帝位。但蹇硕遭何进所弑，故能顺利即位。\n\n",
