    "type": "spear",
    "formation": "front",
    "skills": [],
    "biography": "东汉道士。住於东方，往来於江东近处一带。\n\n演：使用符水治疗病患，推广信仰。於孙策款待袁绍之使者·陈震之时出现，因与会者敬重于吉更甚於孙策，孙策大为不悦。孙策命其祈雨，却於果真降雨之後，以使用妖术为由遭受处刑。不久後，孙策苦於于吉之亡灵纠缠，而英年早世。\n\n史：於曹操攻击许昌之时从军。为帮助苦於乾旱之士兵而祈雨，却使孙策大为不悦而遇害。\n\n",
