    "skills": [],
    "biography": "魏国方士。占卜名家。相貌醜陋，特異奇行。\n\n演：擅长人相术，能预知人之寿命。於曹操因左慈妖术患病时受召见，预知鲁肃之死、蜀军来袭，及许昌火灾。曹操虽欲赐恩赏，其以自身不具福德之相而婉拒。此时亦预知夏侯渊将战亡。尔後亦预知何晏及邓颺之失势。不久之後，二人即遭司马懿夺走政权。\n\n史：自幼少时即喜好观星，擅长「易经」等各式占卜。预知自身寿命为47～48岁，亦正中其预言於48岁时死去。\n\n",
