    "skills": [],
    "biography": "东汉末流行之批评人物大家。许靖之堂弟。\n\n演：评论曹操为「治世之能臣，乱世之奸雄」。\n\n史：因与堂兄许靖共同於月初（月旦）开办人物批评之会，故人物批评亦称「月旦评」。曹操受桥玄之推薦下拜访许劭，为许劭所赏识之缘故，因此曹操之名广为天下人知。对曹操之评论另有「清平之姦贼，乱世之英雄」。仕官於广陵徐孟玉之处後，道曰官府中充满清廉之士。其後，虽投靠扬州之刘繇，却因刘繇遭孙策攻击故逃亡至予章，於４６岁之时病逝。\n\n",
