    "skills": [],
    "biography": "东汉之方士。\n\n演：於峨嵋山得「遁甲天书」故学得仙术。人称乌角先生。吃掉孙权赠与曹操之温州柑子（橘子），对成为魏王之曹操大声放话道「快引退让位给刘备」，即使受拷问依然呼呼大睡，不断以奇言異行嘲笑曹操。不但轻鬆逃过曹操之通缉令，反让曹操身受病痛之苦。\n\n史：与华佗、甘始、郤俭等人同受喜好养生法之曹操招揽。於演义中戏弄曹操之情节，以晋朝葛洪所著之「神仙传」为基準而造出之角色。\n\n",
