    "biography": "东汉之隐士。人称水镜先生。以人物鑑定家闻名，与庞德公、庞统、徐庶、诸葛亮等人深交。\n\n演：藏匿因察觉蔡瑁暗杀计劃而逃走中之刘备，高唱军师之重要性。於当时虽推薦卧龙及凤雏，但並未明说为何者。尔後拜访刘备，於聽闻徐庶向刘备推薦诸葛亮（伏龙）後，低声咕哝说道「伏龙得主，但不逢时」。\n\n史：与新野之刘备会面，告知刘备近处有伏龙与凤雏，被问及为何人之时，答道为诸葛亮及庞统。２０８年，於曹操佔领荆州之时病逝。\n\n",
