    "biography": "东汉之名士。击鼓名手。\n\n演：当曹操建议禰衡归顺刘表之时，受孔融之推举接受使者任务。但於宴会之时，以与生俱来之毒舌痛斥曹操之部下，且裸體嘲笑激怒曹操。致使命其前往之刘表亦对其敬而远之，而被派至黄祖手下。尔後亦侮辱黄祖，因激怒黄祖而被杀。死後，由刘表葬其於鹦鹉洲。\n\n史：其虽因傲慢而怨声载道，但孔融予以好评。黄祖亦认同其才能，但终究因祸从口出而遭杀身之祸。遗留诗作「鹦鹉赋」，现於鹦鹉湖畔仍留有其墓。\n\n",
