    "biography": "东汉之名士。黄月英之父。诸葛亮之岳父。\n\n演：於前往与女婿诸葛亮见面时，巧遇同为欲会见诸葛亮之刘备，被误认为诸葛亮。２２２年，当陆逊迷失在诸葛亮於鱼腹浦所佈设之石兵八阵之际，因惜才而救出陆逊。\n\n史：对欲娶妻之诸葛亮推薦道「我有个醜女兒。虽红发黑皮肤，但其才能与你可说十分相配」。得诸葛亮之允诺後，以车将女兒送予诸葛亮。地方人们还流传「莫学孔明择妇」之笑谈。\n\n",
