    "biography": "东汉之太尉。将曹操评论为「天下将乱能安之者，其在君乎！」。\n\n演：常被误认为大乔小乔之父乔国老。乔国老两位女兒因分别嫁予孙策及周瑜，故被称为国老。２０９年，於刘备与孙尚香成亲之时，与吴国太同助其二人成婚及祝福。\n\n史：为人严正公明具才略，善於鑑定人物。虽於灵帝时代成为太尉，但因病辞职。其殁後，因家中无多餘财产而得名臣之称。曾建议曹操拜访许劭。\n\n",
