    "biography": "掌管死亡之神。身著白衣之老人姿态。\n\n演：於卜者·管辂之故事中登场。於和南斗下棋途中，因过於热衷竟吃光赵颜供出之酒肉。不得以只好将赵颜之寿命由１９岁延至９９岁，尔後与南斗一同变为白鹤後消失。诸葛亮於赤壁之战祈求东南风之时、於延长寿命仪式之时皆面向北斗七星进行祈祷。\n\n史：北斗七星为大熊星座之一部份。斗为杓柄之意。古代中国於埋葬死者之时，使其枕向北，於北方之位角绘有北斗七星。\n\n",
