    "biography": "掌管生育之神。身著红衣装扮美丽。\n\n演：於和北斗下棋途中，因吃下赵颜聽从管辂之主意所供之酒肉。尔後得知得他人之施与，不得已只好将赵颜之寿命由１９岁延至９９岁，尔後与北斗一同变为白鹤後消失。\n\n史：与北斗七星相对之南斗七星为射手座之一部份。为中国之星座·黄道二十八宿其中之一·斗宿。斗为杓子之意。\n\n",
