    "skills": [],
    "biography": "乌丸之武将。\n\n乌丸原称「东胡」。於西汉时代，虽匈奴之冒顿单于被灭，仍有部份倖存之人死守於乌丸山，因此被称为「乌丸」。擅於骑射，为寻找水源及牧草四处移居。以帐篷为家，狩猎鸟兽食其肉、饮奶酪、毛皮为衣。擅长武勇及指导能力者成为「大人」，率领部族。无固定姓氏，使用大人及勇者之姓氏。\n\n",
    "aptitudes": {
      "spear": 0,
      "halberd": 0,
      "cavalry": 2,
      "archer": 1
    },
