    "type": "halberd",
    "formation": "front",
    "skills": [],
    "biography": "山越之武将。\n\n山越为居住於杨子江南岸之山间民族之总称，因居於远離城镇之山中因而被取为此名。有短发纹身之习俗。於东汉末期，於汉族入侵江南後，即屡发争执。孙策及孙权认为欲进军北方，平定山越势在必行，故屡次以武力进行镇压。２３４年，丹阳太守·诸葛恪採懷柔之策，奖励其等下山加入屯田。因此多数之山越加入吴国之支配，势力因此衰退。\n\n",
    "aptitudes": {
      "spear": 1,
      "halberd": 2,
      "cavalry": 0,
      "archer": 1
    },
