    "skills": [],
    "biography": "东汉之宦官。中常侍。\n\n演：东汉末期执朝政牛耳之宦官集团「十常侍」之代表人物。因其施行恶政而导致黄巾之乱，将政敌刘陶、陈耽等人打入大牢並杀害。於灵帝殁後，虽险为何进所杀，因何皇后落泪哀求而倖免一死。其後，虽杀害了企图再次诛灭宦官之何进，却遭受何进部下之袁绍、曹操等人攻击，带少帝与陈留王（後来之献帝）脱逃。但最终因遭闵贡追至，而投河自尽。\n\n史：曹操曾入侵张让宅邸，但因曹操之武功異於常人，故无人可制止。\n\n",
