    "biography": "东汉宦官。中常侍。\n\n演：宦官集团「十常侍」之一。於东汉末期执朝政之牛耳。因其施行恶政而导致黄巾之乱。与董太后联手企图拥立协皇子（後来之献帝）即位，而欲杀政敌何进但失败。遭袁绍追讨，尔後遭同僚之郭勝所杀。\n\n史：於１８８年，担任西园八校尉之时，奉命任上军校尉，包括有袁绍、鲍鸿、曹操、赵融、冯芳、夏牟、淳于琼等校尉。\n\n",
